-- ===== SOURCE: pvp_tier.sql =====
-- ⚠ 다시 돌리지 마세요, 최신 아님 (일부): 이 파일의 _pvp_grant, pvp_report, pvp_status 는 뒤 파일에서 다시 정의됨. 이 파일을 다시 돌리면 예전 것으로 되돌아가요. supabase/README.md 참고
-- =====================================================================
-- PvP 티어 · 시즌 티어 보상 · 연승 보너스 (pvp.sql 다음에 실행). 여러 번 실행해도 안전.
--   티어(시즌 레이팅): 브론즈 <950 · 실버 950 · 골드 1050 · 플래티넘 1150 · 다이아 1250 · 심연 1400
--   시즌 티어 보상: 지난 시즌 3판 이상 → pvp_claim_tier 로 1회 (리그·모드·시즌별). 심연 = 한정 칭호·프레임(pvp_titles)
--   연승: 이번 시즌 연속 승리 3·5·10 달성 판의 결과 보고 때 서버가 바로 지급 (보고는 판당 1번 → 중복 없음)
--   연승 계산: 같은 리그·모드·시즌 기록에서 가장 최근 패배(미보고 판 = 패배) 이후 승리 수. 진행 중(1시간 안 미보고) 판은 제외
-- =====================================================================

-- 1) 표
create table if not exists public.pvp_tier_table (
  tier text primary key, ord int not null, min_rating int not null, reward jsonb not null);
insert into public.pvp_tier_table (tier, ord, min_rating, reward) values
  ('bronze',   0,    0, '{"gold":200}'),
  ('silver',   1,  950, '{"gold":400,"shard":5,"gem":50}'),
  ('gold',     2, 1050, '{"gold":800,"soul":5,"tickets":3,"gem":100}'),
  ('platinum', 3, 1150, '{"gold":1500,"soul":10,"tickets":5,"gem":200}'),
  ('diamond',  4, 1250, '{"gold":2500,"soul":20,"tickets":10,"gem":400}'),
  ('abyss',    5, 1400, '{"gold":4000,"soul":35,"tickets":20,"gem":1000,"title":"abyss"}')
on conflict (tier) do update set ord = excluded.ord, min_rating = excluded.min_rating, reward = excluded.reward;

create table if not exists public.pvp_streak_table (n int primary key, reward jsonb not null);
insert into public.pvp_streak_table (n, reward) values
  (3, '{"gold":300}'), (5, '{"gold":600,"soul":5}'), (10, '{"gold":1500,"soul":15,"tickets":3,"gem":30}')
on conflict (n) do update set reward = excluded.reward;

create table if not exists public.pvp_tier_claims (
  user_id uuid not null references auth.users(id) on delete cascade,
  league text not null, mode text not null, season date not null, tier text not null, rating int not null, reward jsonb not null,
  claimed_at timestamptz not null default now(), primary key (user_id, league, mode, season));
create table if not exists public.pvp_titles (
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null, league text not null, mode text not null, season date not null,
  granted_at timestamptz not null default now(), primary key (user_id, title, league, mode, season));
alter table public.pvp_attempts add column if not exists streak int;            -- 보고 시점 연승 (승리 판만)
alter table public.pvp_attempts add column if not exists streak_reward jsonb;   -- 연승 보너스 지급 내역

alter table public.pvp_tier_table enable row level security;
alter table public.pvp_streak_table enable row level security;
alter table public.pvp_tier_claims enable row level security;
alter table public.pvp_titles enable row level security;
drop policy if exists pvp_tier_read on public.pvp_tier_table;      create policy pvp_tier_read on public.pvp_tier_table for select using (true);
drop policy if exists pvp_streak_read on public.pvp_streak_table;  create policy pvp_streak_read on public.pvp_streak_table for select using (true);
drop policy if exists pvp_tier_claims_own on public.pvp_tier_claims; create policy pvp_tier_claims_own on public.pvp_tier_claims for select using (auth.uid() = user_id);
drop policy if exists pvp_titles_own on public.pvp_titles;         create policy pvp_titles_own on public.pvp_titles for select using (auth.uid() = user_id);
revoke insert, update, delete on public.pvp_tier_table, public.pvp_streak_table, public.pvp_tier_claims, public.pvp_titles from anon, authenticated;

-- 2) 내부 함수
create or replace function public._pvp_tier(p_rating int) returns text language sql stable set search_path = public as $$
  select tier from pvp_tier_table where min_rating <= coalesce(p_rating, 1000) order by min_rating desc limit 1 $$;
-- 보상 지급: gold/blood/shard/soul → 지갑, tickets → 소환권, title → pvp_titles
create or replace function public._pvp_grant(p_uid uuid, p_rw jsonb, p_reason text, p_league text, p_mode text, p_season date) returns void
language plpgsql security definer set search_path = public as $$
declare w jsonb := p_rw - 'tickets' - 'title' - 'gem';
begin
  if w <> '{}'::jsonb then perform _wallet_add(p_uid, w, p_reason); end if;
  if coalesce((p_rw->>'tickets')::int, 0) > 0 then
    insert into story_gacha (user_id, last_draw) values (p_uid, _pvp_day() - 1) on conflict (user_id) do nothing;
    update story_gacha set tickets = tickets + (p_rw->>'tickets')::int, updated_at = now() where user_id = p_uid;
  end if;
  if coalesce((p_rw->>'gem')::int, 0) > 0 and to_regprocedure('public._gem_add(uuid,integer,integer,text,text,jsonb)') is not null then   -- 심연석 (gem.sql)
    perform _gem_add(p_uid, (p_rw->>'gem')::int, 0, p_reason, case when p_reason = 'pvp_tier' then 'pvp_tier:' || p_league || ':' || p_mode || ':' || p_season end, jsonb_build_object('league', p_league, 'mode', p_mode, 'season', p_season));
  end if;
  if p_rw ? 'title' then
    insert into pvp_titles (user_id, title, league, mode, season) values (p_uid, p_rw->>'title', p_league, p_mode, p_season) on conflict do nothing;
  end if;
end $$;
-- 연승 (p_upto: 이 판 id 까지. null = 전부, 진행 중 판 제외)
create or replace function public._pvp_streak(p_uid uuid, p_league text, p_mode text, p_season date, p_upto bigint default null) returns int
language sql stable set search_path = public as $$
  select count(*)::int from pvp_attempts a
  where a.user_id = p_uid and a.league = p_league and a.mode = p_mode and a.season = p_season and a.win
    and (p_upto is null or a.id <= p_upto)
    and a.id > coalesce((select max(b.id) from pvp_attempts b where b.user_id = p_uid and b.league = p_league and b.mode = p_mode and b.season = p_season
                          and not b.win and (p_upto is null or b.id <= p_upto)
                          and (b.reported_at is not null or now() - b.created_at > interval '1 hour')), 0) $$;
revoke all on function public._pvp_tier(int), public._pvp_grant(uuid, jsonb, text, text, text, date), public._pvp_streak(uuid, text, text, date, bigint) from public, anon, authenticated;

-- 3) 상태: 기존 + 연승 · 심연 칭호 · 티어표 · 연승표 · 지난 시즌 미수령 티어 보상
create or replace function public.pvp_status(p_league text, p_mode text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); n int := _pvp_ok(p_league, p_mode); used int; r pvp_ratings; decks jsonb; prev pvp_ratings; pend jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  select count(*) into used from pvp_attempts where user_id = uid and league = p_league and mode = p_mode and day = _pvp_day();
  r := _pvp_rating(uid, p_league, p_mode);
  select coalesce(jsonb_agg(jsonb_build_object('slot', slot, 'uids', uids, 'cost', cost) order by slot), '[]'::jsonb) into decks
    from pvp_decks where user_id = uid and league = p_league and mode = p_mode;
  select * into prev from pvp_ratings where user_id = uid and league = p_league and mode = p_mode and season = _pvp_season() - 7;
  if prev.user_id is not null and prev.wins + prev.losses >= 3
     and not exists (select 1 from pvp_tier_claims where user_id = uid and league = p_league and mode = p_mode and season = prev.season) then
    pend := jsonb_build_object('season', prev.season, 'rating', prev.rating, 'tier', _pvp_tier(prev.rating));
  end if;
  return jsonb_build_object('left', greatest(0, 10 + _pvp_extra(uid, p_league, p_mode) - used), 'max', 10 + _pvp_extra(uid, p_league, p_mode), 'rating', r.rating, 'wins', r.wins, 'losses', r.losses,
    'def_wins', r.def_wins, 'def_losses', r.def_losses, 'decks', decks, 'need', n,
    'season', _pvp_season(), 'season_end', ((_pvp_season() + 7)::timestamp at time zone 'Asia/Seoul'),
    'tier', _pvp_tier(r.rating), 'streak', _pvp_streak(uid, p_league, p_mode, _pvp_season()),
    'abyss', exists (select 1 from pvp_titles where user_id = uid and title = 'abyss'),
    'tiers', (select jsonb_agg(jsonb_build_object('tier', tier, 'min', min_rating, 'reward', reward) order by ord) from pvp_tier_table),
    'streaks', (select jsonb_agg(jsonb_build_object('n', s.n, 'reward', s.reward) order by s.n) from pvp_streak_table s),
    'pending', pend);
end $$;

-- 4) 결과 보고: 기존 + 연승 계산·보너스 지급
create or replace function public.pvp_report(p_id bigint, p_wins int, p_losses int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); a pvp_attempts; n int; need int; v_win boolean; r int; sk int := 0; srw jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into a from pvp_attempts where id = p_id and user_id = uid for update;
  if a.id is null then raise exception 'not found'; end if;
  if a.reported_at is not null then raise exception 'already reported'; end if;
  if now() - a.created_at > interval '1 hour' then raise exception 'expired'; end if;
  n := _pvp_ok(a.league, a.mode); need := case when n = 3 then 2 else 1 end;
  if p_wins is null or p_losses is null or p_wins < 0 or p_losses < 0 or p_wins > need or p_losses > need
     or not (p_wins = need or p_losses = need) or (p_wins = need and p_losses = need) then raise exception 'bad result'; end if;
  v_win := p_wins = need;
  update pvp_attempts set reported_at = now(), wins = p_wins, losses = p_losses, win = v_win where id = p_id;
  if v_win then
    update pvp_ratings set rating = rating + a.dl + a.dw, wins = wins + 1, losses = losses - 1, updated_at = now()
      where user_id = uid and league = a.league and mode = a.mode and season = a.season;
    if a.opp_user is not null then
      update pvp_ratings set rating = rating - a.dl / 2 - a.dw / 2, def_wins = def_wins - 1, def_losses = def_losses + 1, updated_at = now()
        where user_id = a.opp_user and league = a.league and mode = a.mode and season = a.season;
    end if;
    sk := _pvp_streak(uid, a.league, a.mode, a.season, p_id);
    select reward into srw from pvp_streak_table where pvp_streak_table.n = sk;
    if srw is not null then perform _pvp_grant(uid, srw, 'pvp_streak', a.league, a.mode, a.season); end if;
    update pvp_attempts set streak = sk, streak_reward = srw where id = p_id;
    -- 조직 세력 (guild.sql): 승리당 +10 (하루 상한은 _guild_feed 가 처리)
    if to_regprocedure('public._guild_feed(uuid,text,integer)') is not null then perform _guild_feed(uid, 'pvp', 10); end if;
  end if;
  select rating into r from pvp_ratings where user_id = uid and league = a.league and mode = a.mode and season = a.season;
  return jsonb_build_object('ok', true, 'win', v_win, 'rating', r, 'delta', case when v_win then a.dw else -a.dl end,
    'tier', _pvp_tier(r), 'streak', sk, 'streak_reward', srw);
end $$;

-- 5) 랭킹: 기존 + 티어 · 심연 칭호
create or replace function public.pvp_rankings(p_league text, p_mode text, p_season date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); s date := coalesce(p_season, _pvp_season()); top jsonb; mine jsonb;
begin
  perform _pvp_ok(p_league, p_mode);
  with t as (select r.user_id, r.rating, r.wins, r.losses, rank() over (order by r.rating desc, r.wins desc) rk
             from pvp_ratings r where r.league = p_league and r.mode = p_mode and r.season = s and r.wins + r.losses > 0)
  select coalesce(jsonb_agg(jsonb_build_object('rank', rk, 'name', coalesce(p.nickname, '플레이어'), 'rating', rating, 'wins', wins, 'losses', losses,
           'me', t.user_id = uid, 'tier', _pvp_tier(rating), 'abyss', exists (select 1 from pvp_titles x where x.user_id = t.user_id and x.title = 'abyss')) order by rk), '[]'::jsonb)
    into top from (select * from t order by rk limit 100) t left join profiles p on p.id = t.user_id;
  with t as (select r.user_id, r.rating, r.wins, r.losses, rank() over (order by r.rating desc, r.wins desc) rk
             from pvp_ratings r where r.league = p_league and r.mode = p_mode and r.season = s and r.wins + r.losses > 0)
  select jsonb_build_object('rank', rk, 'rating', rating, 'wins', wins, 'losses', losses, 'tier', _pvp_tier(rating)) into mine from t where t.user_id = uid;
  return jsonb_build_object('season', s, 'top', top, 'me', mine);
end $$;

-- 6) 지난 시즌 티어 보상 받기 (리그·모드·시즌별 1회, 3판 이상)
create or replace function public.pvp_claim_tier(p_league text, p_mode text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); s date := _pvp_season() - 7; r pvp_ratings; t text; rw jsonb; ok boolean;
begin
  if uid is null then raise exception 'login required'; end if;
  perform _pvp_ok(p_league, p_mode);
  perform pg_advisory_xact_lock(hashtext('pvptier:' || uid::text));
  select * into r from pvp_ratings where user_id = uid and league = p_league and mode = p_mode and season = s;
  if r.user_id is null or r.wins + r.losses < 3 then raise exception 'not eligible'; end if;
  t := _pvp_tier(r.rating);
  select reward into rw from pvp_tier_table where tier = t;
  insert into pvp_tier_claims (user_id, league, mode, season, tier, rating, reward) values (uid, p_league, p_mode, s, t, r.rating, rw)
    on conflict do nothing returning true into ok;
  if not coalesce(ok, false) then raise exception 'already claimed'; end if;
  perform _pvp_grant(uid, rw, 'pvp_tier', p_league, p_mode, s);
  return jsonb_build_object('ok', true, 'season', s, 'tier', t, 'rating', r.rating, 'reward', rw);
end $$;

revoke all on function public.pvp_status(text, text), public.pvp_report(bigint, int, int), public.pvp_claim_tier(text, text) from public, anon;
grant execute on function public.pvp_status(text, text), public.pvp_report(bigint, int, int), public.pvp_claim_tier(text, text) to authenticated;
revoke all on function public.pvp_rankings(text, text, date) from public;
grant execute on function public.pvp_rankings(text, text, date) to anon, authenticated;


-- ===== SOURCE: gem.sql =====
-- =====================================================================
-- 심연석 🔮 (유료 재화) 1단계 — Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전
-- 선행: phaseE_1.sql(지갑) · phaseE_2.sql(행동력) · story_gacha.sql(소환권) · admin.sql · pvp.sql · pvp_tier.sql
-- 잔액: player_wallet.gem_paid(결제) + gem_free(무료). 화면에는 합계 하나. 사용은 무료 → 유료 순서
-- 쓰기는 전부 서버 함수로만: _gem_add / _gem_spend (클라이언트 호출 불가), 모든 변동은 gem_ledger 에 기록
--   gem_ledger.ref 는 유저별 고유 → 같은 보상(챕터·로그인·시즌 티어)·나중의 결제 주문이 두 번 들어가지 않음
-- 공개 RPC: gem_status() (챕터 첫 클리어·7일 연속 접속 보상 지급 포함) · gem_buy(item[, league, mode])
-- 관리자: admin_grant_gem(user, amount, reason) · admin_gem_ledger(user, limit)
-- 나중 결제: 결제 확인(Edge Function, service role)이 _gem_add(uid, 0, paid, 'iap', 'iap:<주문번호>', ...) 호출 → 환불은 같은 주문의 paid 만 회수
-- 확인용: select public.gem_status();
-- =====================================================================

-- 1) 잔액 (지갑에 열 추가)
alter table public.player_wallet add column if not exists gem_paid bigint not null default 0;
alter table public.player_wallet add column if not exists gem_free bigint not null default 0;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'player_wallet_gem_chk') then
    alter table public.player_wallet add constraint player_wallet_gem_chk check (gem_paid >= 0 and gem_free >= 0);
  end if;
end $$;

-- 2) 원장 (클라이언트 접근 불가 — 본인 기록은 gem_status 로만)
create table if not exists public.gem_ledger (
  id         bigint generated always as identity primary key,
  user_id    uuid not null references auth.users(id) on delete cascade,
  d_free     int not null default 0,
  d_paid     int not null default 0,
  free_after bigint not null,
  paid_after bigint not null,
  reason     text not null check (char_length(reason) <= 40),   -- chapter_clear · login_7 · pvp_tier · pvp_streak · buy:<item> · admin · iap · refund
  ref        text not null default gen_random_uuid()::text,       -- 고유 참조 (chapter:3 · login:2026-10-27 · pvp_tier:open:1v1:2026-10-19 · iap:<주문>)
  meta       jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (user_id, ref)
);
create index if not exists gem_ledger_user_idx on public.gem_ledger (user_id, created_at desc);
alter table public.gem_ledger enable row level security;
revoke all on public.gem_ledger from public, anon, authenticated;

-- 3) 상점 가격표 (한 곳에서 조정). step = 오늘 n번째 구매마다 가격 +step, daily_max = 하루 최대 (null = 무제한)
create table if not exists public.gem_shop (
  item      text primary key,
  ord       int not null default 0,
  price     int not null check (price > 0),
  step      int not null default 0 check (step >= 0),
  daily_max int,
  gives     jsonb not null,
  active    boolean not null default true
);
insert into public.gem_shop (item, ord, price, step, daily_max, gives) values
  ('ticket',   1,  150,  0, null, '{"tickets":1}'),
  ('pull10',   2, 1500,  0, null, '{"tickets":10}'),
  ('stamina',  3,  100, 50,    5, '{"stamina":"full"}'),
  ('pvp_try',  4,   50,  0,    3, '{"pvp_try":1}'),
  ('gold10k',  5,  100,  0, null, '{"gold":10000}')
on conflict (item) do update set ord = excluded.ord, price = excluded.price, step = excluded.step, daily_max = excluded.daily_max, gives = excluded.gives;
alter table public.gem_shop enable row level security;
revoke all on public.gem_shop from public, anon, authenticated;

-- 4) 연속 접속 (7일마다 +30)
create table if not exists public.gem_login (
  user_id  uuid primary key references auth.users(id) on delete cascade,
  last_day date not null,
  streak   int not null default 1
);
alter table public.gem_login enable row level security;
revoke all on public.gem_login from public, anon, authenticated;

-- 5) 내부 도우미
create or replace function public._gem_day() returns date language sql stable as $$ select (now() at time zone 'Asia/Seoul')::date $$;
create or replace function public._gem_chapter_reward() returns int language sql immutable as $$ select 50 $$;
create or replace function public._gem_login_reward() returns int language sql immutable as $$ select 30 $$;

-- 증감 (양수 = 지급). p_ref 가 이미 있으면 아무것도 안 하고 null (중복 방지). 잔액 부족이면 'not enough gem' 예외 → 전체 롤백
create or replace function public._gem_add(p_uid uuid, p_free int, p_paid int, p_reason text, p_ref text, p_meta jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare w player_wallet; f bigint; p bigint;
begin
  if p_uid is null then raise exception 'login required'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'reason required'; end if;
  if coalesce(p_free, 0) = 0 and coalesce(p_paid, 0) = 0 then return null; end if;
  insert into player_wallet (user_id) values (p_uid) on conflict (user_id) do nothing;
  select * into w from player_wallet where user_id = p_uid for update;
  if p_ref is not null and exists (select 1 from gem_ledger where user_id = p_uid and ref = p_ref) then return null; end if;
  f := w.gem_free + coalesce(p_free, 0); p := w.gem_paid + coalesce(p_paid, 0);
  if f < 0 or p < 0 then raise exception 'not enough gem'; end if;
  update player_wallet set gem_free = f, gem_paid = p, updated_at = now() where user_id = p_uid;
  insert into gem_ledger (user_id, d_free, d_paid, free_after, paid_after, reason, ref, meta)
  values (p_uid, coalesce(p_free, 0), coalesce(p_paid, 0), f, p, left(btrim(p_reason), 40), coalesce(p_ref, gen_random_uuid()::text), coalesce(p_meta, '{}'::jsonb));
  return jsonb_build_object('gem', f + p, 'free', f, 'paid', p, 'd_free', coalesce(p_free, 0), 'd_paid', coalesce(p_paid, 0));
end $$;

-- 사용: 무료 먼저, 모자라면 유료
create or replace function public._gem_spend(p_uid uuid, p_amount int, p_reason text, p_meta jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare w player_wallet; fp int;
begin
  if p_amount is null or p_amount <= 0 then raise exception 'invalid amount'; end if;
  insert into player_wallet (user_id) values (p_uid) on conflict (user_id) do nothing;
  select * into w from player_wallet where user_id = p_uid for update;
  if w.gem_free + w.gem_paid < p_amount then raise exception 'not enough gem'; end if;
  fp := least(w.gem_free, p_amount)::int;
  return _gem_add(p_uid, -fp, -(p_amount - fp), p_reason, null, p_meta);
end $$;

-- 오늘(KST) 이 상품을 몇 번 샀는지
create or replace function public._gem_bought(p_uid uuid, p_item text) returns int language sql stable security definer set search_path = public as $$
  select count(*)::int from gem_ledger where user_id = p_uid and reason = 'buy:' || p_item and created_at >= (_gem_day()::timestamp at time zone 'Asia/Seoul') $$;

-- 화면용 상태: 잔액 · 상점(오늘 가격·남은 횟수) · 최근 20건
create or replace function public._gem_json(p_uid uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare w player_wallet;
begin
  select * into w from player_wallet where user_id = p_uid;
  return jsonb_build_object('ok', true, 'gem', coalesce(w.gem_free, 0) + coalesce(w.gem_paid, 0), 'free', coalesce(w.gem_free, 0), 'paid', coalesce(w.gem_paid, 0),
    'shop', (select coalesce(jsonb_agg(jsonb_build_object('item', s.item, 'price', s.price + s.step * least(b.n, coalesce(s.daily_max, b.n)), 'gives', s.gives,
                     'left', case when s.daily_max is null then null else greatest(0, s.daily_max - b.n) end) order by s.ord), '[]'::jsonb)
             from gem_shop s cross join lateral (select _gem_bought(p_uid, s.item) n) b where s.active),
    'log', (select coalesce(jsonb_agg(jsonb_build_object('d', x.d_free + x.d_paid, 'after', x.free_after + x.paid_after, 'reason', x.reason, 'at', x.created_at) order by x.id desc), '[]'::jsonb)
            from (select * from gem_ledger where user_id = p_uid order by id desc limit 20) x),
    'login_streak', coalesce((select streak from gem_login where user_id = p_uid and last_day >= _gem_day() - 1), 0));
end $$;

-- 무료 획득 동기화: 챕터 첫 클리어(+50, 소급 포함) · 7일 연속 접속(+30). 반환 새로 받은 목록
create or replace function public._gem_sync(p_uid uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare d jsonb; ch int; r jsonb; out jsonb := '[]'::jsonb; lg gem_login; today date := _gem_day();
begin
  select data into d from story_progress where user_id = p_uid;
  if d is not null then
    for ch in
      select c.chapter from story_phase_config c group by c.chapter
      having bool_and(case when jsonb_typeof(d->'cleared'->(c.chapter::text)) = 'array'
                           then (d->'cleared'->(c.chapter::text)) @> to_jsonb(c.phase) or (d->'cleared'->(c.chapter::text)) @> to_jsonb(c.phase::text) else false end)
      order by c.chapter
    loop
      r := _gem_add(p_uid, _gem_chapter_reward(), 0, 'chapter_clear', 'chapter:' || ch, jsonb_build_object('chapter', ch));
      if r is not null then out := out || jsonb_build_array(jsonb_build_object('reason', 'chapter_clear', 'chapter', ch, 'gem', _gem_chapter_reward())); end if;
    end loop;
  end if;
  insert into gem_login (user_id, last_day, streak) values (p_uid, today - 1, 0) on conflict (user_id) do nothing;
  select * into lg from gem_login where user_id = p_uid for update;
  if lg.last_day < today then
    lg.streak := case when lg.last_day = today - 1 then lg.streak + 1 else 1 end;
    update gem_login set last_day = today, streak = lg.streak where user_id = p_uid;
    if lg.streak % 7 = 0 then
      r := _gem_add(p_uid, _gem_login_reward(), 0, 'login_7', 'login:' || today, jsonb_build_object('streak', lg.streak));
      if r is not null then out := out || jsonb_build_array(jsonb_build_object('reason', 'login_7', 'streak', lg.streak, 'gem', _gem_login_reward())); end if;
    end if;
  end if;
  return out;
end $$;
revoke all on function public._gem_add(uuid, int, int, text, text, jsonb), public._gem_spend(uuid, int, text, jsonb), public._gem_bought(uuid, text),
  public._gem_json(uuid), public._gem_sync(uuid) from public, anon, authenticated;

-- 6) 공개 RPC
-- 내 심연석 (+ 무료 획득 지급). 반환 { ok, gem, free, paid, shop, log, login_streak, granted:[...] }
create or replace function public.gem_status() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); g jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('gem:' || uid::text));
  g := _gem_sync(uid);
  return _gem_json(uid) || jsonb_build_object('granted', g);
end $$;

-- 구매. 가격·지급량은 서버 표(gem_shop)가 기준 (클라이언트는 상품 키만 보냄). pvp_try 는 리그·모드 필요
-- 오류: invalid item · daily limit · not enough gem · stamina full · (pvp) invalid league/mode
create or replace function public.gem_buy(p_item text, p_league text default null, p_mode text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); s gem_shop; n int; price int; res jsonb := '{}'::jsonb; ps player_state; mx int; t int;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('gem:' || uid::text));
  select * into s from gem_shop where item = p_item and active;
  if s.item is null then raise exception 'invalid item'; end if;
  n := _gem_bought(uid, s.item);
  if s.daily_max is not null and n >= s.daily_max then raise exception 'daily limit'; end if;
  price := s.price + s.step * n;
  -- 지급 조건 먼저 확인 (실패하면 심연석도 안 빠짐)
  if s.item = 'stamina' then
    ps := _player_sync(uid); mx := _stamina_max(ps.level);
    if ps.stamina >= mx then raise exception 'stamina full'; end if;
  elsif s.item = 'pvp_try' then
    perform _pvp_ok(p_league, p_mode);
  end if;
  perform _gem_spend(uid, price, 'buy:' || s.item, jsonb_build_object('price', price, 'gives', s.gives) || case when s.item = 'pvp_try' then jsonb_build_object('league', p_league, 'mode', p_mode) else '{}'::jsonb end);
  if s.gives ? 'tickets' then
    insert into story_gacha (user_id, last_draw) values (uid, _gem_day() - 1) on conflict (user_id) do nothing;
    update story_gacha set tickets = tickets + (s.gives->>'tickets')::int, updated_at = now() where user_id = uid returning tickets into t;
    res := res || jsonb_build_object('tickets', t);
  end if;
  if s.gives ? 'gold' then res := res || jsonb_build_object('wallet', _wallet_add(uid, jsonb_build_object('gold', (s.gives->>'gold')::int), 'gem_buy')); end if;
  if s.gives ? 'stamina' then res := res || jsonb_build_object('stamina', _player_stamina_add(uid, mx)); end if;
  if s.gives ? 'pvp_try' then
    insert into pvp_bonus_tries (user_id, league, mode, day, n) values (uid, p_league, p_mode, _pvp_day(), 1)
      on conflict (user_id, league, mode, day) do update set n = pvp_bonus_tries.n + 1;
    res := res || jsonb_build_object('pvp_extra', _pvp_extra(uid, p_league, p_mode));
  end if;
  return _gem_json(uid) || res || jsonb_build_object('item', s.item, 'price', price);
end $$;
revoke all on function public.gem_status(), public.gem_buy(text, text, text) from public, anon;
grant execute on function public.gem_status(), public.gem_buy(text, text, text) to authenticated;

-- 7) 지갑 상태에 심연석 추가 (합계 gem + 내역 분리)
create or replace function public.wallet_status() returns jsonb language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); w player_wallet;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into w from player_wallet where user_id = uid;
  return jsonb_build_object('ok', true, 'gold', coalesce(w.gold, 0), 'blood', coalesce(w.blood, 0), 'shard', coalesce(w.shard, 0), 'soul', coalesce(w.soul, 0),
    'gem', coalesce(w.gem_free, 0) + coalesce(w.gem_paid, 0), 'gem_free', coalesce(w.gem_free, 0), 'gem_paid', coalesce(w.gem_paid, 0));
end $$;
revoke all on function public.wallet_status() from public, anon;
grant execute on function public.wallet_status() to authenticated;

-- 8) 관리자: 무료 심연석 지급(+)/회수(−) · 원장 보기
create or replace function public.admin_grant_gem(p_user uuid, p_amount int, p_reason text) returns jsonb language plpgsql volatile security definer set search_path = public, auth as $$
declare bef bigint; res jsonb;
begin
  perform public._admin_guard();
  if p_amount is null or p_amount = 0 or abs(p_amount) > 1000000 then raise exception 'amount must be ±1..1000000'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'reason required'; end if;
  if not exists (select 1 from auth.users where id = p_user) then raise exception 'no such user'; end if;
  select coalesce(gem_free, 0) + coalesce(gem_paid, 0) into bef from player_wallet where user_id = p_user;
  bef := coalesce(bef, 0);
  res := public._gem_add(p_user, p_amount, 0, 'admin', null, jsonb_build_object('by', auth.jwt()->>'email', 'memo', left(btrim(p_reason), 200)));
  insert into public.admin_log (admin_id, admin_email, action, target_user, amount, reason, before_val, after_val)
  values (auth.uid(), auth.jwt()->>'email', 'grant_gem', p_user, p_amount, left(btrim(p_reason), 200), least(bef, 2147483647)::int, least((res->>'gem')::bigint, 2147483647)::int);
  return jsonb_build_object('ok', true, 'before', bef, 'after', (res->>'gem')::bigint, 'free', (res->>'free')::bigint, 'paid', (res->>'paid')::bigint);
end $$;
create or replace function public.admin_gem_ledger(p_user uuid, p_limit int default 50) returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
declare w player_wallet;
begin
  perform public._admin_guard();
  select * into w from player_wallet where user_id = p_user;
  return jsonb_build_object('gem', coalesce(w.gem_free, 0) + coalesce(w.gem_paid, 0), 'free', coalesce(w.gem_free, 0), 'paid', coalesce(w.gem_paid, 0),
    'log', coalesce((select jsonb_agg(jsonb_build_object('d_free', x.d_free, 'd_paid', x.d_paid, 'free_after', x.free_after, 'paid_after', x.paid_after, 'reason', x.reason, 'ref', x.ref, 'meta', x.meta, 'at', x.created_at) order by x.id desc)
                     from (select * from gem_ledger where user_id = p_user order by id desc limit least(greatest(coalesce(p_limit, 50), 1), 500)) x), '[]'::jsonb));
end $$;
revoke all on function public.admin_grant_gem(uuid, int, text), public.admin_gem_ledger(uuid, int) from public, anon;
grant execute on function public.admin_grant_gem(uuid, int, text), public.admin_gem_ledger(uuid, int) to authenticated;


-- 9) PvP 연동 (pvp.sql / pvp_tier.sql 과 같은 정의 — 이 파일만 실행해도 되도록 복사. tools/test_gem_sql.mjs 가 일치 확인)
--    추가 도전권(pvp_bonus_tries) · 시즌 티어/10연승 보상에 심연석
-- 추가 도전권 (gem.sql 의 심연석 구매로 늘어남). 오늘(KST) 리그·모드별 추가 횟수
create table if not exists public.pvp_bonus_tries (
  user_id uuid not null references auth.users(id) on delete cascade, league text not null, mode text not null, day date not null,
  n int not null default 0 check (n >= 0), primary key (user_id, league, mode, day));
alter table public.pvp_bonus_tries enable row level security;
revoke all on public.pvp_bonus_tries from public, anon, authenticated;
create or replace function public._pvp_extra(p_uid uuid, p_league text, p_mode text) returns int language sql stable security definer set search_path = public as $$
  select coalesce((select n from pvp_bonus_tries where user_id = p_uid and league = p_league and mode = p_mode and day = (now() at time zone 'Asia/Seoul')::date), 0) $$;
revoke all on function public._pvp_extra(uuid, text, text) from public, anon, authenticated;
create or replace function public.pvp_start(p_league text, p_mode text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); n int := _pvp_ok(p_league, p_mode); used int; me pvp_ratings; mine jsonb := '[]'::jsonb; d record;
        opp uuid; oname text; orat int; osnap jsonb := '[]'::jsonb; seed bigint; ex numeric; dw int; dl int; aid bigint;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('pvp:' || uid::text));
  select count(*) into used from pvp_attempts where user_id = uid and league = p_league and mode = p_mode and day = _pvp_day();
  if used >= 10 + _pvp_extra(uid, p_league, p_mode) then raise exception 'no attempts left'; end if;
  if (select count(*) from pvp_decks where user_id = uid and league = p_league and mode = p_mode) < n then raise exception 'deck required'; end if;
  for d in select * from pvp_decks where user_id = uid and league = p_league and mode = p_mode order by slot loop
    mine := mine || jsonb_build_array(_pvp_snap(uid, d.uids, p_league)->'cards');
  end loop;
  me := _pvp_rating(uid, p_league, p_mode);
  -- 상대: 덱을 다 등록한 다른 유저 중 레이팅이 가까운 쪽 (약간의 무작위)
  select x.user_id, coalesce(r.rating, 1000) into opp, orat from (
      select user_id from pvp_decks where league = p_league and mode = p_mode and user_id <> uid group by user_id having count(*) >= n) x
    left join pvp_ratings r on r.user_id = x.user_id and r.league = p_league and r.mode = p_mode and r.season = _pvp_season()
    order by abs(coalesce(r.rating, 1000) - me.rating) + random() * 60 limit 1;
  if opp is not null then
    select coalesce(jsonb_agg(snap order by slot), '[]'::jsonb) into osnap from pvp_decks where user_id = opp and league = p_league and mode = p_mode and slot < n;
    select coalesce(nickname, '플레이어') into oname from profiles where id = opp;
    oname := coalesce(oname, '플레이어');
  else
    -- 상대 없음: 내 덱 거울 봇 (레벨 -10%)
    select coalesce(jsonb_agg((select coalesce(jsonb_agg(c || jsonb_build_object('level', greatest(1, round(coalesce((c->>'level')::int, 1) * 0.9)::int), 'boost', '{}'::jsonb)), '[]'::jsonb)
                               from jsonb_array_elements(dk) c)), '[]'::jsonb) into osnap from jsonb_array_elements(mine) dk;
    oname := '봇'; orat := me.rating;
  end if;
  ex := 1 / (1 + power(10, (orat - me.rating) / 400.0));
  dw := greatest(1, round(32 * (1 - ex))::int); dl := greatest(1, round(32 * ex)::int);
  if opp is null then dw := greatest(1, dw / 2); dl := greatest(1, dl / 2); end if;   -- 봇전은 절반
  seed := floor(random() * 2147483647)::bigint;
  insert into pvp_attempts (user_id, league, mode, season, day, opp_user, opp_name, seed, my_snap, opp_snap, my_rating, opp_rating, dw, dl)
  values (uid, p_league, p_mode, _pvp_season(), _pvp_day(), opp, oname, seed, mine, osnap, me.rating, orat, dw, dl) returning id into aid;
  update pvp_ratings set rating = rating - dl, losses = losses + 1, updated_at = now() where user_id = uid and league = p_league and mode = p_mode and season = _pvp_season();
  if opp is not null then perform _pvp_rating(opp, p_league, p_mode);
    update pvp_ratings set rating = rating + dl / 2, def_wins = def_wins + 1, updated_at = now() where user_id = opp and league = p_league and mode = p_mode and season = _pvp_season(); end if;
  return jsonb_build_object('id', aid, 'seed', seed, 'me', mine, 'opp', osnap, 'opp_name', oname, 'opp_rating', orat, 'rating', me.rating, 'dw', dw, 'dl', dl, 'left', 9 + _pvp_extra(uid, p_league, p_mode) - used, 'bot', opp is null);
end $$;
revoke all on function public.pvp_start(text, text) from public, anon;
grant execute on function public.pvp_start(text, text) to authenticated;
create or replace function public._pvp_grant(p_uid uuid, p_rw jsonb, p_reason text, p_league text, p_mode text, p_season date) returns void
language plpgsql security definer set search_path = public as $$
declare w jsonb := p_rw - 'tickets' - 'title' - 'gem';
begin
  if w <> '{}'::jsonb then perform _wallet_add(p_uid, w, p_reason); end if;
  if coalesce((p_rw->>'tickets')::int, 0) > 0 then
    insert into story_gacha (user_id, last_draw) values (p_uid, _pvp_day() - 1) on conflict (user_id) do nothing;
    update story_gacha set tickets = tickets + (p_rw->>'tickets')::int, updated_at = now() where user_id = p_uid;
  end if;
  if coalesce((p_rw->>'gem')::int, 0) > 0 and to_regprocedure('public._gem_add(uuid,integer,integer,text,text,jsonb)') is not null then   -- 심연석 (gem.sql)
    perform _gem_add(p_uid, (p_rw->>'gem')::int, 0, p_reason, case when p_reason = 'pvp_tier' then 'pvp_tier:' || p_league || ':' || p_mode || ':' || p_season end, jsonb_build_object('league', p_league, 'mode', p_mode, 'season', p_season));
  end if;
  if p_rw ? 'title' then
    insert into pvp_titles (user_id, title, league, mode, season) values (p_uid, p_rw->>'title', p_league, p_mode, p_season) on conflict do nothing;
  end if;
end $$;
revoke all on function public._pvp_grant(uuid, jsonb, text, text, text, date) from public, anon, authenticated;
create or replace function public.pvp_status(p_league text, p_mode text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); n int := _pvp_ok(p_league, p_mode); used int; r pvp_ratings; decks jsonb; prev pvp_ratings; pend jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  select count(*) into used from pvp_attempts where user_id = uid and league = p_league and mode = p_mode and day = _pvp_day();
  r := _pvp_rating(uid, p_league, p_mode);
  select coalesce(jsonb_agg(jsonb_build_object('slot', slot, 'uids', uids, 'cost', cost) order by slot), '[]'::jsonb) into decks
    from pvp_decks where user_id = uid and league = p_league and mode = p_mode;
  select * into prev from pvp_ratings where user_id = uid and league = p_league and mode = p_mode and season = _pvp_season() - 7;
  if prev.user_id is not null and prev.wins + prev.losses >= 3
     and not exists (select 1 from pvp_tier_claims where user_id = uid and league = p_league and mode = p_mode and season = prev.season) then
    pend := jsonb_build_object('season', prev.season, 'rating', prev.rating, 'tier', _pvp_tier(prev.rating));
  end if;
  return jsonb_build_object('left', greatest(0, 10 + _pvp_extra(uid, p_league, p_mode) - used), 'max', 10 + _pvp_extra(uid, p_league, p_mode), 'rating', r.rating, 'wins', r.wins, 'losses', r.losses,
    'def_wins', r.def_wins, 'def_losses', r.def_losses, 'decks', decks, 'need', n,
    'season', _pvp_season(), 'season_end', ((_pvp_season() + 7)::timestamp at time zone 'Asia/Seoul'),
    'tier', _pvp_tier(r.rating), 'streak', _pvp_streak(uid, p_league, p_mode, _pvp_season()),
    'abyss', exists (select 1 from pvp_titles where user_id = uid and title = 'abyss'),
    'tiers', (select jsonb_agg(jsonb_build_object('tier', tier, 'min', min_rating, 'reward', reward) order by ord) from pvp_tier_table),
    'streaks', (select jsonb_agg(jsonb_build_object('n', s.n, 'reward', s.reward) order by s.n) from pvp_streak_table s),
    'pending', pend);
end $$;
revoke all on function public.pvp_status(text, text) from public, anon;
grant execute on function public.pvp_status(text, text) to authenticated;
insert into public.pvp_tier_table (tier, ord, min_rating, reward) values
  ('bronze',   0,    0, '{"gold":200}'),
  ('silver',   1,  950, '{"gold":400,"shard":5,"gem":50}'),
  ('gold',     2, 1050, '{"gold":800,"soul":5,"tickets":3,"gem":100}'),
  ('platinum', 3, 1150, '{"gold":1500,"soul":10,"tickets":5,"gem":200}'),
  ('diamond',  4, 1250, '{"gold":2500,"soul":20,"tickets":10,"gem":400}'),
  ('abyss',    5, 1400, '{"gold":4000,"soul":35,"tickets":20,"gem":1000,"title":"abyss"}')
on conflict (tier) do update set ord = excluded.ord, min_rating = excluded.min_rating, reward = excluded.reward;
insert into public.pvp_streak_table (n, reward) values
  (3, '{"gold":300}'), (5, '{"gold":600,"soul":5}'), (10, '{"gold":1500,"soul":15,"tickets":3,"gem":30}')
on conflict (n) do update set reward = excluded.reward;


-- ===== SOURCE: guild.sql =====
-- ⚠ 다시 돌리지 마세요, 최신 아님 (일부): 이 파일의 _guild_feed, guild_shop_buy 는 뒤 파일에서 다시 정의됨. 이 파일을 다시 돌리면 예전 것으로 되돌아가요. supabase/README.md 참고
-- =====================================================================
-- [조직] 1단계 (길드 코어) — Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전
-- 선행: phaseE_1.sql(지갑) · phaseE_2.sql(레벨·행동력) · gem.sql(심연석) · admin.sql · pvp.sql · pvp_tier.sql
-- 역할: 보스(boss) · 간부(officer) · 조직원(member). 개인 재화: 충성 (loyalty_wallet + loyalty_ledger)
-- 창설: 계정 Lv.15+ · 골드 50,000 또는 심연석 300 (기존 _wallet_add / _gem_spend 로 차감)
-- 세력(조직 EXP): 스토리(행동력 6 = 1, 하루 100) · PvP 승리 +10 (하루 100). 기여한 만큼 본인 충성 +
-- 탈퇴 후 24시간 가입 불가 · 추방된 조직은 72시간 재가입 불가 · 추방 하루 5명
-- 쓰기는 전부 서버 함수로만. 테이블은 클라이언트 접근 불가 (RLS + revoke)
-- 나중 단계: 집결(출석) · 의뢰(퀘스트) · 토벌(레이드) · 전쟁 → _guild_exp / _loyalty_add 를 호출해 연결
-- 확인용: select public.guild_status();
-- =====================================================================

-- 1) 테이블
create table if not exists public.guild_level_table (
  level int primary key, exp_total bigint not null, max_members int not null, officers int not null, unlock text);
insert into public.guild_level_table (level, exp_total, max_members, officers, unlock) values
  (1, 0, 15, 1, '기본 상점'), (2, 1000, 18, 2, null), (3, 3000, 21, 2, '상점 확장'), (4, 7000, 24, 3, '토벌 (준비 중)'), (5, 15000, 27, 3, '엠블럼 프레임'),
  (6, 30000, 30, 4, '전쟁 (준비 중)'), (7, 60000, 33, 4, null), (8, 120000, 36, 5, null), (9, 240000, 38, 5, null), (10, 480000, 40, 5, null)
on conflict (level) do update set exp_total = excluded.exp_total, max_members = excluded.max_members, officers = excluded.officers, unlock = excluded.unlock;

create table if not exists public.guilds (
  id          bigint generated always as identity primary key,
  name        text not null,
  name_key    text not null unique,                 -- lower(name) — 대소문자 무시 중복 금지
  emblem      int not null default 1 check (emblem between 1 and 12),
  intro       text not null default '' check (char_length(intro) <= 60),
  notice      text not null default '' check (char_length(notice) <= 100),
  join_mode   text not null default 'open' check (join_mode in ('open', 'approval', 'closed')),
  level       int not null default 1,
  exp         bigint not null default 0 check (exp >= 0),
  boss        uuid not null references auth.users(id),
  renamed_at  timestamptz,
  created_at  timestamptz not null default now()
);
create table if not exists public.guild_members (
  user_id       uuid primary key references auth.users(id) on delete cascade,   -- 한 사람 한 조직
  guild_id      bigint not null references public.guilds(id) on delete cascade,
  role          text not null default 'member' check (role in ('boss', 'officer', 'member')),
  joined_at     timestamptz not null default now(),
  loyalty_total bigint not null default 0,           -- 이 조직에서 쌓은 충성 (누적, 순위용)
  seen_at       timestamptz not null default now()
);
create index if not exists guild_members_gid on public.guild_members (guild_id);
create table if not exists public.guild_requests (
  id         bigint generated always as identity primary key,
  guild_id   bigint not null references public.guilds(id) on delete cascade,
  user_id    uuid not null references auth.users(id) on delete cascade,
  kind       text not null check (kind in ('apply', 'invite')),
  status     text not null default 'pending' check (status in ('pending', 'accepted', 'rejected', 'cancelled')),
  by_user    uuid,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '3 days'
);
create unique index if not exists guild_requests_pending on public.guild_requests (guild_id, user_id, kind) where status = 'pending';
create table if not exists public.guild_cooldowns (
  user_id  uuid not null references auth.users(id) on delete cascade,
  guild_id bigint not null default 0,                -- 0 = 모든 조직 (탈퇴), 그 외 = 그 조직만 (추방)
  until    timestamptz not null,
  primary key (user_id, guild_id)
);
create table if not exists public.guild_log (
  id bigint generated always as identity primary key, guild_id bigint, actor uuid, action text not null, target uuid, meta jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists guild_log_gid on public.guild_log (guild_id, created_at desc);
create table if not exists public.guild_exp_log (
  id bigint generated always as identity primary key, guild_id bigint not null, user_id uuid, amount int not null, src text not null,
  day date not null, ref text not null default gen_random_uuid()::text, created_at timestamptz not null default now(), unique (guild_id, ref));
create index if not exists guild_exp_log_day on public.guild_exp_log (user_id, day, src);
create table if not exists public.loyalty_wallet (
  user_id uuid primary key references auth.users(id) on delete cascade, balance bigint not null default 0 check (balance >= 0), updated_at timestamptz not null default now());
create table if not exists public.loyalty_ledger (
  id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, delta int not null, after bigint not null,
  reason text not null check (char_length(reason) <= 40), ref text not null default gen_random_uuid()::text, meta jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(), unique (user_id, ref));
create index if not exists loyalty_ledger_user on public.loyalty_ledger (user_id, created_at desc);
create table if not exists public.guild_shop (
  item text primary key, ord int not null default 0, price int not null check (price > 0), gives jsonb not null,
  limit_kind text check (limit_kind in ('day', 'week', 'once')), limit_n int, min_level int not null default 1, active boolean not null default true);
insert into public.guild_shop (item, ord, price, gives, limit_kind, limit_n, min_level) values
  ('ticket',    1,  300, '{"tickets":1}',          'week', 2,    1),
  ('stamina30', 2,  100, '{"stamina":30}',         'day',  1,    1),
  ('gold5k',    3,   80, '{"gold":5000}',          null,   null, 1),
  ('shard5',    4,  150, '{"shard":5}',            null,   null, 3),
  ('soul3',     5,  150, '{"soul":3}',             null,   null, 3),
  ('frame',     6, 2000, '{"title":"guild_frame"}', 'once', 1,   5)
on conflict (item) do update set ord = excluded.ord, price = excluded.price, gives = excluded.gives, limit_kind = excluded.limit_kind, limit_n = excluded.limit_n, min_level = excluded.min_level;
create table if not exists public.guild_titles (user_id uuid not null references auth.users(id) on delete cascade, title text not null, created_at timestamptz not null default now(), primary key (user_id, title));

do $$ declare t text; begin
  foreach t in array array['guild_level_table', 'guilds', 'guild_members', 'guild_requests', 'guild_cooldowns', 'guild_log', 'guild_exp_log', 'loyalty_wallet', 'loyalty_ledger', 'guild_shop', 'guild_titles'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
  end loop;
end $$;

-- 2) 수치
create or replace function public._guild_day() returns date language sql stable as $$ select (now() at time zone 'Asia/Seoul')::date $$;
create or replace function public._guild_min_level() returns int language sql immutable as $$ select 15 $$;
create or replace function public._guild_cost_gold() returns int language sql immutable as $$ select 50000 $$;
create or replace function public._guild_cost_gem() returns int language sql immutable as $$ select 300 $$;
create or replace function public._guild_rename_gem() returns int language sql immutable as $$ select 500 $$;
create or replace function public._guild_feed_cap(p_src text) returns int language sql immutable as $$ select case p_src when 'story' then 100 when 'pvp' then 100 else 1000 end $$;

-- 3) 내부 도우미
create or replace function public._guild_lock(p_gid bigint) returns void language sql as $$ select pg_advisory_xact_lock(hashtext('guild:' || p_gid)) $$;
create or replace function public._guild_me(p_uid uuid) returns guild_members language sql stable security definer set search_path = public as $$
  select * from guild_members where user_id = p_uid $$;
create or replace function public._guild_name_ok(p_name text) returns text language plpgsql immutable as $$
declare n text := btrim(coalesce(p_name, '')); w text;
begin
  if n !~ '^[가-힣A-Za-z0-9]{2,8}$' then raise exception 'bad name'; end if;
  foreach w in array array['운영', '관리자', 'admin', 'gm', '시발', '씨발', '병신', '좆', '섹스', '느금', '애미', '애비', '지랄', '꺼져', 'fuck', 'shit', 'sex'] loop
    if position(w in lower(n)) > 0 then raise exception 'bad name'; end if;
  end loop;
  return n;
end $$;
create or replace function public._guild_text_ok(p_text text, p_max int) returns text language plpgsql immutable as $$
declare t text := btrim(coalesce(p_text, '')); w text;
begin
  if char_length(t) > p_max then raise exception 'too long'; end if;
  foreach w in array array['시발', '씨발', '병신', '좆', '섹스', '느금', '애미'] loop
    if position(w in t) > 0 then raise exception 'bad word'; end if;
  end loop;
  return t;
end $$;
create or replace function public._guild_log(p_gid bigint, p_actor uuid, p_action text, p_target uuid, p_meta jsonb) returns void language sql security definer set search_path = public as $$
  insert into guild_log (guild_id, actor, action, target, meta) values (p_gid, p_actor, p_action, p_target, coalesce(p_meta, '{}'::jsonb)) $$;
-- 쿨타임 확인: 탈퇴(전체) 또는 이 조직에서 추방
create or replace function public._guild_cd_check(p_uid uuid, p_gid bigint) returns void language plpgsql stable security definer set search_path = public as $$
declare u timestamptz;
begin
  select max(until) into u from guild_cooldowns where user_id = p_uid and guild_id in (0, coalesce(p_gid, 0)) and until > now();
  if u is not null then raise exception 'cooldown until %', to_char(u at time zone 'Asia/Seoul', 'MM-DD HH24:MI'); end if;
end $$;
-- 멤버 추가 (조직 잠금 상태에서 호출). 인원·중복·쿨타임 확인, 이 사람의 다른 대기 신청은 취소
create or replace function public._guild_add_member(p_gid bigint, p_uid uuid, p_by uuid) returns void language plpgsql security definer set search_path = public as $$
declare g guilds; cnt int; mx int;
begin
  select * into g from guilds where id = p_gid;
  if g.id is null then raise exception 'no such guild'; end if;
  if exists (select 1 from guild_members where user_id = p_uid) then raise exception 'already in guild'; end if;
  perform _guild_cd_check(p_uid, p_gid);
  select count(*) into cnt from guild_members where guild_id = p_gid;
  select max_members into mx from guild_level_table where level = g.level;
  if cnt >= coalesce(mx, 15) then raise exception 'guild full'; end if;
  insert into guild_members (user_id, guild_id, role) values (p_uid, p_gid, 'member');
  update guild_requests set status = 'cancelled' where user_id = p_uid and status = 'pending';
  perform _guild_log(p_gid, coalesce(p_by, p_uid), 'join', p_uid, '{}');
end $$;
-- 충성 증감 (+ 획득, − 사용). p_ref 중복이면 null. 부족하면 'not enough loyalty'
create or replace function public._loyalty_add(p_uid uuid, p_delta int, p_reason text, p_ref text, p_meta jsonb) returns bigint language plpgsql security definer set search_path = public as $$
declare b bigint;
begin
  if coalesce(p_delta, 0) = 0 then return null; end if;
  insert into loyalty_wallet (user_id) values (p_uid) on conflict (user_id) do nothing;
  select balance into b from loyalty_wallet where user_id = p_uid for update;
  if p_ref is not null and exists (select 1 from loyalty_ledger where user_id = p_uid and ref = p_ref) then return null; end if;
  b := b + p_delta;
  if b < 0 then raise exception 'not enough loyalty'; end if;
  update loyalty_wallet set balance = b, updated_at = now() where user_id = p_uid;
  insert into loyalty_ledger (user_id, delta, after, reason, ref, meta) values (p_uid, p_delta, b, left(p_reason, 40), coalesce(p_ref, gen_random_uuid()::text), coalesce(p_meta, '{}'::jsonb));
  if p_delta > 0 then update guild_members set loyalty_total = loyalty_total + p_delta where user_id = p_uid; end if;
  return b;
end $$;
-- 세력(조직 EXP) 추가 + 레벨업. p_ref 중복이면 0. 반환 실제 추가량
create or replace function public._guild_exp(p_gid bigint, p_uid uuid, p_n int, p_src text, p_ref text) returns int language plpgsql security definer set search_path = public as $$
declare g guilds; lv int;
begin
  if coalesce(p_n, 0) <= 0 then return 0; end if;
  select * into g from guilds where id = p_gid for update;
  if g.id is null then return 0; end if;
  if p_ref is not null and exists (select 1 from guild_exp_log where guild_id = p_gid and ref = p_ref) then return 0; end if;
  insert into guild_exp_log (guild_id, user_id, amount, src, day, ref) values (p_gid, p_uid, p_n, p_src, _guild_day(), coalesce(p_ref, gen_random_uuid()::text));
  select max(level) into lv from guild_level_table where exp_total <= g.exp + p_n;
  update guilds set exp = exp + p_n, level = greatest(level, coalesce(lv, 1)) where id = p_gid;
  if coalesce(lv, 1) > g.level then perform _guild_log(p_gid, null, 'level_up', null, jsonb_build_object('level', lv)); end if;
  return p_n;
end $$;
-- 활동 → 세력 + 본인 충성 (하루 상한). 조직이 없으면 아무것도 안 함. 스토리/PvP 함수에서 호출
create or replace function public._guild_feed(p_uid uuid, p_src text, p_n int) returns int language plpgsql security definer set search_path = public as $$
declare m guild_members; used int; n int;
begin
  select * into m from guild_members where user_id = p_uid;
  if m.user_id is null or coalesce(p_n, 0) <= 0 then return 0; end if;
  if p_src = 'pvp' and to_regprocedure('public._guild_event(uuid,text,integer)') is not null then perform _guild_event(p_uid, 'pvp_win', 1); end if;   -- 조직 의뢰 (guild2.sql)
  select coalesce(sum(amount), 0) into used from guild_exp_log where user_id = p_uid and day = _guild_day() and src = p_src;
  n := least(p_n, _guild_feed_cap(p_src) - used);
  if n <= 0 then return 0; end if;
  perform _guild_exp(m.guild_id, p_uid, n, p_src, null);
  perform _loyalty_add(p_uid, n, 'feed:' || p_src, null, jsonb_build_object('guild', m.guild_id));
  return n;
end $$;
-- 조직 요약 / 상세 JSON
create or replace function public._guild_card(p_gid bigint) returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', g.id, 'name', g.name, 'emblem', g.emblem, 'intro', g.intro, 'join_mode', g.join_mode, 'level', g.level,
    'members', (select count(*) from guild_members where guild_id = g.id), 'max_members', (select max_members from guild_level_table where level = g.level),
    'boss_name', (select coalesce(nickname, '보스') from profiles where id = g.boss))
  from guilds g where g.id = p_gid $$;
create or replace function public._guild_shop_left(p_uid uuid, s guild_shop) returns int language sql stable security definer set search_path = public as $$
  select case when s.limit_kind is null then null else greatest(0, s.limit_n - (select count(*)::int from loyalty_ledger l where l.user_id = p_uid and l.reason = 'shop:' || s.item
    and l.created_at >= case s.limit_kind when 'day' then (_guild_day()::timestamp at time zone 'Asia/Seoul')
                                          when 'week' then (date_trunc('week', _guild_day()::timestamp) at time zone 'Asia/Seoul') else '-infinity'::timestamptz end)) end $$;
revoke all on function public._guild_lock(bigint), public._guild_me(uuid), public._guild_log(bigint, uuid, text, uuid, jsonb), public._guild_cd_check(uuid, bigint),
  public._guild_add_member(bigint, uuid, uuid), public._loyalty_add(uuid, int, text, text, jsonb), public._guild_exp(bigint, uuid, int, text, text),
  public._guild_feed(uuid, text, int), public._guild_card(bigint), public._guild_shop_left(uuid, guild_shop) from public, anon, authenticated;

-- 4) 공개 RPC
-- 내 조직 상태. 조직 없음: { ok, guild:null, list, invites, applies, cooldown, can_create, cost } / 있음: { ok, guild, me, members, requests, shop, levels, log, loyalty }
create or replace function public.guild_status() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; g guilds; lv int; cd timestamptz; res jsonb; lt guild_level_table; nx guild_level_table;
begin
  if uid is null then raise exception 'login required'; end if;
  update guild_requests set status = 'cancelled' where status = 'pending' and expires_at < now() and (user_id = uid or guild_id = (select guild_id from guild_members where user_id = uid));
  select coalesce((select level from player_state where user_id = uid), 1) into lv;
  res := jsonb_build_object('ok', true, 'loyalty', coalesce((select balance from loyalty_wallet where user_id = uid), 0), 'my_level', lv);
  m := _guild_me(uid);
  if m.user_id is null then
    select max(until) into cd from guild_cooldowns where user_id = uid and guild_id = 0 and until > now();
    return res || jsonb_build_object('guild', null, 'cooldown', cd, 'min_level', _guild_min_level(), 'cost', jsonb_build_object('gold', _guild_cost_gold(), 'gem', _guild_cost_gem()),
      'list', (select coalesce(jsonb_agg(_guild_card(x.id) order by x.lv desc, x.n desc), '[]'::jsonb) from (
                 select g2.id, g2.level lv, (select count(*) from guild_members where guild_id = g2.id) n from guilds g2 where g2.join_mode <> 'closed' order by g2.level desc, g2.exp desc limit 20) x),
      'invites', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'guild', _guild_card(r.guild_id)) order by r.id desc), '[]'::jsonb) from guild_requests r where r.user_id = uid and r.kind = 'invite' and r.status = 'pending'),
      'applies', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'guild', _guild_card(r.guild_id)) order by r.id desc), '[]'::jsonb) from guild_requests r where r.user_id = uid and r.kind = 'apply' and r.status = 'pending'));
  end if;
  update guild_members set seen_at = now() where user_id = uid;
  select * into g from guilds where id = m.guild_id;
  select * into lt from guild_level_table where level = g.level;
  select * into nx from guild_level_table where level = g.level + 1;
  return res || jsonb_build_object(
    'guild', _guild_card(g.id) || jsonb_build_object('notice', g.notice, 'exp', g.exp, 'exp_cur', lt.exp_total, 'exp_next', nx.exp_total, 'officers_max', lt.officers, 'boss', g.boss),
    'me', jsonb_build_object('role', m.role, 'joined_at', m.joined_at, 'loyalty_total', m.loyalty_total,
      'today', (select coalesce(jsonb_object_agg(src, s), '{}'::jsonb) from (select src, sum(amount) s from guild_exp_log where user_id = uid and day = _guild_day() group by src) t),
      'can_claim', m.role <> 'boss' and exists (select 1 from guild_members b where b.guild_id = g.id and b.role = 'boss' and b.seen_at < now() - interval '14 days')),
    'members', (select coalesce(jsonb_agg(jsonb_build_object('user_id', gm.user_id, 'name', coalesce(p.nickname, '조직원'), 'role', gm.role, 'loyalty_total', gm.loyalty_total,
                  'joined_at', gm.joined_at, 'seen_at', gm.seen_at,
                  'card', (select o->>'id' from story_progress sp, jsonb_array_elements(coalesce(sp.data->'owned', '[]'::jsonb)) o where sp.user_id = gm.user_id and o->>'uid' = sp.data->>'leader' limit 1))
                order by case gm.role when 'boss' then 0 when 'officer' then 1 else 2 end, gm.loyalty_total desc), '[]'::jsonb)
                from guild_members gm left join profiles p on p.id = gm.user_id where gm.guild_id = g.id),
    'requests', case when m.role in ('boss', 'officer') then (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'user_id', r.user_id, 'name', coalesce(p.nickname, '플레이어'),
                  'level', coalesce((select level from player_state where user_id = r.user_id), 1)) order by r.id), '[]'::jsonb)
                from guild_requests r left join profiles p on p.id = r.user_id where r.guild_id = g.id and r.kind = 'apply' and r.status = 'pending') else '[]'::jsonb end,
    'shop', (select coalesce(jsonb_agg(jsonb_build_object('item', s.item, 'price', s.price, 'gives', s.gives, 'min_level', s.min_level, 'left', _guild_shop_left(uid, s),
                'owned', s.limit_kind = 'once' and exists (select 1 from guild_titles t where t.user_id = uid and t.title = s.gives->>'title')) order by s.ord), '[]'::jsonb) from guild_shop s where s.active),
    'levels', (select jsonb_agg(jsonb_build_object('level', level, 'exp', exp_total, 'members', max_members, 'officers', officers, 'unlock', unlock) order by level) from guild_level_table),
    'log', (select coalesce(jsonb_agg(jsonb_build_object('action', l.action, 'actor', (select nickname from profiles where id = l.actor), 'target', (select nickname from profiles where id = l.target), 'meta', l.meta, 'at', l.created_at) order by l.id desc), '[]'::jsonb)
            from (select * from guild_log where guild_id = g.id order by id desc limit 20) l));
end $$;

-- 조직 찾기 (이름 검색, 비공개 제외)
create or replace function public.guild_search(p_q text) returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'login required'; end if;
  return (select coalesce(jsonb_agg(_guild_card(g.id) order by g.level desc, g.exp desc), '[]'::jsonb) from (
    select * from guilds where name_key like '%' || lower(replace(replace(btrim(coalesce(p_q, '')), '%', ''), '_', '')) || '%' order by level desc, exp desc limit 20) g);
end $$;

-- 창설: p_pay = 'gold' | 'gem'
create or replace function public.guild_create(p_name text, p_emblem int, p_intro text, p_join text, p_pay text) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); n text; gid bigint; lv int;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('guilduser:' || uid::text));
  select coalesce((select level from player_state where user_id = uid), 1) into lv;
  if lv < _guild_min_level() then raise exception 'level required %', _guild_min_level(); end if;
  if exists (select 1 from guild_members where user_id = uid) then raise exception 'already in guild'; end if;
  perform _guild_cd_check(uid, 0);
  n := _guild_name_ok(p_name);
  if p_emblem is null or p_emblem not between 1 and 12 then raise exception 'bad emblem'; end if;
  if coalesce(p_join, 'open') not in ('open', 'approval', 'closed') then raise exception 'bad join mode'; end if;
  perform pg_advisory_xact_lock(hashtext('guildname:' || lower(n)));
  if exists (select 1 from guilds where name_key = lower(n)) then raise exception 'name taken'; end if;
  if p_pay = 'gold' then perform _wallet_add(uid, jsonb_build_object('gold', -_guild_cost_gold()), 'guild_create');
  elsif p_pay = 'gem' then perform _gem_spend(uid, _guild_cost_gem(), 'guild_create', jsonb_build_object('name', n));
  else raise exception 'bad pay'; end if;
  insert into guilds (name, name_key, emblem, intro, join_mode, boss) values (n, lower(n), p_emblem, _guild_text_ok(p_intro, 60), coalesce(p_join, 'open'), uid) returning id into gid;
  insert into guild_members (user_id, guild_id, role) values (uid, gid, 'boss');
  update guild_requests set status = 'cancelled' where user_id = uid and status = 'pending';
  perform _guild_log(gid, uid, 'create', null, jsonb_build_object('pay', p_pay));
  return jsonb_build_object('ok', true, 'id', gid);
end $$;

-- 설정 변경: p_patch { intro, emblem, join_mode (보스) · notice (보스·간부) · name (보스, 심연석 500, 30일 1회) }
create or replace function public.guild_update(p_patch jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; g guilds; n text;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  perform _guild_lock(m.guild_id);
  select * into g from guilds where id = m.guild_id;
  if p_patch ? 'notice' then
    if m.role not in ('boss', 'officer') then raise exception 'no permission'; end if;
    update guilds set notice = _guild_text_ok(p_patch->>'notice', 100) where id = g.id;
  end if;
  if p_patch ?| array['intro', 'emblem', 'join_mode', 'name'] and m.role <> 'boss' then raise exception 'no permission'; end if;
  if p_patch ? 'intro' then update guilds set intro = _guild_text_ok(p_patch->>'intro', 60) where id = g.id; end if;
  if p_patch ? 'emblem' then
    if (p_patch->>'emblem')::int not between 1 and 12 then raise exception 'bad emblem'; end if;
    update guilds set emblem = (p_patch->>'emblem')::int where id = g.id;
  end if;
  if p_patch ? 'join_mode' then
    if p_patch->>'join_mode' not in ('open', 'approval', 'closed') then raise exception 'bad join mode'; end if;
    update guilds set join_mode = p_patch->>'join_mode' where id = g.id;
  end if;
  if p_patch ? 'name' then
    n := _guild_name_ok(p_patch->>'name');
    if g.renamed_at is not null and g.renamed_at > now() - interval '30 days' then raise exception 'rename cooldown'; end if;
    perform pg_advisory_xact_lock(hashtext('guildname:' || lower(n)));
    if exists (select 1 from guilds where name_key = lower(n) and id <> g.id) then raise exception 'name taken'; end if;
    perform _gem_spend(uid, _guild_rename_gem(), 'guild_rename', jsonb_build_object('guild', g.id, 'name', n));
    update guilds set name = n, name_key = lower(n), renamed_at = now() where id = g.id;
  end if;
  perform _guild_log(g.id, uid, 'update', null, p_patch - 'notice' - 'intro' || case when p_patch ? 'notice' then '{"notice":true}'::jsonb else '{}'::jsonb end);
  return jsonb_build_object('ok', true);
end $$;

-- 가입 신청: 공개 = 바로 가입 · 승인제 = 신청 (대기 최대 3개) · 비공개 = 불가
create or replace function public.guild_apply(p_gid bigint) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); g guilds;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('guilduser:' || uid::text));
  perform _guild_lock(p_gid);
  select * into g from guilds where id = p_gid;
  if g.id is null then raise exception 'no such guild'; end if;
  if exists (select 1 from guild_members where user_id = uid) then raise exception 'already in guild'; end if;
  perform _guild_cd_check(uid, p_gid);
  if g.join_mode = 'closed' then raise exception 'closed'; end if;
  if g.join_mode = 'open' then perform _guild_add_member(p_gid, uid, null); return jsonb_build_object('ok', true, 'joined', true); end if;
  if (select count(*) from guild_requests where user_id = uid and kind = 'apply' and status = 'pending' and expires_at > now()) >= 3 then raise exception 'too many requests'; end if;
  insert into guild_requests (guild_id, user_id, kind, by_user) values (p_gid, uid, 'apply', uid) on conflict do nothing;
  return jsonb_build_object('ok', true, 'joined', false, 'pending', true);
end $$;

-- 초대 (보스·간부, 닉네임으로)
create or replace function public.guild_invite(p_nick text) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; t uuid;
begin
  m := _guild_me(uid);
  if m.user_id is null or m.role not in ('boss', 'officer') then raise exception 'no permission'; end if;
  select id into t from profiles where nickname = btrim(p_nick) limit 1;
  if t is null then raise exception 'no such player'; end if;
  if exists (select 1 from guild_members where user_id = t) then raise exception 'already in guild'; end if;
  if (select count(*) from guild_requests where guild_id = m.guild_id and kind = 'invite' and created_at > now() - interval '1 day') >= 20 then raise exception 'too many invites'; end if;
  insert into guild_requests (guild_id, user_id, kind, by_user) values (m.guild_id, t, 'invite', uid) on conflict do nothing;
  perform _guild_log(m.guild_id, uid, 'invite', t, '{}');
  return jsonb_build_object('ok', true);
end $$;

-- 신청/초대 응답: 가입 신청은 그 조직 보스·간부가, 초대는 초대받은 본인이. 본인 신청 취소도 여기서 (p_accept = false)
create or replace function public.guild_respond(p_req bigint, p_accept boolean) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); r guild_requests; m guild_members;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into r from guild_requests where id = p_req;
  if r.id is null or r.status <> 'pending' then raise exception 'no such request'; end if;
  perform _guild_lock(r.guild_id);
  select * into r from guild_requests where id = p_req for update;
  if r.status <> 'pending' then raise exception 'no such request'; end if;
  if r.expires_at < now() then update guild_requests set status = 'cancelled' where id = r.id; raise exception 'expired'; end if;
  if r.kind = 'apply' and r.user_id = uid and not p_accept then
    update guild_requests set status = 'cancelled' where id = r.id; return jsonb_build_object('ok', true);
  end if;
  if r.kind = 'apply' then
    m := _guild_me(uid);
    if m.user_id is null or m.guild_id <> r.guild_id or m.role not in ('boss', 'officer') then raise exception 'no permission'; end if;
  elsif r.user_id <> uid then raise exception 'no permission'; end if;
  if p_accept then
    perform pg_advisory_xact_lock(hashtext('guilduser:' || r.user_id::text));
    perform _guild_add_member(r.guild_id, r.user_id, uid);
    update guild_requests set status = 'accepted' where id = r.id;
  else
    update guild_requests set status = 'rejected' where id = r.id;
  end if;
  return jsonb_build_object('ok', true, 'accepted', p_accept);
end $$;

-- 탈퇴: 24시간 가입 불가. 보스는 넘기기 전엔 못 나감 (혼자면 해산)
create or replace function public.guild_leave() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  perform _guild_lock(m.guild_id);
  if m.role = 'boss' then
    if (select count(*) from guild_members where guild_id = m.guild_id) > 1 then raise exception 'boss must transfer'; end if;
    perform _guild_log(m.guild_id, uid, 'disband', null, '{}');
    delete from guilds where id = m.guild_id;
  else
    delete from guild_members where user_id = uid;
    perform _guild_log(m.guild_id, uid, 'leave', uid, '{}');
  end if;
  insert into guild_cooldowns (user_id, guild_id, until) values (uid, 0, now() + interval '24 hours') on conflict (user_id, guild_id) do update set until = excluded.until;
  return jsonb_build_object('ok', true);
end $$;
create or replace function public.guild_disband() returns jsonb language plpgsql security definer set search_path = public as $$
declare m guild_members := _guild_me(auth.uid());
begin
  if m.user_id is null or m.role <> 'boss' then raise exception 'no permission'; end if;
  if (select count(*) from guild_members where guild_id = m.guild_id) > 1 then raise exception 'members remain'; end if;
  return guild_leave();
end $$;

-- 추방: 보스 = 누구든 (보스 제외) · 간부 = 조직원만. 하루 5명. 그 조직 72시간 재가입 불가
create or replace function public.guild_kick(p_user uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; t guild_members;
begin
  m := _guild_me(uid);
  if m.user_id is null or m.role not in ('boss', 'officer') then raise exception 'no permission'; end if;
  perform _guild_lock(m.guild_id);
  t := _guild_me(p_user);
  if t.user_id is null or t.guild_id <> m.guild_id or t.role = 'boss' or (m.role = 'officer' and t.role <> 'member') then raise exception 'no permission'; end if;
  if (select count(*) from guild_log where guild_id = m.guild_id and action = 'kick' and created_at >= (_guild_day()::timestamp at time zone 'Asia/Seoul')) >= 5 then raise exception 'kick limit'; end if;
  delete from guild_members where user_id = p_user;
  insert into guild_cooldowns (user_id, guild_id, until) values (p_user, m.guild_id, now() + interval '72 hours') on conflict (user_id, guild_id) do update set until = excluded.until;
  perform _guild_log(m.guild_id, uid, 'kick', p_user, '{}');
  return jsonb_build_object('ok', true);
end $$;

-- 간부 임명/해제 (보스). 간부 수는 레벨표 상한
create or replace function public.guild_set_role(p_user uuid, p_role text) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; t guild_members; mx int;
begin
  m := _guild_me(uid);
  if m.user_id is null or m.role <> 'boss' then raise exception 'no permission'; end if;
  if p_role not in ('officer', 'member') then raise exception 'bad role'; end if;
  perform _guild_lock(m.guild_id);
  t := _guild_me(p_user);
  if t.user_id is null or t.guild_id <> m.guild_id or t.role = 'boss' then raise exception 'no permission'; end if;
  if p_role = 'officer' and t.role <> 'officer' then
    select officers into mx from guild_level_table where level = (select level from guilds where id = m.guild_id);
    if (select count(*) from guild_members where guild_id = m.guild_id and role = 'officer') >= coalesce(mx, 1) then raise exception 'officer slots full'; end if;
  end if;
  update guild_members set role = p_role where user_id = p_user;
  perform _guild_log(m.guild_id, uid, 'role', p_user, jsonb_build_object('role', p_role));
  return jsonb_build_object('ok', true);
end $$;

-- 보스 넘기기 (보스 → 조직원 중 1명, 이전 보스는 간부)
create or replace function public.guild_transfer(p_user uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; t guild_members;
begin
  m := _guild_me(uid);
  if m.user_id is null or m.role <> 'boss' then raise exception 'no permission'; end if;
  perform _guild_lock(m.guild_id);
  t := _guild_me(p_user);
  if t.user_id is null or t.guild_id <> m.guild_id or p_user = uid then raise exception 'no permission'; end if;
  update guild_members set role = 'officer' where user_id = uid;
  update guild_members set role = 'boss' where user_id = p_user;
  update guilds set boss = p_user where id = m.guild_id;
  perform _guild_log(m.guild_id, uid, 'transfer', p_user, '{}');
  return jsonb_build_object('ok', true);
end $$;

-- 보스 14일 미접속: 가장 오래된 간부 (간부 없으면 충성 누적 1위 조직원) 가 보스 승계
create or replace function public.guild_claim_boss() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; b guild_members; heir uuid;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  perform _guild_lock(m.guild_id);
  select * into b from guild_members where guild_id = m.guild_id and role = 'boss';
  if b.seen_at > now() - interval '14 days' then raise exception 'boss active'; end if;
  select user_id into heir from guild_members where guild_id = m.guild_id and role <> 'boss'
    order by (role = 'officer') desc, case when role = 'officer' then extract(epoch from joined_at) else -loyalty_total end, joined_at limit 1;
  if heir is distinct from uid then raise exception 'not heir'; end if;
  update guild_members set role = 'member' where user_id = b.user_id;
  update guild_members set role = 'boss' where user_id = uid;
  update guilds set boss = uid where id = m.guild_id;
  perform _guild_log(m.guild_id, uid, 'claim_boss', b.user_id, '{}');
  return jsonb_build_object('ok', true);
end $$;

-- 충성 상점 (개인 충성 사용, 조직 레벨로 해금, 하루/주/1회 제한)
create or replace function public.guild_shop_buy(p_item text) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; s guild_shop; lv int; t int; res jsonb := '{}'::jsonb; w jsonb;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  perform pg_advisory_xact_lock(hashtext('guilduser:' || uid::text));
  select * into s from guild_shop where item = p_item and active;
  if s.item is null then raise exception 'invalid item'; end if;
  select level into lv from guilds where id = m.guild_id;
  if lv < s.min_level then raise exception 'guild level required %', s.min_level; end if;
  if _guild_shop_left(uid, s) = 0 or (s.limit_kind = 'once' and exists (select 1 from guild_titles where user_id = uid and title = s.gives->>'title')) then raise exception 'limit reached'; end if;
  perform _loyalty_add(uid, -s.price, 'shop:' || s.item, null, jsonb_build_object('gives', s.gives));
  if s.gives ? 'tickets' then
    insert into story_gacha (user_id, last_draw) values (uid, _guild_day() - 1) on conflict (user_id) do nothing;
    update story_gacha set tickets = tickets + (s.gives->>'tickets')::int, updated_at = now() where user_id = uid returning tickets into t;
    res := res || jsonb_build_object('tickets', t);
  end if;
  w := s.gives - 'tickets' - 'stamina' - 'title';
  if w <> '{}'::jsonb then res := res || jsonb_build_object('wallet', _wallet_add(uid, w, 'guild_shop')); end if;
  if s.gives ? 'stamina' then res := res || jsonb_build_object('stamina', _player_stamina_add(uid, (s.gives->>'stamina')::int)); end if;
  if s.gives ? 'title' then insert into guild_titles (user_id, title) values (uid, s.gives->>'title') on conflict do nothing; end if;
  return res || jsonb_build_object('ok', true, 'item', s.item, 'loyalty', (select balance from loyalty_wallet where user_id = uid));
end $$;

revoke all on function public.guild_status(), public.guild_search(text), public.guild_create(text, int, text, text, text), public.guild_update(jsonb), public.guild_apply(bigint),
  public.guild_invite(text), public.guild_respond(bigint, boolean), public.guild_leave(), public.guild_disband(), public.guild_kick(uuid), public.guild_set_role(uuid, text),
  public.guild_transfer(uuid), public.guild_claim_boss(), public.guild_shop_buy(text) from public, anon;
grant execute on function public.guild_status(), public.guild_search(text), public.guild_create(text, int, text, text, text), public.guild_update(jsonb), public.guild_apply(bigint),
  public.guild_invite(text), public.guild_respond(bigint, boolean), public.guild_leave(), public.guild_disband(), public.guild_kick(uuid), public.guild_set_role(uuid, text),
  public.guild_transfer(uuid), public.guild_claim_boss(), public.guild_shop_buy(text) to authenticated;

-- 5) 관리자: 목록 · 이름 변경 · 공지 지우기 · 해산 (admin_log 기록)
create or replace function public.admin_guild_list(p_q text default null) returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
begin
  perform public._admin_guard();
  return (select coalesce(jsonb_agg(_guild_card(g.id) || jsonb_build_object('exp', g.exp, 'notice', g.notice, 'created_at', g.created_at) order by g.id desc), '[]'::jsonb)
    from (select * from guilds where p_q is null or name_key like '%' || lower(p_q) || '%' order by id desc limit 200) g);
end $$;
create or replace function public.admin_guild_edit(p_gid bigint, p_action text, p_value text, p_reason text) returns jsonb language plpgsql volatile security definer set search_path = public, auth as $$
declare g guilds; n text;
begin
  perform public._admin_guard();
  if coalesce(btrim(p_reason), '') = '' then raise exception 'reason required'; end if;
  select * into g from guilds where id = p_gid;
  if g.id is null then raise exception 'no such guild'; end if;
  if p_action = 'rename' then n := _guild_name_ok(p_value);
    if exists (select 1 from guilds where name_key = lower(n) and id <> g.id) then raise exception 'name taken'; end if;
    update guilds set name = n, name_key = lower(n) where id = g.id;
  elsif p_action = 'clear_text' then update guilds set notice = '', intro = '' where id = g.id;
  elsif p_action = 'disband' then delete from guilds where id = g.id;
  else raise exception 'bad action'; end if;
  insert into public.admin_log (admin_id, admin_email, action, target_user, amount, reason, before_val, after_val)
  values (auth.uid(), auth.jwt()->>'email', 'guild_' || p_action, g.boss, g.id::int, left(btrim(p_reason) || ' · ' || g.name || coalesce(' → ' || n, ''), 200), null, null);
  perform _guild_log(case when p_action = 'disband' then null else g.id end, auth.uid(), 'admin_' || p_action, null, jsonb_build_object('reason', p_reason));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.admin_guild_list(text), public.admin_guild_edit(bigint, text, text, text) from public, anon;
grant execute on function public.admin_guild_list(text), public.admin_guild_edit(bigint, text, text, text) to authenticated;


-- 6) 스토리·PvP 연동 (phaseE_2.sql / pvp_tier.sql 과 같은 정의 — 이 파일만 실행해도 되도록 복사. tools/test_guild_sql.mjs 가 일치 확인)
--    스토리 경험치(= 행동력 × 10) 60 당 세력 1 · PvP 승리 +10
create or replace function public._player_add_xp(p_uid uuid, p_xp int, p_reward boolean) returns jsonb language plpgsql security definer set search_path = public as $$
declare ps player_state; n int := 0; gold int := 0; mx int;
begin
  select * into ps from player_state where user_id = p_uid for update;
  if ps.user_id is null or p_xp <= 0 then return jsonb_build_object('levelups', 0, 'gold', 0); end if;
  ps.xp := ps.xp + p_xp;
  while ps.level < _player_max_level() and ps.xp >= _player_xp_need(ps.level) loop
    ps.xp := ps.xp - _player_xp_need(ps.level);
    ps.level := ps.level + 1; n := n + 1;
    if p_reward then
      mx := _stamina_max(ps.level);
      if ps.stamina >= _stamina_max(ps.level - 1) then ps.stamina_at := now(); end if;
      ps.stamina := ps.stamina + mx;
      gold := gold + 100 * ps.level;
    end if;
  end loop;
  if ps.level >= _player_max_level() then ps.xp := 0; end if;
  update player_state set level = ps.level, xp = ps.xp, stamina = ps.stamina, stamina_at = ps.stamina_at, updated_at = now() where user_id = p_uid;
  if gold > 0 and to_regprocedure('public._wallet_add(uuid,jsonb,text)') is not null then
    perform public._wallet_add(p_uid, jsonb_build_object('gold', gold), 'player_levelup');
  end if;
  -- 조직 세력 (guild.sql): 스토리 경험치 60 = 행동력 6 → 세력 1 (하루 상한은 _guild_feed 가 처리)
  if to_regprocedure('public._guild_feed(uuid,text,integer)') is not null then perform public._guild_feed(p_uid, 'story', greatest(1, p_xp / 60)); end if;
  return jsonb_build_object('levelups', n, 'gold', gold);
end $$;
revoke all on function public._player_add_xp(uuid, int, boolean) from public, anon, authenticated;
create or replace function public.pvp_report(p_id bigint, p_wins int, p_losses int) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); a pvp_attempts; n int; need int; v_win boolean; r int; sk int := 0; srw jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into a from pvp_attempts where id = p_id and user_id = uid for update;
  if a.id is null then raise exception 'not found'; end if;
  if a.reported_at is not null then raise exception 'already reported'; end if;
  if now() - a.created_at > interval '1 hour' then raise exception 'expired'; end if;
  n := _pvp_ok(a.league, a.mode); need := case when n = 3 then 2 else 1 end;
  if p_wins is null or p_losses is null or p_wins < 0 or p_losses < 0 or p_wins > need or p_losses > need
     or not (p_wins = need or p_losses = need) or (p_wins = need and p_losses = need) then raise exception 'bad result'; end if;
  v_win := p_wins = need;
  update pvp_attempts set reported_at = now(), wins = p_wins, losses = p_losses, win = v_win where id = p_id;
  if v_win then
    update pvp_ratings set rating = rating + a.dl + a.dw, wins = wins + 1, losses = losses - 1, updated_at = now()
      where user_id = uid and league = a.league and mode = a.mode and season = a.season;
    if a.opp_user is not null then
      update pvp_ratings set rating = rating - a.dl / 2 - a.dw / 2, def_wins = def_wins - 1, def_losses = def_losses + 1, updated_at = now()
        where user_id = a.opp_user and league = a.league and mode = a.mode and season = a.season;
    end if;
    sk := _pvp_streak(uid, a.league, a.mode, a.season, p_id);
    select reward into srw from pvp_streak_table where pvp_streak_table.n = sk;
    if srw is not null then perform _pvp_grant(uid, srw, 'pvp_streak', a.league, a.mode, a.season); end if;
    update pvp_attempts set streak = sk, streak_reward = srw where id = p_id;
    -- 조직 세력 (guild.sql): 승리당 +10 (하루 상한은 _guild_feed 가 처리)
    if to_regprocedure('public._guild_feed(uuid,text,integer)') is not null then perform _guild_feed(uid, 'pvp', 10); end if;
  end if;
  select rating into r from pvp_ratings where user_id = uid and league = a.league and mode = a.mode and season = a.season;
  return jsonb_build_object('ok', true, 'win', v_win, 'rating', r, 'delta', case when v_win then a.dw else -a.dl end,
    'tier', _pvp_tier(r), 'streak', sk, 'streak_reward', srw);
end $$;
revoke all on function public.pvp_report(bigint, int, int) from public, anon;
grant execute on function public.pvp_report(bigint, int, int) to authenticated;


-- ===== SOURCE: guild2.sql =====
-- ⚠ 다시 돌리지 마세요, 최신 아님 (일부): 이 파일의 story_sweep 는 뒤 파일에서 다시 정의됨. 이 파일을 다시 돌리면 예전 것으로 되돌아가요. supabase/README.md 참고
-- =====================================================================
-- [조직] 2단계: 집결(출석) · 의뢰(일일 개인 / 주간 공동) — Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전
-- 선행: guild.sql (1단계) · gem.sql · phaseE_3.sql · phaseE_5.sql · quest.sql / tower_v2.sql
-- 하루 = KST 00:00 기준, 한 주 = 월요일 00:00 (KST) 시작
-- 집결: 하루 1번 충성 20 · 골드 1,000 · 세력 10 / 출석률 30·60·90% 보너스 / 주 7일 개근 충성 100 + 소환권 1
-- 의뢰: 일일 3개(풀 8종, 하루 1번 무료 교체, 3개 완료 보너스 충성 20) · 주간 공동 3개(풀 6종, 목표 = 1인 목표 × 인원, 50·100·150% 보상)
-- 진행도는 서버 이벤트로만 (_guild_event): 스토리 클리어·소탕, PvP 승리, 탑 클리어, 카드 뽑기, 카드 레벨업, 집결
-- 보상은 guild_claims (유저별 고유 ref) 로 한 번만. 쓰기는 전부 서버 함수 (테이블 RLS + revoke)
-- 확인용: select public.guild_rally(); select public.guild_quests();
-- =====================================================================

-- 1) 테이블
create table if not exists public.guild_attendance (
  user_id  uuid not null references auth.users(id) on delete cascade,
  day      date not null,
  guild_id bigint not null,
  at       timestamptz not null default now(),
  primary key (user_id, day));
create index if not exists guild_attendance_gday on public.guild_attendance (guild_id, day);
create table if not exists public.guild_quest_pool (
  key text primary key, kind text not null check (kind in ('daily', 'weekly')), event text not null, goal int not null check (goal > 0),
  reward jsonb not null default '{}'::jsonb, weight int not null default 1, label text not null, icon text not null default '📜', active boolean not null default true);
insert into public.guild_quest_pool (key, kind, event, goal, reward, label, icon) values
  ('d_phase',   'daily', 'draw',    1,  '{"loyalty":15,"gold":800,"exp":10}',  '인재 소환 1회', '🎴'),   -- guild_quest_draw.sql (예전 '페이즈 정리 5')
  ('d_stamina', 'daily', 'stamina', 60, '{"loyalty":15,"gold":800,"exp":10}',  '행동력 소모',  '🔋'),
  ('d_pvp',     'daily', 'pvp_win', 2,  '{"loyalty":20,"gold":1000,"exp":15}', 'PvP 승리',     '⚔️'),
  ('d_tower',   'daily', 'tower',   1,  '{"loyalty":15,"gold":800,"exp":10}',  '탑 오르기',    '🗼'),
  ('d_draw',    'daily', 'draw',    1,  '{"loyalty":10,"gold":500,"exp":5}',   '소환',         '🎴'),
  ('d_boss',    'daily', 'raid',    1,  '{"loyalty":20,"gold":1000,"exp":15}', '균열 토벌',    '🐉'),   -- guild_quest_raid.sql
  ('d_levelup', 'daily', 'levelup', 1,  '{"loyalty":10,"gold":500,"exp":5}',   '카드 강화',    '⬆️'),
  ('d_checkin', 'daily', 'checkin', 1,  '{"loyalty":10,"exp":5}',              '집결',         '🕯️'),
  ('w_phase',   'weekly', 'phase',   30,  '{}', '균열 정리',   '🗡️'),
  ('w_pvp',     'weekly', 'pvp_win', 10,  '{}', '피의 결투',   '⚔️'),
  ('w_stamina', 'weekly', 'stamina', 300, '{}', '행동력 헌납', '🔋'),
  ('w_tower',   'weekly', 'tower',   5,   '{}', '탑 정복',     '🗼'),
  ('w_checkin', 'weekly', 'checkin', 5,   '{}', '집결의 맹세', '🕯️'),
  ('w_draw',    'weekly', 'draw',    5,   '{}', '소환 의식',   '🎴')
on conflict (key) do update set kind = excluded.kind, event = excluded.event, goal = excluded.goal, reward = excluded.reward, label = excluded.label, icon = excluded.icon;
create table if not exists public.guild_daily_quests (
  user_id uuid not null references auth.users(id) on delete cascade, day date not null, slot int not null check (slot between 1 and 3),
  qkey text not null, goal int not null, progress int not null default 0, rerolled boolean not null default false, claimed_at timestamptz,
  primary key (user_id, day, slot));
create table if not exists public.guild_weekly_quests (
  guild_id bigint not null references public.guilds(id) on delete cascade, week date not null, slot int not null check (slot between 1 and 3),
  qkey text not null, goal int not null, progress int not null default 0, primary key (guild_id, week, slot));
create table if not exists public.guild_weekly_contrib (
  guild_id bigint not null, week date not null, slot int not null, user_id uuid not null references auth.users(id) on delete cascade,
  amount int not null default 0, primary key (guild_id, week, slot, user_id));
create table if not exists public.guild_claims (
  user_id uuid not null references auth.users(id) on delete cascade, ref text not null, guild_id bigint, reward jsonb not null, at timestamptz not null default now(),
  primary key (user_id, ref));
do $$ declare t text; begin
  foreach t in array array['guild_attendance', 'guild_quest_pool', 'guild_daily_quests', 'guild_weekly_quests', 'guild_weekly_contrib', 'guild_claims'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
  end loop;
end $$;

-- 2) 수치 (한 곳에서 조정)
create or replace function public._guild_week() returns date language sql stable as $$ select date_trunc('week', _guild_day()::timestamp)::date $$;
create or replace function public._guild_checkin_reward() returns jsonb language sql immutable as $$ select '{"loyalty":20,"gold":1000,"exp":10}'::jsonb $$;
-- 출석률 보너스: [필요 %, 개인 보상, 조직 세력]
create or replace function public._guild_rally_tiers() returns jsonb language sql immutable as $$
  select '[{"tier":30,"reward":{"loyalty":10},"exp":30},{"tier":60,"reward":{"loyalty":20,"gold":1000},"exp":60},{"tier":90,"reward":{"loyalty":30,"gem":5},"exp":100}]'::jsonb $$;
create or replace function public._guild_week_streak_reward() returns jsonb language sql immutable as $$ select '{"loyalty":100,"tickets":1}'::jsonb $$;
create or replace function public._guild_daily_all_reward() returns jsonb language sql immutable as $$ select '{"loyalty":20}'::jsonb $$;
-- 주간 공동 의뢰 단계: [%, 개인 보상, 조직 세력]
create or replace function public._guild_weekly_tiers() returns jsonb language sql immutable as $$
  select '[{"tier":50,"reward":{"loyalty":30},"exp":100},{"tier":100,"reward":{"loyalty":60,"gold":3000,"gem":10},"exp":200},{"tier":150,"reward":{"loyalty":100,"tickets":1},"exp":300}]'::jsonb $$;
create or replace function public._guild_weekly_min_pct() returns numeric language sql immutable as $$ select 0.01 $$;

-- 3) 내부 도우미
-- 보상 지급 (한 번만). 키: loyalty · gold · gem · tickets · exp(조직 세력). 이미 받았으면 'already claimed'
create or replace function public._guild_reward(p_uid uuid, p_gid bigint, p_rw jsonb, p_reason text, p_ref text) returns jsonb language plpgsql security definer set search_path = public as $$
declare ok boolean; w jsonb;
begin
  insert into guild_claims (user_id, ref, guild_id, reward) values (p_uid, p_ref, p_gid, p_rw) on conflict do nothing returning true into ok;
  if not coalesce(ok, false) then raise exception 'already claimed'; end if;
  if coalesce((p_rw->>'loyalty')::int, 0) > 0 then perform _loyalty_add(p_uid, (p_rw->>'loyalty')::int, p_reason, null, jsonb_build_object('ref', p_ref)); end if;
  if coalesce((p_rw->>'gold')::int, 0) > 0 then w := _wallet_add(p_uid, jsonb_build_object('gold', (p_rw->>'gold')::int), p_reason); end if;
  if coalesce((p_rw->>'gem')::int, 0) > 0 then perform _gem_add(p_uid, (p_rw->>'gem')::int, 0, p_reason, 'guild:' || p_ref, jsonb_build_object('guild', p_gid)); end if;
  if coalesce((p_rw->>'tickets')::int, 0) > 0 then
    insert into story_gacha (user_id, last_draw) values (p_uid, _guild_day() - 1) on conflict (user_id) do nothing;
    update story_gacha set tickets = tickets + (p_rw->>'tickets')::int, updated_at = now() where user_id = p_uid;
  end if;
  if coalesce((p_rw->>'exp')::int, 0) > 0 and p_gid is not null then perform _guild_exp(p_gid, p_uid, (p_rw->>'exp')::int, p_reason, 'u:' || p_uid || ':' || p_ref); end if;
  return jsonb_build_object('reward', p_rw, 'wallet', w);
end $$;
-- 오늘 일일 의뢰 3개 (없으면 뽑기, 같은 종류 중복 없음)
create or replace function public._guild_roll_daily(p_uid uuid) returns void language plpgsql security definer set search_path = public as $$
declare d date := _guild_day(); q record; i int := 0;
begin
  if exists (select 1 from guild_daily_quests where user_id = p_uid and day = d) then return; end if;
  for q in select key, goal from guild_quest_pool where kind = 'daily' and active order by -ln(1 - random()) / greatest(weight, 1) limit 3 loop
    i := i + 1; insert into guild_daily_quests (user_id, day, slot, qkey, goal) values (p_uid, d, i, q.key, q.goal) on conflict do nothing;
  end loop;
end $$;
-- 이번 주 공동 의뢰 3개 (목표 = 1인 목표 × 그때 인원)
create or replace function public._guild_roll_weekly(p_gid bigint) returns void language plpgsql security definer set search_path = public as $$
declare w date := _guild_week(); q record; i int := 0; n int;
begin
  if exists (select 1 from guild_weekly_quests where guild_id = p_gid and week = w) then return; end if;
  perform _guild_lock(p_gid);
  if exists (select 1 from guild_weekly_quests where guild_id = p_gid and week = w) then return; end if;
  select greatest(count(*), 1) into n from guild_members where guild_id = p_gid;
  for q in select key, goal from guild_quest_pool where kind = 'weekly' and active order by -ln(1 - random()) / greatest(weight, 1) limit 3 loop
    i := i + 1; insert into guild_weekly_quests (guild_id, week, slot, qkey, goal) values (p_gid, w, i, q.key, q.goal * n) on conflict do nothing;
  end loop;
end $$;
-- 진행 이벤트 (서버 함수·트리거에서만). 조직이 없으면 무시. 오류가 나도 원래 동작은 막지 않음
create or replace function public._guild_event(p_uid uuid, p_kind text, p_n int) returns void language plpgsql security definer set search_path = public as $$
declare m guild_members; w date := _guild_week();
begin
  if p_uid is null or coalesce(p_n, 0) <= 0 then return; end if;
  select * into m from guild_members where user_id = p_uid;
  if m.user_id is null then return; end if;
  begin
    perform _guild_roll_daily(p_uid);
    update guild_daily_quests d set progress = least(d.goal, d.progress + p_n)
      from guild_quest_pool p where d.user_id = p_uid and d.day = _guild_day() and p.key = d.qkey and p.event = p_kind and d.claimed_at is null;
    perform _guild_roll_weekly(m.guild_id);
    if exists (select 1 from guild_weekly_quests q join guild_quest_pool p on p.key = q.qkey where q.guild_id = m.guild_id and q.week = w and p.event = p_kind) then
      perform _guild_lock(m.guild_id);
      insert into guild_weekly_contrib (guild_id, week, slot, user_id, amount)
        select q.guild_id, q.week, q.slot, p_uid, p_n from guild_weekly_quests q join guild_quest_pool p on p.key = q.qkey where q.guild_id = m.guild_id and q.week = w and p.event = p_kind
        on conflict (guild_id, week, slot, user_id) do update set amount = guild_weekly_contrib.amount + excluded.amount;
      update guild_weekly_quests q set progress = q.progress + p_n from guild_quest_pool p where q.guild_id = m.guild_id and q.week = w and p.key = q.qkey and p.event = p_kind;
    end if;
  exception when others then
    raise warning '[guild_event] %', sqlerrm;
  end;
end $$;
-- 오늘 출석 인원 (오늘 가입한 사람 제외) / 현재 인원
create or replace function public._guild_rally_count(p_gid bigint) returns int[] language sql stable security definer set search_path = public as $$
  select array[(select count(*)::int from guild_attendance a join guild_members gm on gm.user_id = a.user_id and gm.guild_id = p_gid
                 where a.guild_id = p_gid and a.day = _guild_day() and gm.joined_at < (_guild_day()::timestamp at time zone 'Asia/Seoul')),
               (select count(*)::int from guild_members where guild_id = p_gid)] $$;
revoke all on function public._guild_reward(uuid, bigint, jsonb, text, text), public._guild_roll_daily(uuid), public._guild_roll_weekly(bigint),
  public._guild_event(uuid, text, int), public._guild_rally_count(bigint) from public, anon, authenticated;

-- 4) 트리거: 카드 뽑기(story_gacha_log) · 카드 레벨업(wallet_log 'card_levelup') · 탑 클리어(quest_progress / tower_progress clears 증가)
create or replace function public._guild_trg_draw() returns trigger language plpgsql security definer set search_path = public as $$
begin perform _guild_event(new.user_id, 'draw', 1); return null; end $$;
create or replace function public._guild_trg_levelup() returns trigger language plpgsql security definer set search_path = public as $$
begin if new.reason = 'card_levelup' then perform _guild_event(new.user_id, 'levelup', 1); end if; return null; end $$;
create or replace function public._guild_trg_tower() returns trigger language plpgsql security definer set search_path = public as $$
begin if new.clears > old.clears then perform _guild_event(new.user_id, 'tower', new.clears - old.clears); end if; return null; end $$;
revoke all on function public._guild_trg_draw(), public._guild_trg_levelup(), public._guild_trg_tower() from public, anon, authenticated;
drop trigger if exists guild_ev_draw on public.story_gacha_log;
create trigger guild_ev_draw after insert on public.story_gacha_log for each row execute function public._guild_trg_draw();
drop trigger if exists guild_ev_levelup on public.wallet_log;
create trigger guild_ev_levelup after insert on public.wallet_log for each row execute function public._guild_trg_levelup();
do $$ begin
  if to_regclass('public.quest_progress') is not null then
    drop trigger if exists guild_ev_tower on public.quest_progress;
    create trigger guild_ev_tower after update of clears on public.quest_progress for each row execute function public._guild_trg_tower();
  end if;
  if to_regclass('public.tower_progress') is not null then
    drop trigger if exists guild_ev_tower on public.tower_progress;
    create trigger guild_ev_tower after update of clears on public.tower_progress for each row execute function public._guild_trg_tower();
  end if;
end $$;

-- 5) 공개 RPC
-- 집결 상태: { ok, checked, count, total, pct, tiers:[{tier, reward, exp, reached, claimed}], week:[7일 bool], week_claimable, week_claimed, checked_users:[uid] }
create or replace function public.guild_rally() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; c int[]; pct numeric; d date := _guild_day(); w date := _guild_week(); days int;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  c := _guild_rally_count(m.guild_id); pct := case when c[2] > 0 then c[1] * 100.0 / c[2] else 0 end;
  select count(*) into days from guild_attendance where user_id = uid and day between w and w + 6;
  return jsonb_build_object('ok', true, 'day', d, 'checked', exists (select 1 from guild_attendance where user_id = uid and day = d),
    'checked_other', exists (select 1 from guild_attendance where user_id = uid and day = d and guild_id <> m.guild_id),
    'count', c[1], 'total', c[2], 'pct', round(pct, 1), 'reward', _guild_checkin_reward(),
    'tiers', (select jsonb_agg(t || jsonb_build_object('reached', pct >= (t->>'tier')::int, 'claimed', exists (select 1 from guild_claims where user_id = uid and ref = 'rally:' || d || ':' || (t->>'tier'))))
              from jsonb_array_elements(_guild_rally_tiers()) t),
    'week', (select jsonb_agg(exists (select 1 from guild_attendance where user_id = uid and day = w + i) order by i) from generate_series(0, 6) i),
    'week_reward', _guild_week_streak_reward(), 'week_claimable', days >= 7, 'week_claimed', exists (select 1 from guild_claims where user_id = uid and ref = 'rallyweek:' || w),
    'checked_users', (select coalesce(jsonb_agg(a.user_id), '[]'::jsonb) from guild_attendance a where a.guild_id = m.guild_id and a.day = d));
end $$;
-- 집결 (하루 1번, 조직을 옮겨도 하루 1번)
create or replace function public.guild_checkin() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; ok boolean; r jsonb;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  insert into guild_attendance (user_id, day, guild_id) values (uid, _guild_day(), m.guild_id) on conflict do nothing returning true into ok;
  if not coalesce(ok, false) then raise exception 'already checked in'; end if;
  r := _guild_reward(uid, m.guild_id, _guild_checkin_reward(), 'guild_checkin', 'checkin:' || _guild_day());
  perform _guild_event(uid, 'checkin', 1);
  return guild_rally() || jsonb_build_object('got', _guild_checkin_reward(), 'wallet', r->'wallet');
end $$;
-- 출석률 보너스 (p_tier = 30 | 60 | 90) 또는 주간 개근 (p_tier = 7)
create or replace function public.guild_rally_claim(p_tier int) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; c int[]; t jsonb; d date := _guild_day(); w date := _guild_week(); r jsonb;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  if p_tier = 7 then
    if (select count(*) from guild_attendance where user_id = uid and day between w and w + 6) < 7 then raise exception 'not reached'; end if;
    r := _guild_reward(uid, m.guild_id, _guild_week_streak_reward(), 'guild_rally_week', 'rallyweek:' || w);
    return guild_rally() || jsonb_build_object('got', _guild_week_streak_reward(), 'wallet', r->'wallet');
  end if;
  select x into t from jsonb_array_elements(_guild_rally_tiers()) x where (x->>'tier')::int = p_tier;
  if t is null then raise exception 'bad tier'; end if;
  if not exists (select 1 from guild_attendance where user_id = uid and day = d and guild_id = m.guild_id) then raise exception 'check in first'; end if;
  c := _guild_rally_count(m.guild_id);
  if c[2] = 0 or c[1] * 100.0 / c[2] < p_tier then raise exception 'not reached'; end if;
  r := _guild_reward(uid, m.guild_id, t->'reward', 'guild_rally_bonus', 'rally:' || d || ':' || p_tier);
  perform _guild_exp(m.guild_id, null, (t->>'exp')::int, 'rally_bonus', 'rally:' || d || ':' || p_tier);   -- 조직 세력은 조직당 한 번
  return guild_rally() || jsonb_build_object('got', t->'reward', 'wallet', r->'wallet');
end $$;
-- 의뢰 상태
create or replace function public.guild_quests() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; d date := _guild_day(); w date := _guild_week();
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  perform _guild_roll_daily(uid); perform _guild_roll_weekly(m.guild_id);
  return jsonb_build_object('ok', true, 'day', d, 'week', w, 'week_end', ((w + 7)::timestamp at time zone 'Asia/Seoul'),
    'daily', (select jsonb_agg(jsonb_build_object('slot', q.slot, 'key', q.qkey, 'label', p.label, 'icon', p.icon, 'event', p.event, 'goal', q.goal, 'progress', q.progress,
                'reward', p.reward, 'claimed', q.claimed_at is not null) order by q.slot) from guild_daily_quests q join guild_quest_pool p on p.key = q.qkey where q.user_id = uid and q.day = d),
    'reroll_left', case when exists (select 1 from guild_daily_quests where user_id = uid and day = d and rerolled) then 0 else 1 end,
    'all_reward', _guild_daily_all_reward(), 'all_claimed', exists (select 1 from guild_claims where user_id = uid and ref = 'dqall:' || d),
    'weekly', (select jsonb_agg(jsonb_build_object('slot', q.slot, 'key', q.qkey, 'label', p.label, 'icon', p.icon, 'event', p.event, 'goal', q.goal, 'progress', q.progress,
                'mine', coalesce((select amount from guild_weekly_contrib c where c.guild_id = q.guild_id and c.week = w and c.slot = q.slot and c.user_id = uid), 0),
                'min', ceil(q.goal * _guild_weekly_min_pct())::int,
                'tiers', (select jsonb_agg(t || jsonb_build_object('reached', q.progress * 100 >= q.goal * (t->>'tier')::int,
                            'claimed', exists (select 1 from guild_claims where user_id = uid and ref = 'wq:' || w || ':' || q.slot || ':' || (t->>'tier')))) from jsonb_array_elements(_guild_weekly_tiers()) t),
                'top', (select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(pr.nickname, '조직원'), 'amount', c.amount) order by c.amount desc), '[]'::jsonb)
                        from (select * from guild_weekly_contrib c2 where c2.guild_id = q.guild_id and c2.week = w and c2.slot = q.slot order by amount desc limit 5) c left join profiles pr on pr.id = c.user_id))
              order by q.slot) from guild_weekly_quests q join guild_quest_pool p on p.key = q.qkey where q.guild_id = m.guild_id and q.week = w));
end $$;
-- 일일 의뢰 보상 (p_slot 1~3) · 3개 완료 보너스 (p_slot = 0)
create or replace function public.guild_quest_claim(p_slot int) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; d date := _guild_day(); q guild_daily_quests; rw jsonb; r jsonb;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  if p_slot = 0 then
    if (select count(*) from guild_daily_quests where user_id = uid and day = d and claimed_at is not null) < 3 then raise exception 'not reached'; end if;
    r := _guild_reward(uid, m.guild_id, _guild_daily_all_reward(), 'guild_daily_all', 'dqall:' || d);
    return guild_quests() || jsonb_build_object('got', _guild_daily_all_reward(), 'wallet', r->'wallet');
  end if;
  select * into q from guild_daily_quests where user_id = uid and day = d and slot = p_slot for update;
  if q.user_id is null then raise exception 'no quest'; end if;
  if q.progress < q.goal then raise exception 'not reached'; end if;
  select reward into rw from guild_quest_pool where key = q.qkey;
  r := _guild_reward(uid, m.guild_id, rw, 'guild_daily', 'dq:' || d || ':' || p_slot);
  update guild_daily_quests set claimed_at = now() where user_id = uid and day = d and slot = p_slot;
  return guild_quests() || jsonb_build_object('got', rw, 'wallet', r->'wallet');
end $$;
-- 일일 의뢰 교체 (하루 1번 무료, 받지 않은 칸만, 진행도 0 부터)
create or replace function public.guild_quest_reroll(p_slot int) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; d date := _guild_day(); q guild_daily_quests; nk record;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  perform _guild_roll_daily(uid);
  if exists (select 1 from guild_daily_quests where user_id = uid and day = d and rerolled) then raise exception 'reroll used'; end if;
  select * into q from guild_daily_quests where user_id = uid and day = d and slot = p_slot for update;
  if q.user_id is null or q.claimed_at is not null then raise exception 'no quest'; end if;
  select key, goal into nk from guild_quest_pool where kind = 'daily' and active and key not in (select qkey from guild_daily_quests where user_id = uid and day = d) order by random() limit 1;
  if nk.key is null then raise exception 'no quest'; end if;
  update guild_daily_quests set qkey = nk.key, goal = nk.goal, progress = 0, rerolled = true where user_id = uid and day = d and slot = p_slot;
  return guild_quests();
end $$;
-- 주간 공동 의뢰 보상 (p_tier = 50 | 100 | 150). 기여 1% 이상만. 조직 세력은 조직당 한 번
create or replace function public.guild_weekly_claim(p_slot int, p_tier int) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; w date := _guild_week(); q guild_weekly_quests; t jsonb; mine int; r jsonb;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  select * into q from guild_weekly_quests where guild_id = m.guild_id and week = w and slot = p_slot;
  if q.guild_id is null then raise exception 'no quest'; end if;
  select x into t from jsonb_array_elements(_guild_weekly_tiers()) x where (x->>'tier')::int = p_tier;
  if t is null then raise exception 'bad tier'; end if;
  if q.progress * 100 < q.goal * p_tier then raise exception 'not reached'; end if;
  select amount into mine from guild_weekly_contrib where guild_id = q.guild_id and week = w and slot = p_slot and user_id = uid;
  if coalesce(mine, 0) < ceil(q.goal * _guild_weekly_min_pct()) then raise exception 'contribution too low'; end if;
  r := _guild_reward(uid, m.guild_id, t->'reward', 'guild_weekly', 'wq:' || w || ':' || p_slot || ':' || p_tier);
  perform _guild_exp(m.guild_id, null, (t->>'exp')::int, 'weekly_quest', 'wq:' || w || ':' || p_slot || ':' || p_tier);
  return guild_quests() || jsonb_build_object('got', t->'reward', 'wallet', r->'wallet');
end $$;
-- 조직 홈 빨간 점: { rally: 집결 안 했거나 받을 보너스, quest: 받을 의뢰 보상 }
create or replace function public.guild_dots() returns jsonb language plpgsql security definer set search_path = public as $$
declare rl jsonb; qs jsonb;
begin
  if (_guild_me(auth.uid())).user_id is null then return jsonb_build_object('ok', true, 'rally', false, 'quest', false); end if;
  rl := guild_rally(); qs := guild_quests();
  return jsonb_build_object('ok', true,
    'rally', not (rl->>'checked')::boolean or exists (select 1 from jsonb_array_elements(rl->'tiers') t where (t->>'reached')::boolean and not (t->>'claimed')::boolean)
             or ((rl->>'week_claimable')::boolean and not (rl->>'week_claimed')::boolean),
    'quest', exists (select 1 from jsonb_array_elements(qs->'daily') x where (x->>'progress')::int >= (x->>'goal')::int and not (x->>'claimed')::boolean)
             or exists (select 1 from jsonb_array_elements(qs->'weekly') x, jsonb_array_elements(x->'tiers') t where (t->>'reached')::boolean and not (t->>'claimed')::boolean and (x->>'mine')::int >= (x->>'min')::int));
end $$;
revoke all on function public.guild_rally(), public.guild_checkin(), public.guild_rally_claim(int), public.guild_quests(), public.guild_quest_claim(int),
  public.guild_quest_reroll(int), public.guild_weekly_claim(int, int), public.guild_dots() from public, anon;
grant execute on function public.guild_rally(), public.guild_checkin(), public.guild_rally_claim(int), public.guild_quests(), public.guild_quest_claim(int),
  public.guild_quest_reroll(int), public.guild_weekly_claim(int, int), public.guild_dots() to authenticated;

-- 조직원 상세 (같은 조직만, 공개 정보만)
create or replace function public.guild_member_info(p_user uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare me guild_members; x guild_members; pr record;
begin
  me := _guild_me(auth.uid());
  if me.user_id is null then raise exception 'not in guild'; end if;
  select * into x from guild_members where user_id = p_user and guild_id = me.guild_id;
  if x.user_id is null then raise exception 'not member'; end if;
  select rating, wins, losses into pr from pvp_ratings where user_id = p_user and season = _pvp_season() order by rating desc limit 1;
  return jsonb_build_object('ok', true, 'user_id', x.user_id, 'name', coalesce((select nickname from profiles where id = p_user), '조직원'),
    'level', coalesce((select level from player_state where user_id = p_user), 1), 'role', x.role, 'joined_at', x.joined_at, 'seen_at', x.seen_at,
    'loyalty_total', x.loyalty_total,
    'loyalty_week', coalesce((select sum(delta) from loyalty_ledger where user_id = p_user and delta > 0 and created_at >= (_guild_week()::timestamp at time zone 'Asia/Seoul')), 0),
    'pvp', case when pr.rating is null then null else jsonb_build_object('rating', pr.rating, 'tier', _pvp_tier(pr.rating), 'wins', pr.wins, 'losses', pr.losses) end,
    'card', (select o->>'id' from story_progress sp, jsonb_array_elements(coalesce(sp.data->'owned', '[]'::jsonb)) o where sp.user_id = p_user and o->>'uid' = sp.data->>'leader' limit 1),
    'top', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'level', t.lv) order by t.lv desc), '[]'::jsonb) from (
              select o->>'id' id, max(coalesce((o->>'level')::int, 1)) lv from story_progress sp, jsonb_array_elements(coalesce(sp.data->'owned', '[]'::jsonb)) o
              where sp.user_id = p_user and o ? 'id' group by o->>'id' order by 2 desc limit 3) t));
end $$;
revoke all on function public.guild_member_info(uuid) from public, anon;
grant execute on function public.guild_member_info(uuid) to authenticated;

-- 6) 관리자: 조직 출석·의뢰 보기 · 주간 의뢰 다시 뽑기
create or replace function public.admin_guild_activity(p_gid bigint) returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
begin
  perform public._admin_guard();
  return jsonb_build_object('rally', _guild_rally_count(p_gid),
    'attendance_7d', (select coalesce(jsonb_object_agg(day, n), '{}'::jsonb) from (select day, count(*) n from guild_attendance where guild_id = p_gid and day > _guild_day() - 7 group by day) x),
    'weekly', (select coalesce(jsonb_agg(to_jsonb(q) order by slot), '[]'::jsonb) from guild_weekly_quests q where guild_id = p_gid and week = _guild_week()));
end $$;
create or replace function public.admin_guild_reset_weekly(p_gid bigint, p_reason text) returns jsonb language plpgsql volatile security definer set search_path = public, auth as $$
begin
  perform public._admin_guard();
  if coalesce(btrim(p_reason), '') = '' then raise exception 'reason required'; end if;
  delete from guild_weekly_quests where guild_id = p_gid and week = _guild_week();
  delete from guild_weekly_contrib where guild_id = p_gid and week = _guild_week();
  perform _guild_roll_weekly(p_gid);
  insert into public.admin_log (admin_id, admin_email, action, target_user, amount, reason) values (auth.uid(), auth.jwt()->>'email', 'guild_reset_weekly', null, p_gid::int, left(btrim(p_reason), 200));
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.admin_guild_activity(bigint), public.admin_guild_reset_weekly(bigint, text) from public, anon;
grant execute on function public.admin_guild_activity(bigint), public.admin_guild_reset_weekly(bigint, text) to authenticated;


-- 7) 스토리·PvP 연동 (phaseE_3.sql / phaseE_5.sql / guild.sql 과 같은 정의 — 이 파일만 실행해도 되도록 복사. tools/test_guild2_sql.mjs 가 일치 확인)
create or replace function public.story_complete_phase(p_chapter int, p_phase int, p_stats jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
-- phaseE_2 wrapper
declare uid uuid := auth.uid(); b jsonb; spent int; r jsonb; cfg story_phase_config; xp int; up jsonb; drops jsonb := null;
begin
  if uid is null then raise exception 'login required'; end if;
  select data->'battle' into b from story_progress where user_id = uid;
  spent := coalesce((b->>'stamina')::int, 0);
  r := _story_complete_phase_e0(p_chapter, p_phase, p_stats);
  select * into cfg from story_phase_config where chapter = p_chapter and phase = p_phase;
  xp := spent * _player_xp_per_stamina() + case when coalesce((r->>'first')::boolean, false) then _player_first_bonus(cfg.type) else 0 end;
  perform _player_sync(uid);
  up := _player_add_xp(uid, xp, true);
  -- 조직 의뢰 진행 (guild2.sql): 페이즈 클리어 · 행동력 · 보스
  if to_regprocedure('public._guild_event(uuid,text,integer)') is not null then
    perform _guild_event(uid, 'phase', 1); perform _guild_event(uid, 'stamina', spent);
    if cfg.type = 'boss' then perform _guild_event(uid, 'boss', 1); end if;
  end if;
  -- 재화 드롭 (phaseE_3.sql 의 _story_drops 가 있으면)
  if to_regprocedure('public._story_drops(uuid,integer,integer,boolean)') is not null then
    execute 'select public._story_drops($1, $2, $3, $4)' into drops using uid, p_chapter, p_phase, coalesce((r->>'first')::boolean, false);
  end if;
  return r || jsonb_build_object('player', _player_json(uid) || jsonb_build_object('gained_xp', xp, 'levelups', up->'levelups', 'levelup_gold', up->'gold'))
           || case when drops is null then '{}'::jsonb else jsonb_build_object('drops', drops) end;
end $$;
revoke all on function public.story_complete_phase(int, int, jsonb) from public, anon;
grant execute on function public.story_complete_phase(int, int, jsonb) to authenticated;
create or replace function public.story_sweep(p_chapter int, p_phase int, p_runs int default 1) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); d jsonb; cfg story_phase_config; cost int; xp int; up jsonb; dr jsonb;
  tot jsonb := '{"gold":0,"blood":0,"shard":0,"soul":0}'::jsonb; runs jsonb := '[]'::jsonb; k text; w jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  if p_runs is null or p_runs not in (1, 5, 10) then raise exception 'invalid runs'; end if;
  if not _player_unlocked(uid, 'sweep') then raise exception 'sweep locked (player Lv%)', _player_unlock_level('sweep'); end if;
  select * into cfg from story_phase_config where chapter = p_chapter and phase = p_phase;
  if not found then raise exception 'unknown phase'; end if;
  select data into d from story_progress where user_id = uid for update;
  if not (coalesce(d->'cleared'->(p_chapter::text), '[]'::jsonb) @> to_jsonb(p_phase)) then raise exception 'not cleared'; end if;
  cost := _stamina_cost(p_chapter, p_phase);
  perform _player_stamina_add(uid, -cost * p_runs);   -- 부족하면 'not enough stamina' (전체 롤백)
  for i in 1..p_runs loop
    dr := _story_drop_calc(p_chapter, coalesce(cfg.type, 'normal'), false, cost, random()::numeric, random()::numeric);
    runs := runs || dr;
    foreach k in array array['gold','blood','shard','soul'] loop
      tot := jsonb_set(tot, array[k], to_jsonb((tot->>k)::int + coalesce((dr->>k)::int, 0)));
    end loop;
  end loop;
  w := _wallet_add(uid, tot, 'story_sweep');
  xp := cost * p_runs * _player_xp_per_stamina();
  up := _player_add_xp(uid, xp, true);
  -- 조직 의뢰 진행 (guild2.sql): 소탕 1회 = 페이즈 1 · 행동력 · 보스
  if to_regprocedure('public._guild_event(uuid,text,integer)') is not null then
    perform _guild_event(uid, 'phase', p_runs); perform _guild_event(uid, 'stamina', cost * p_runs);
    if cfg.type = 'boss' then perform _guild_event(uid, 'boss', p_runs); end if;
  end if;
  return jsonb_build_object('ok', true, 'chapter', p_chapter, 'phase', p_phase, 'runs', p_runs, 'stamina', cost * p_runs,
    'drops', tot, 'per_run', runs, 'wallet', w,
    'player', _player_json(uid) || jsonb_build_object('gained_xp', xp, 'levelups', up->'levelups', 'levelup_gold', up->'gold'));
end $$;
revoke all on function public.story_sweep(int, int, int) from public, anon;
grant execute on function public.story_sweep(int, int, int) to authenticated;
create or replace function public._guild_feed(p_uid uuid, p_src text, p_n int) returns int language plpgsql security definer set search_path = public as $$
declare m guild_members; used int; n int;
begin
  select * into m from guild_members where user_id = p_uid;
  if m.user_id is null or coalesce(p_n, 0) <= 0 then return 0; end if;
  if p_src = 'pvp' and to_regprocedure('public._guild_event(uuid,text,integer)') is not null then perform _guild_event(p_uid, 'pvp_win', 1); end if;   -- 조직 의뢰 (guild2.sql)
  select coalesce(sum(amount), 0) into used from guild_exp_log where user_id = p_uid and day = _guild_day() and src = p_src;
  n := least(p_n, _guild_feed_cap(p_src) - used);
  if n <= 0 then return 0; end if;
  perform _guild_exp(m.guild_id, p_uid, n, p_src, null);
  perform _loyalty_add(p_uid, n, 'feed:' || p_src, null, jsonb_build_object('guild', m.guild_id));
  return n;
end $$;
revoke all on function public._guild_feed(uuid, text, int) from public, anon, authenticated;


-- ===== SOURCE: guild3.sql =====
-- ⚠ 다시 돌리지 마세요, 최신 아님 (일부): 이 파일의 _raid_numbers 는 뒤 파일에서 다시 정의됨. 이 파일을 다시 돌리면 예전 것으로 되돌아가요. supabase/README.md 참고
-- 조직 3단계: 「균열 토벌」 (조직 레이드). 여러 번 실행해도 안전.
-- 선행: guild.sql · guild2.sql · pvp.sql(_pvp_snap · pvp_card_meta) · gem.sql
-- 주기: 매주 월 00:00 ~ 일 22:00 (KST) 토벌, 일 22:00 부터 순위 보상 수령. 하루 3회(행동력 없음) · 소탕 = 오늘 최고 기록 90% (그날 1회 이상 직접 싸운 뒤)
-- 전투: 브라우저 js/raid-core.js (서버 seed + 서버가 만든 덱 스냅샷, 자동 전투). 서버는 한 판 상한·최소 시간 검사 + seed·스냅샷 보관 → tools/raid_verify.mjs 로 재검증
-- 보스: 단계별 1 임유리 · 2 [각성] 임유리 · 3 김신현 · 4 김성진 · 5 이지영 → 6단계부터 다시 1번, HP 는 단계마다 ×1.35
-- 보상 숫자는 전부 _raid_numbers() 하나에 있음

-- 1) 테이블
create table if not exists public.guild_raids (
  guild_id bigint not null references public.guilds(id) on delete cascade, week date not null,
  difficulty text not null default 'normal' check (difficulty in ('normal', 'hard', 'abyss')),
  members int not null, stage int not null default 1, hp_max bigint not null, hp_left bigint not null,
  total_damage bigint not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  primary key (guild_id, week));
create table if not exists public.guild_raid_stages (
  guild_id bigint not null, week date not null, stage int not null, boss_id text, hp bigint not null,
  cleared_at timestamptz, last_hit uuid references auth.users(id) on delete set null,
  primary key (guild_id, week, stage), foreign key (guild_id, week) references public.guild_raids(guild_id, week) on delete cascade);
create table if not exists public.guild_raid_attempts (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade, guild_id bigint not null, week date not null, day date not null,
  kind text not null check (kind in ('fight', 'sweep')), stage int not null, difficulty text not null,
  seed bigint, snap jsonb, reported bigint, damage bigint not null default 0, flagged boolean not null default false, voided boolean not null default false,
  started_at timestamptz not null default now(), finished_at timestamptz);
create index if not exists guild_raid_attempts_user on public.guild_raid_attempts (user_id, day);
create index if not exists guild_raid_attempts_guild on public.guild_raid_attempts (guild_id, week);
create table if not exists public.guild_raid_damage (
  guild_id bigint not null, week date not null, user_id uuid not null references auth.users(id) on delete cascade,
  damage bigint not null default 0, attempts int not null default 0, updated_at timestamptz not null default now(),
  primary key (guild_id, week, user_id));
do $$ declare t text; begin
  foreach t in array array['guild_raids', 'guild_raid_stages', 'guild_raid_attempts', 'guild_raid_damage'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
  end loop;
end $$;

-- 2) 숫자 (여기만 고치면 됨)
create or replace function public._raid_numbers() returns jsonb language sql immutable as $$ select '{
  "attempts_per_day": 3, "sweep_pct": 90, "min_secs": 3, "open_minutes": 20,
  "hp_per_member": {"normal": 500000, "hard": 1250000, "abyss": 3000000}, "hp_min_members": 5, "hp_growth": 1.35,
  "diff_level": {"normal": 1, "hard": 3, "abyss": 5}, "diff_mult": {"normal": 1, "hard": 1.6, "abyss": 2.5},
  "hit_cap": 6000, "hit_cap_growth": 1.1, "attempt_hits": 200,
  "attempt": {"loyalty": 5, "gold_base": 200, "gold_per_damage": 200, "gold_max": 2000, "exp": 5},
  "stage": {"loyalty": 20, "gold": 2000, "gem": 30, "gem_every3": 150, "tickets_every5": 1, "exp_per_stage": 30},
  "last_hit": {"loyalty": 10},
  "rank": [{"from": 1, "to": 1, "reward": {"gem": 1000, "loyalty": 100}}, {"from": 2, "to": 3, "reward": {"gem": 500, "loyalty": 70}}, {"from": 4, "to": 10, "reward": {"gem": 200, "loyalty": 40}}],
  "member": {"gem": 100, "loyalty": 20},
  "join_hours": 24
}'::jsonb $$;
-- 단계 → 보스 (js/raid-core.js RAID_BOSSES 와 같음)
create or replace function public._raid_boss(p_stage int) returns jsonb language sql immutable as $$
  select (array['{"id":"10325","name":"임유리","weak":"CHARGE"}', '{"id":"10326","name":"[각성] 임유리","weak":"DEFENSE"}',
                '{"id":"10062","name":"김신현","weak":"CRUSH"}', '{"id":"10060","name":"김성진","weak":"SUPPORT"}',
                '{"id":"10311","name":"이지영","weak":"DISTURB"}'])[((greatest(p_stage, 1) - 1) % 5) + 1]::jsonb $$;
create or replace function public._raid_now() returns timestamptz language sql stable as $$ select now() $$;   -- 테스트에서 바꿔 끼움
create or replace function public._raid_end(p_week date) returns timestamptz language sql stable as $$ select ((p_week + 6)::timestamp + interval '22 hours') at time zone 'Asia/Seoul' $$;
create or replace function public._raid_hp(p_diff text, p_members int, p_stage int) returns bigint language sql immutable as $$
  select round((_raid_numbers()->'hp_per_member'->>p_diff)::numeric * greatest(p_members, (_raid_numbers()->>'hp_min_members')::int)
               * power((_raid_numbers()->>'hp_growth')::numeric, greatest(p_stage, 1) - 1))::bigint $$;
create or replace function public._raid_attempt_cap(p_stage int) returns bigint language sql immutable as $$
  select round((_raid_numbers()->>'hit_cap')::numeric * power((_raid_numbers()->>'hit_cap_growth')::numeric, greatest(p_stage, 1) - 1)) * (_raid_numbers()->>'attempt_hits')::int $$;
-- 단계 처치 개인 보상 (난이도 배율: 충성·골드·심연석)
create or replace function public._raid_stage_reward(p_diff text, p_stage int) returns jsonb language sql immutable as $$
  with n as (select _raid_numbers() j), x as (select j->'stage' s, (j->'diff_mult'->>p_diff)::numeric m from n)
  select jsonb_strip_nulls(jsonb_build_object('loyalty', round((s->>'loyalty')::int * m)::int, 'gold', round((s->>'gold')::int * m)::int,
    'gem', round(((s->>'gem')::int + case when p_stage % 3 = 0 then (s->>'gem_every3')::int else 0 end) * m)::int,
    'tickets', case when p_stage % 5 = 0 then (s->>'tickets_every5')::int end)) from x $$;
create or replace function public._raid_rank_reward(p_rank int) returns jsonb language sql immutable as $$
  select coalesce((select r->'reward' from jsonb_array_elements(_raid_numbers()->'rank') r where p_rank between (r->>'from')::int and (r->>'to')::int), '{}'::jsonb) $$;

-- 3) 내부
-- 이번 주 레이드 (없으면 만듦: 그때 인원으로 HP 고정)
create or replace function public._raid_get(p_gid bigint, p_week date) returns guild_raids language plpgsql security definer set search_path = public as $$
declare r guild_raids; n int;
begin
  select * into r from guild_raids where guild_id = p_gid and week = p_week;
  if r.guild_id is not null then return r; end if;
  select count(*) into n from guild_members where guild_id = p_gid;
  insert into guild_raids (guild_id, week, members, hp_max, hp_left) values (p_gid, p_week, n, _raid_hp('normal', n, 1), _raid_hp('normal', n, 1)) on conflict do nothing;
  insert into guild_raid_stages (guild_id, week, stage, boss_id, hp) values (p_gid, p_week, 1, _raid_boss(1)->>'id', _raid_hp('normal', n, 1)) on conflict do nothing;
  select * into r from guild_raids where guild_id = p_gid and week = p_week;
  return r;
end $$;
-- 공유 HP 깎기 (넘친 피해는 다음 단계로). 반환 처치한 단계 수
create or replace function public._raid_hit(p_gid bigint, p_week date, p_uid uuid, p_dmg bigint) returns int language plpgsql security definer set search_path = public as $$
declare r guild_raids; d bigint := greatest(p_dmg, 0); k int := 0; nhp bigint;
begin
  select * into r from guild_raids where guild_id = p_gid and week = p_week for update;
  update guild_raids set total_damage = total_damage + d, updated_at = now() where guild_id = p_gid and week = p_week;
  while d > 0 and k < 100 loop
    if d < r.hp_left then r.hp_left := r.hp_left - d; d := 0;
    else
      d := d - r.hp_left; k := k + 1;
      update guild_raid_stages set cleared_at = now(), last_hit = p_uid where guild_id = p_gid and week = p_week and stage = r.stage;
      perform _guild_exp(p_gid, null, r.stage * (_raid_numbers()->'stage'->>'exp_per_stage')::int, 'raid_stage', 'raid:' || p_week || ':' || r.stage);
      perform _guild_reward(p_uid, p_gid, _raid_numbers()->'last_hit', 'raid_last_hit', 'raidlh:' || p_gid || ':' || p_week || ':' || r.stage);
      r.stage := r.stage + 1; nhp := _raid_hp(r.difficulty, r.members, r.stage); r.hp_max := nhp; r.hp_left := nhp;
      insert into guild_raid_stages (guild_id, week, stage, boss_id, hp) values (p_gid, p_week, r.stage, _raid_boss(r.stage)->>'id', nhp) on conflict do nothing;
    end if;
  end loop;
  update guild_raids set stage = r.stage, hp_max = r.hp_max, hp_left = r.hp_left where guild_id = p_gid and week = p_week;
  return k;
end $$;
-- 한 판 마감 (피해 기록 · 공유 HP · 1회 보상 · 의뢰 진행)
create or replace function public._raid_close(a guild_raid_attempts, p_dmg bigint) returns jsonb language plpgsql security definer set search_path = public as $$
declare N jsonb := _raid_numbers(); k int; rw jsonb;
begin
  update guild_raid_attempts set damage = p_dmg, finished_at = now() where id = a.id;
  insert into guild_raid_damage (guild_id, week, user_id, damage, attempts) values (a.guild_id, a.week, a.user_id, p_dmg, 1)
    on conflict (guild_id, week, user_id) do update set damage = guild_raid_damage.damage + p_dmg, attempts = guild_raid_damage.attempts + 1, updated_at = now();
  k := _raid_hit(a.guild_id, a.week, a.user_id, p_dmg);
  rw := jsonb_build_object('loyalty', (N->'attempt'->>'loyalty')::int,
    'gold', least((N->'attempt'->>'gold_max')::int, (N->'attempt'->>'gold_base')::int + (p_dmg / (N->'attempt'->>'gold_per_damage')::int)::int), 'exp', (N->'attempt'->>'exp')::int);
  perform _guild_reward(a.user_id, a.guild_id, rw, 'raid_attempt', 'raida:' || a.id);
  if to_regprocedure('public._guild_event(uuid,text,integer)') is not null then perform _guild_event(a.user_id, 'raid', 1); end if;
  return jsonb_build_object('damage', p_dmg, 'cleared', k, 'got', rw - 'exp');
end $$;
revoke all on function public._raid_get(bigint, date), public._raid_hit(bigint, date, uuid, bigint), public._raid_close(guild_raid_attempts, bigint) from public, anon, authenticated;

-- 4) 공개 RPC
-- 상태
create or replace function public.raid_status() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; g guilds; w date := _guild_week(); r guild_raids; N jsonb := _raid_numbers(); used int; best bigint; fought boolean; open_id bigint;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  select * into g from guilds where id = m.guild_id;
  r := _raid_get(m.guild_id, w);
  select count(*), coalesce(max(damage) filter (where kind = 'fight' and finished_at is not null and not voided), 0), bool_or(kind = 'fight' and finished_at is not null)
    into used, best, fought from guild_raid_attempts where user_id = uid and day = _guild_day();
  return jsonb_build_object('ok', true, 'week', w, 'ends_at', _raid_end(w), 'ended', _raid_now() >= _raid_end(w),
    'difficulty', r.difficulty, 'guild_level', g.level, 'diff_level', N->'diff_level', 'diff_mult', N->'diff_mult',
    'can_set_diff', m.role in ('boss', 'officer') and r.total_damage = 0,
    'stage', r.stage, 'hp_max', r.hp_max, 'hp_left', r.hp_left, 'total_damage', r.total_damage, 'boss', _raid_boss(r.stage), 'next_boss', _raid_boss(r.stage + 1),
    'attempts_left', greatest(0, (N->>'attempts_per_day')::int - used), 'best_today', best, 'can_sweep', coalesce(fought, false) and best > 0,
    'sweep_damage', best * (N->>'sweep_pct')::int / 100,
    'ranking', (select coalesce(jsonb_agg(jsonb_build_object('user_id', d.user_id, 'name', coalesce(p.nickname, '조직원'), 'damage', d.damage, 'attempts', d.attempts, 'me', d.user_id = uid) order by d.damage desc, d.user_id), '[]'::jsonb)
                from guild_raid_damage d left join profiles p on p.id = d.user_id where d.guild_id = m.guild_id and d.week = w and d.damage > 0),
    'stages', (select coalesce(jsonb_agg(jsonb_build_object('stage', s.stage, 'boss', _raid_boss(s.stage), 'cleared', s.cleared_at is not null,
                 'reward', _raid_stage_reward(r.difficulty, s.stage), 'claimed', exists (select 1 from guild_claims c where c.user_id = uid and c.ref = 'raidst:' || w || ':' || s.stage)) order by s.stage), '[]'::jsonb)
               from guild_raid_stages s where s.guild_id = m.guild_id and s.week = w),
    'rank_rewards', N->'rank', 'member_reward', N->'member', 'claimable', raid_claimable());
end $$;
-- 받을 수 있는 보상 수 (빨간 점)
create or replace function public.raid_claimable() returns int language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; w date; n int := 0;
begin
  m := _guild_me(uid);
  if m.user_id is null then return 0; end if;
  foreach w in array array[_guild_week(), _guild_week() - 7] loop
    n := n + (select count(*) from guild_raid_stages s join guild_raids r using (guild_id, week) where s.guild_id = m.guild_id and s.week = w and s.cleared_at is not null and m.joined_at <= s.cleared_at
              and not exists (select 1 from guild_claims c where c.user_id = uid and c.ref = 'raidst:' || w || ':' || s.stage));
    if _raid_now() >= _raid_end(w) and m.joined_at <= _raid_end(w) - make_interval(hours => (_raid_numbers()->>'join_hours')::int)
       and exists (select 1 from guild_raids where guild_id = m.guild_id and week = w)
       and not exists (select 1 from guild_claims c where c.user_id = uid and c.ref = 'raidrk:' || w) then n := n + 1; end if;
  end loop;
  return n;
end $$;
-- 난이도 (보스·간부, 이번 주 첫 피해 전까지)
create or replace function public.raid_set_difficulty(p_diff text) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; r guild_raids; lv int; w date := _guild_week(); nhp bigint;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  if m.role not in ('boss', 'officer') then raise exception 'not allowed'; end if;
  if p_diff not in ('normal', 'hard', 'abyss') then raise exception 'bad difficulty'; end if;
  select level into lv from guilds where id = m.guild_id;
  if lv < (_raid_numbers()->'diff_level'->>p_diff)::int then raise exception 'guild level'; end if;
  r := _raid_get(m.guild_id, w);
  select * into r from guild_raids where guild_id = m.guild_id and week = w for update;
  if r.total_damage > 0 then raise exception 'raid started'; end if;
  nhp := _raid_hp(p_diff, r.members, 1);
  update guild_raids set difficulty = p_diff, stage = 1, hp_max = nhp, hp_left = nhp, updated_at = now() where guild_id = m.guild_id and week = w;
  update guild_raid_stages set hp = nhp where guild_id = m.guild_id and week = w and stage = 1;
  return raid_status();
end $$;
-- 전투 시작: 횟수 차감 · 덱 스냅샷 · seed
create or replace function public.raid_start(p_uids jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; w date := _guild_week(); r guild_raids; N jsonb := _raid_numbers(); snap jsonb; seed bigint; aid bigint;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  if _raid_now() >= _raid_end(w) then raise exception 'raid ended'; end if;
  perform pg_advisory_xact_lock(hashtext('raid:' || uid));
  -- 끝내지 않은 판은 0 피해로 마감 (횟수는 이미 씀)
  update guild_raid_attempts set finished_at = now(), damage = 0 where user_id = uid and finished_at is null;
  if (select count(*) from guild_raid_attempts where user_id = uid and day = _guild_day()) >= (N->>'attempts_per_day')::int then raise exception 'no attempts'; end if;
  r := _raid_get(m.guild_id, w);
  snap := _pvp_snap(uid, p_uids, 'open')->'cards';
  seed := floor(random() * 2147483647)::bigint;
  insert into guild_raid_attempts (user_id, guild_id, week, day, kind, stage, difficulty, seed, snap)
    values (uid, m.guild_id, w, _guild_day(), 'fight', r.stage, r.difficulty, seed, snap) returning id into aid;
  return jsonb_build_object('ok', true, 'id', aid, 'seed', seed, 'deck', snap, 'stage', r.stage, 'difficulty', r.difficulty, 'boss', _raid_boss(r.stage));
end $$;
-- 전투 끝: 피해 보고 (한 판 상한 · 최소 시간)
create or replace function public.raid_finish(p_id bigint, p_damage bigint) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); a guild_raid_attempts; N jsonb := _raid_numbers(); cap bigint; d bigint; res jsonb;
begin
  select * into a from guild_raid_attempts where id = p_id and user_id = uid for update;
  if a.id is null then raise exception 'no battle'; end if;
  if a.finished_at is not null then raise exception 'already finished'; end if;
  if now() - a.started_at < make_interval(secs => (N->>'min_secs')::int) then raise exception 'too fast'; end if;
  if now() - a.started_at > make_interval(mins => (N->>'open_minutes')::int) then
    update guild_raid_attempts set finished_at = now(), damage = 0 where id = a.id; raise exception 'battle expired'; end if;
  if _raid_now() >= _raid_end(a.week) + interval '5 minutes' then raise exception 'raid ended'; end if;
  if not exists (select 1 from guild_members where user_id = uid and guild_id = a.guild_id) then raise exception 'not in guild'; end if;
  cap := _raid_attempt_cap(a.stage); d := least(greatest(coalesce(p_damage, 0), 0), cap);
  update guild_raid_attempts set reported = p_damage, flagged = p_damage > cap where id = a.id;
  res := _raid_close(a, d);
  return raid_status() || jsonb_build_object('result', res);
end $$;
-- 소탕: 오늘 직접 싸운 최고 기록의 90% (횟수 1 사용)
create or replace function public.raid_sweep() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; w date := _guild_week(); r guild_raids; N jsonb := _raid_numbers(); best bigint; a guild_raid_attempts; res jsonb;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  if _raid_now() >= _raid_end(w) then raise exception 'raid ended'; end if;
  perform pg_advisory_xact_lock(hashtext('raid:' || uid));
  if (select count(*) from guild_raid_attempts where user_id = uid and day = _guild_day()) >= (N->>'attempts_per_day')::int then raise exception 'no attempts'; end if;
  select max(damage) into best from guild_raid_attempts where user_id = uid and day = _guild_day() and kind = 'fight' and finished_at is not null and not voided;
  if coalesce(best, 0) <= 0 then raise exception 'fight first'; end if;
  r := _raid_get(m.guild_id, w);
  insert into guild_raid_attempts (user_id, guild_id, week, day, kind, stage, difficulty) values (uid, m.guild_id, w, _guild_day(), 'sweep', r.stage, r.difficulty) returning * into a;
  res := _raid_close(a, best * (N->>'sweep_pct')::int / 100);
  return raid_status() || jsonb_build_object('result', res);
end $$;
-- 보상 모두 받기: 처치 단계(그때 조직원이었던 사람) · 주간 순위/참여(정산 24시간 전 가입, 지금도 같은 조직)
create or replace function public.raid_claim() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; w date; s record; rr guild_raids; got jsonb := '{}'::jsonb; rw jsonb; k text; rk int;
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  foreach w in array array[_guild_week() - 7, _guild_week()] loop
    select * into rr from guild_raids where guild_id = m.guild_id and week = w;
    if rr.guild_id is null then continue; end if;
    for s in select * from guild_raid_stages where guild_id = m.guild_id and week = w and cleared_at is not null and m.joined_at <= cleared_at order by stage loop
      if exists (select 1 from guild_claims where user_id = uid and ref = 'raidst:' || w || ':' || s.stage) then continue; end if;
      rw := _raid_stage_reward(rr.difficulty, s.stage);
      perform _guild_reward(uid, m.guild_id, rw, 'raid_stage', 'raidst:' || w || ':' || s.stage);
      for k in select jsonb_object_keys(rw) loop got := jsonb_set(got, array[k], to_jsonb(coalesce((got->>k)::int, 0) + (rw->>k)::int)); end loop;
    end loop;
    if _raid_now() >= _raid_end(w) and m.joined_at <= _raid_end(w) - make_interval(hours => (_raid_numbers()->>'join_hours')::int)
       and not exists (select 1 from guild_claims where user_id = uid and ref = 'raidrk:' || w) then
      select x.rk into rk from (select user_id, row_number() over (order by damage desc, user_id) rk from guild_raid_damage where guild_id = m.guild_id and week = w and damage > 0) x where x.user_id = uid;
      rw := _raid_numbers()->'member';
      if rk is not null then
        for k in select jsonb_object_keys(_raid_rank_reward(rk)) loop rw := jsonb_set(rw, array[k], to_jsonb(coalesce((rw->>k)::int, 0) + (_raid_rank_reward(rk)->>k)::int)); end loop;
      end if;
      perform _guild_reward(uid, m.guild_id, rw || jsonb_build_object('rank', rk), 'raid_rank', 'raidrk:' || w);
      for k in select jsonb_object_keys(rw) loop got := jsonb_set(got, array[k], to_jsonb(coalesce((got->>k)::int, 0) + (rw->>k)::int)); end loop;
      got := got || jsonb_build_object('rank', rk);
    end if;
  end loop;
  if got = '{}'::jsonb then raise exception 'nothing to claim'; end if;
  return raid_status() || jsonb_build_object('got', got);
end $$;
revoke all on function public.raid_status(), public.raid_claimable(), public.raid_set_difficulty(text), public.raid_start(jsonb), public.raid_finish(bigint, bigint), public.raid_sweep(), public.raid_claim() from public, anon;
grant execute on function public.raid_status(), public.raid_claimable(), public.raid_set_difficulty(text), public.raid_start(jsonb), public.raid_finish(bigint, bigint), public.raid_sweep(), public.raid_claim() to authenticated;

-- 5) 관리자: 조직 토벌 현황 · 의심 기록 · 기록 무효(사유 필수, 개인 누적만 빼고 공유 HP 는 그대로)
create or replace function public.admin_guild_raid(p_gid bigint) returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
begin
  perform public._admin_guard();
  return jsonb_build_object('raid', (select to_jsonb(r) from guild_raids r where guild_id = p_gid and week = _guild_week()),
    'flagged', (select coalesce(jsonb_agg(to_jsonb(a) - 'snap' order by a.id desc), '[]'::jsonb) from (select * from guild_raid_attempts where guild_id = p_gid and flagged order by id desc limit 50) a),
    'top', (select coalesce(jsonb_agg(to_jsonb(d) order by d.damage desc), '[]'::jsonb) from guild_raid_damage d where guild_id = p_gid and week = _guild_week()));
end $$;
create or replace function public.admin_raid_void(p_id bigint, p_reason text) returns jsonb language plpgsql volatile security definer set search_path = public, auth as $$
declare a guild_raid_attempts;
begin
  perform public._admin_guard();
  if coalesce(btrim(p_reason), '') = '' then raise exception 'reason required'; end if;
  select * into a from guild_raid_attempts where id = p_id for update;
  if a.id is null or a.voided then raise exception 'no attempt'; end if;
  update guild_raid_attempts set voided = true where id = p_id;
  update guild_raid_damage set damage = greatest(0, damage - a.damage) where guild_id = a.guild_id and week = a.week and user_id = a.user_id;
  insert into public.admin_log (admin_id, admin_email, action, target_user, amount, reason) values (auth.uid(), auth.jwt()->>'email', 'raid_void', a.user_id, least(a.damage, 2147483647)::int, left(btrim(p_reason), 200));
  return jsonb_build_object('ok', true, 'voided', p_id, 'damage', a.damage);
end $$;
revoke all on function public.admin_guild_raid(bigint), public.admin_raid_void(bigint, text) from public, anon;
grant execute on function public.admin_guild_raid(bigint), public.admin_raid_void(bigint, text) to authenticated;


-- ===== SOURCE: guild4.sql =====
-- ⚠ 다시 돌리지 마세요, 최신 아님 (일부): 이 파일의 _war_lock, _war_npc_deck, _war_numbers 는 뒤 파일에서 다시 정의됨. 이 파일을 다시 돌리면 예전 것으로 되돌아가요. supabase/README.md 참고
-- 조직 4단계: 「구역 전쟁」 (조직 대 조직). 여러 번 실행해도 안전.
-- 선행: guild.sql · guild2.sql(_guild_reward · guild_claims) · pvp.sql(_pvp_snap · pvp_card_meta) · gem.sql · admin.sql
-- 시즌: 매달 셋째 수요일 ~ 일요일 (KST, 5일). 매일 09:00~23:00 전투, 하루 1경기 = 상대 5개 조직.
--   1일차: 세력(exp) 비슷한 조직끼리 · 2일차부터: 승점 가까운 조직끼리 (이미 붙은 상대는 피함). 홀수면 「동네 불량배파」(NPC) 와 붙음.
-- 명단 21칸: 1~5 방어조 · 6~10 돌격조 · 11~13 중간보스 · 14 보스 · 15~21 조직원. 보스(조직장)가 배치, 시즌 시작(셋째 수 09:00)에 잠김.
--   빈 칸 = 동네 불량배(NPC, HR 2 + R 3 · 남녀 섞임 · 조직 평균 등급에 맞춰 강해짐). 실제 조직원 10명 미만이면 참가 불가.
-- 덱: 방어 2 · 공격 2. 방어 덱은 시즌 시작 때 스냅샷으로 잠김 (2번 덱 = 목숨 하나 더). 공격 덱은 그날 처음 쓸 때 스냅샷.
-- 전투: 브라우저 js/war-core.js (서버 seed + 서버 스냅샷 + 현재 HP, 양쪽 자동). 쓰러진 카드는 그 경기 동안 빠지고, 살아남은 카드는 깎인 HP 그대로.
-- 순서: 상대 방어조 5곳을 모두 부숴야 나머지 공격 가능. 보스 아지트 파괴 = 즉시 승리(그 경기 공격 끝, 승점 반영은 23:00 정산). 아니면 23:00 에 점수 높은 쪽 승리.
-- 숫자는 전부 _war_numbers() 하나에 있음

-- 1) 테이블
create table if not exists public.war_decks (
  user_id uuid primary key references auth.users(id) on delete cascade,
  def1 jsonb, def2 jsonb, atk1 jsonb, atk2 jsonb, updated_at timestamptz not null default now());
create table if not exists public.war_entries (
  season date not null, guild_id bigint not null references public.guilds(id) on delete cascade,
  status text not null default 'in' check (status in ('in', 'out')), locked boolean not null default false, scale numeric not null default 1,
  points int not null default 0, wins int not null default 0, draws int not null default 0, losses int not null default 0, boss_kills int not null default 0, score_total int not null default 0,
  entered_at timestamptz not null default now(), primary key (season, guild_id));
create table if not exists public.war_roster (
  season date not null, guild_id bigint not null, slot int not null check (slot between 1 and 21), user_id uuid references auth.users(id) on delete set null,
  def_snap jsonb, primary key (season, guild_id, slot), foreign key (season, guild_id) references public.war_entries(season, guild_id) on delete cascade);
create unique index if not exists war_roster_user on public.war_roster (season, user_id) where user_id is not null;
create table if not exists public.war_matches (
  id bigint generated always as identity primary key, season date not null, day int not null check (day between 1 and 5),
  guild_a bigint not null, guild_b bigint, score_a int not null default 0, score_b int not null default 0,
  winner bigint, draw boolean not null default false, boss_kill boolean not null default false, ended_at timestamptz, settled boolean not null default false,
  unique (season, day, guild_a));
create index if not exists war_matches_b on public.war_matches (season, day, guild_b);
create table if not exists public.war_ajits (
  match_id bigint not null references public.war_matches(id) on delete cascade, side int not null check (side in (0, 1)), slot int not null,
  role text not null, user_id uuid, npc boolean not null default false, snaps jsonb not null default '[]'::jsonb,
  deck int not null default 1, state jsonb, destroyed_at timestamptz, destroyed_by uuid, locked_by uuid, locked_until timestamptz,
  primary key (match_id, side, slot));
create table if not exists public.war_atk_state (
  match_id bigint not null references public.war_matches(id) on delete cascade, user_id uuid not null, deck int not null check (deck in (1, 2)),
  snap jsonb not null, state jsonb, primary key (match_id, user_id, deck));
create table if not exists public.war_attacks (
  id bigint generated always as identity primary key, match_id bigint not null references public.war_matches(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade, side int not null, target_slot int not null, atk_deck int not null, def_deck int not null,
  seed bigint not null, atk_snap jsonb not null, def_snap jsonb not null, atk_buff jsonb not null, def_buff jsonb not null,
  before jsonb not null, reported jsonb, win boolean, points int not null default 0, flagged boolean not null default false, voided boolean not null default false,
  started_at timestamptz not null default now(), finished_at timestamptz);
create index if not exists war_attacks_user on public.war_attacks (user_id, match_id);
do $$ declare t text; begin
  foreach t in array array['war_decks', 'war_entries', 'war_roster', 'war_matches', 'war_ajits', 'war_atk_state', 'war_attacks'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
  end loop;
end $$;

-- 2) 숫자 (여기만 고치면 됨)
create or replace function public._war_numbers() returns jsonb language sql immutable as $$ select '{
  "min_members": 10, "attacks_per_day": 5, "open_hour": 9, "close_hour": 23, "min_secs": 3, "open_minutes": 20, "lock_minutes": 3, "hp_cap": 60000,
  "layout": {"def": [1,2,3,4,5], "atk": [6,7,8,9,10], "mid": [11,12,13], "boss": [14], "etc": [15,16,17,18,19,20,21]},
  "roles": {"def": {"atk": 1, "def": 1.2}, "atk": {"atk": 1.2, "def": 1}, "mid": {"atk": 1.15, "def": 1.15}, "boss": {"atk": 1.25, "def": 1.25}, "etc": {"atk": 1, "def": 1}},
  "points": {"def": 200, "atk": 150, "etc": 150, "mid": 250, "boss": 400},
  "standings": {"win": 3, "draw": 2, "loss": 0, "boss_bonus": 1},
  "npc_level": 10, "npc_scale": 1, "signup_days_before": 3,
  "match_win": {"loyalty": 60, "gold": 5000}, "match_boss_kill": {"loyalty": 20, "gold": 2000}, "match_draw": {"loyalty": 20, "gold": 1500}, "match_loss": {"loyalty": 10}, "match_exp_win": 300,
  "season_rank": [{"from": 1, "to": 1, "reward": {"gem": 1000, "loyalty": 300}}, {"from": 2, "to": 2, "reward": {"gem": 700, "loyalty": 200}}, {"from": 3, "to": 3, "reward": {"gem": 500, "loyalty": 150}},
                  {"from": 4, "to": 10, "reward": {"gem": 300, "loyalty": 100}}, {"from": 11, "to": 30, "reward": {"gem": 150, "loyalty": 50}}],
  "season_member": {"gem": 100, "loyalty": 30}
}'::jsonb $$;
create or replace function public._war_role(p_slot int) returns text language sql immutable as $$
  select case when p_slot <= 5 then 'def' when p_slot <= 10 then 'atk' when p_slot <= 13 then 'mid' when p_slot = 14 then 'boss' else 'etc' end $$;

-- 3) 시간 (KST)
create or replace function public._war_now() returns timestamptz language sql stable as $$ select now() $$;   -- 테스트에서 바꿔 끼움
create or replace function public._war_kst() returns timestamp language sql stable as $$ select _war_now() at time zone 'Asia/Seoul' $$;
create or replace function public._war_third_wed(p_d date) returns date language sql immutable as $$
  select (date_trunc('month', p_d)::date + ((3 - extract(isodow from date_trunc('month', p_d))::int + 7) % 7) + 14) $$;
-- 지금 시즌 (진행 중 · 끝난 날 당일 · 아니면 다음 시즌)
create or replace function public._war_season() returns date language sql stable as $$
  select case when _war_kst()::date <= _war_third_wed(_war_kst()::date) + 4 then _war_third_wed(_war_kst()::date)
              else _war_third_wed((date_trunc('month', _war_kst()) + interval '1 month')::date) end $$;
create or replace function public._war_at(p_season date, p_day int, p_hour int) returns timestamptz language sql immutable as $$
  select ((p_season + p_day - 1)::timestamp + make_interval(hours => p_hour)) at time zone 'Asia/Seoul' $$;
-- 오늘 몇 일차 (1~5, 아니면 null)
create or replace function public._war_day(p_season date) returns int language sql stable as $$
  select case when _war_kst()::date between p_season and p_season + 4 then (_war_kst()::date - p_season) + 1 end $$;
create or replace function public._war_phase(p_season date) returns text language sql stable as $$
  select case when _war_now() < _war_at(p_season, 1 - (_war_numbers()->>'signup_days_before')::int, 0) then 'soon'
              when _war_now() < _war_at(p_season, 1, (_war_numbers()->>'open_hour')::int) then 'signup'
              when _war_now() >= _war_at(p_season, 5, (_war_numbers()->>'close_hour')::int) then 'ended'
              when extract(hour from _war_kst()) >= (_war_numbers()->>'open_hour')::int and extract(hour from _war_kst()) < (_war_numbers()->>'close_hour')::int then 'live'
              else 'rest' end $$;

-- 4) 동네 불량배 (NPC): HR 2 + R 3, 남녀 섞임, seed 로 고정
create or replace function public._war_npc_deck(p_seed text, p_scale numeric) returns jsonb language plpgsql stable as $$
declare hr text[] := array['10151','10152','10163','10164','10165','10166','10167','10168'];
        r text[] := array['10148','10149','10150','10159','10160','10161','10162'];
        male text[] := array['10148','10149','10150','10151','10152'];   -- 성별은 ID 첫 자리가 아니라 카드 데이터(gender)로 (ID 변경 후에도 맞게)
        a text[]; b text[]; ids text[]; alt text; out jsonb := '[]'::jsonb; i int;
begin
  select array_agg(x order by md5(p_seed || ':h:' || x)) into a from unnest(hr) x;
  select array_agg(x order by md5(p_seed || ':r:' || x)) into b from unnest(r) x;
  ids := a[1:2] || b[1:3];
  if (select count(distinct (x = any(male))) from unnest(ids) x) < 2 then
    select x into alt from unnest(b[4:7]) x where (x = any(male)) <> (ids[1] = any(male)) limit 1;
    ids[5] := alt;
  end if;
  for i in 1..5 loop out := out || jsonb_build_object('uid', 'n' || i, 'id', ids[i], 'level', (_war_numbers()->>'npc_level')::int, 'scale', p_scale); end loop;
  return out;
end $$;
-- 동네 불량배 = 고정 약체 (레벨 10 · 배율 1, 조직 덱과 무관)
create or replace function public._war_scale(p_season date, p_gid bigint) returns numeric language sql stable security definer set search_path = public as $$
  select coalesce((_war_numbers()->>'npc_scale')::numeric, 1) $$;

-- 5) 진행 (모든 공개 RPC 가 먼저 부름): 시즌 잠금 · 매일 대진 · 23시 정산
create or replace function public._war_lock(p_season date) returns void language plpgsql security definer set search_path = public as $$
declare e record; u record; s int; n int; sc numeric;
begin
  for e in select * from war_entries where season = p_season and not locked loop
    -- 배치 안 된 조직원 → 빈 칸
    for u in select gm.user_id from guild_members gm where gm.guild_id = e.guild_id
               and not exists (select 1 from war_roster r where r.season = p_season and r.user_id = gm.user_id) order by gm.joined_at loop
      select min(x) into s from generate_series(1, 21) x where not exists (select 1 from war_roster r where r.season = p_season and r.guild_id = e.guild_id and r.slot = x and r.user_id is not null);
      exit when s is null;
      insert into war_roster (season, guild_id, slot, user_id) values (p_season, e.guild_id, s, u.user_id) on conflict (season, guild_id, slot) do update set user_id = excluded.user_id;
    end loop;
    -- 떠난 사람 정리 · 방어 덱 잠금
    update war_roster r set user_id = null where r.season = p_season and r.guild_id = e.guild_id and r.user_id is not null
      and not exists (select 1 from guild_members gm where gm.user_id = r.user_id and gm.guild_id = e.guild_id);
    update war_roster r set def_snap = (select case when d.def1 is null then null else jsonb_build_array(d.def1, coalesce(d.def2, '[]'::jsonb)) end from war_decks d where d.user_id = r.user_id)
      where r.season = p_season and r.guild_id = e.guild_id and r.user_id is not null;
    select count(*) into n from war_roster where season = p_season and guild_id = e.guild_id and user_id is not null;
    sc := _war_scale(p_season, e.guild_id);
    update war_entries set locked = true, scale = sc, status = case when n >= (_war_numbers()->>'min_members')::int then 'in' else 'out' end where season = p_season and guild_id = e.guild_id;
  end loop;
end $$;
-- 한 쪽 아지트 21곳 만들기
create or replace function public._war_build_side(p_mid bigint, p_side int, p_season date, p_gid bigint, p_scale numeric) returns void language plpgsql security definer set search_path = public as $$
declare i int; r war_roster; sn jsonb;
begin
  for i in 1..21 loop
    r := null;
    if p_gid is not null then select * into r from war_roster where season = p_season and guild_id = p_gid and slot = i; end if;
    sn := case when r.def_snap is not null and jsonb_array_length(coalesce(r.def_snap->0, '[]'::jsonb)) > 0 then r.def_snap
               else jsonb_build_array(_war_npc_deck(p_mid || ':' || p_side || ':' || i || ':1', p_scale), _war_npc_deck(p_mid || ':' || p_side || ':' || i || ':2', p_scale)) end;
    insert into war_ajits (match_id, side, slot, role, user_id, npc, snaps) values (p_mid, p_side, i, _war_role(i), r.user_id, r.def_snap is null or jsonb_array_length(coalesce(r.def_snap->0, '[]'::jsonb)) = 0, sn)
      on conflict do nothing;
  end loop;
end $$;
create or replace function public._war_pair(p_season date, p_day int) returns void language plpgsql security definer set search_path = public as $$
declare ids bigint[]; used bigint[] := '{}'; a bigint; b bigint; mid bigint; i int; j int; sa numeric; sb numeric;
begin
  if exists (select 1 from war_matches where season = p_season and day = p_day) then return; end if;
  if p_day = 1 then
    select array_agg(e.guild_id order by g.exp desc, g.level desc, e.guild_id) into ids from war_entries e join guilds g on g.id = e.guild_id where e.season = p_season and e.status = 'in';
  else
    select array_agg(e.guild_id order by e.points desc, e.score_total desc, e.guild_id) into ids from war_entries e where e.season = p_season and e.status = 'in';
  end if;
  if ids is null then return; end if;
  for i in 1..array_length(ids, 1) loop
    a := ids[i]; if a = any(used) then continue; end if;
    b := null;
    for j in i + 1..array_length(ids, 1) loop   -- 가장 가까운, 아직 안 붙은 상대
      continue when ids[j] = any(used);
      if not exists (select 1 from war_matches m where m.season = p_season and ((m.guild_a = a and m.guild_b = ids[j]) or (m.guild_a = ids[j] and m.guild_b = a))) then b := ids[j]; exit; end if;
    end loop;
    if b is null then select x into b from unnest(ids[i + 1:]) x where not x = any(used) limit 1; end if;   -- 다 붙었으면 가장 가까운 조직
    used := used || a || coalesce(b, a);
    insert into war_matches (season, day, guild_a, guild_b) values (p_season, p_day, a, b) returning id into mid;
    select scale into sa from war_entries where season = p_season and guild_id = a;
    select scale into sb from war_entries where season = p_season and guild_id = b;
    perform _war_build_side(mid, 0, p_season, a, sa);
    perform _war_build_side(mid, 1, p_season, b, coalesce(sb, sa));   -- NPC 조직 = 상대 배율
  end loop;
end $$;
create or replace function public._war_settle(p_mid bigint) returns void language plpgsql security definer set search_path = public as $$
declare m war_matches; N jsonb := _war_numbers(); win bigint; dr boolean := false; side int;
begin
  select * into m from war_matches where id = p_mid for update;
  if m.settled then return; end if;
  if m.winner is null then
    if m.score_a > m.score_b then win := m.guild_a; elsif m.score_b > m.score_a then win := coalesce(m.guild_b, -1); else dr := true; end if;
  else win := m.winner; end if;
  update war_matches set winner = win, draw = dr, settled = true, ended_at = coalesce(ended_at, _war_now()) where id = p_mid;
  for side in 0..1 loop
    continue when (case side when 0 then m.guild_a else m.guild_b end) is null;
    update war_entries e set
      points = points + case when dr then (N->'standings'->>'draw')::int when win = e.guild_id then (N->'standings'->>'win')::int + case when m.boss_kill then (N->'standings'->>'boss_bonus')::int else 0 end else (N->'standings'->>'loss')::int end,
      wins = wins + (not dr and win = e.guild_id)::int, draws = draws + dr::int, losses = losses + (not dr and win is distinct from e.guild_id)::int,
      boss_kills = boss_kills + (m.boss_kill and win = e.guild_id)::int, score_total = score_total + case side when 0 then m.score_a else m.score_b end
      where season = m.season and guild_id = case side when 0 then m.guild_a else m.guild_b end;
  end loop;
  if win > 0 then perform _guild_exp(win, null, (N->>'match_exp_win')::int, 'war_win', 'war:' || p_mid); end if;
end $$;
create or replace function public._war_tick() returns date language plpgsql security definer set search_path = public as $$
declare s date := _war_season(); d int; m record;
begin
  if _war_now() < _war_at(s, 1, (_war_numbers()->>'open_hour')::int) then return s; end if;
  perform pg_advisory_xact_lock(hashtext('war:' || s));
  perform _war_lock(s);
  for d in 1..5 loop
    exit when _war_now() < _war_at(s, d, (_war_numbers()->>'open_hour')::int);
    perform _war_pair(s, d);
    if _war_now() >= _war_at(s, d, (_war_numbers()->>'close_hour')::int) then
      for m in select id from war_matches where season = s and day = d and not settled loop perform _war_settle(m.id); end loop;
    end if;
  end loop;
  return s;
end $$;
revoke all on function public._war_npc_deck(text, numeric), public._war_scale(date, bigint), public._war_lock(date), public._war_build_side(bigint, int, date, bigint, numeric),
  public._war_pair(date, int), public._war_settle(bigint), public._war_tick() from public, anon, authenticated;

-- 6) 공개 RPC
-- 덱 설정: p_kind = def1 | def2 | atk1 | atk2, p_uids = 카드 uid 1~5장 ([] = 비움). 방어 덱은 시즌 잠금 뒤 못 바꿈(다음 시즌부터 적용)
create or replace function public.war_set_deck(p_kind text, p_uids jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); sn jsonb := null; other jsonb; s date;
begin
  if uid is null then raise exception 'login required'; end if;
  if p_kind not in ('def1', 'def2', 'atk1', 'atk2') then raise exception 'bad deck'; end if;
  s := _war_tick();
  if p_kind like 'def%' and _war_phase(s) not in ('soon', 'signup', 'ended') and exists (select 1 from war_roster where season = s and user_id = uid) then raise exception 'defense locked'; end if;
  if jsonb_array_length(coalesce(p_uids, '[]'::jsonb)) > 0 then sn := _pvp_snap(uid, p_uids, 'open')->'cards'; end if;
  insert into war_decks (user_id) values (uid) on conflict do nothing;
  select case p_kind when 'def1' then def2 when 'def2' then def1 when 'atk1' then atk2 else atk1 end into other from war_decks where user_id = uid;
  if sn is not null and other is not null and exists (select 1 from jsonb_array_elements(sn) a, jsonb_array_elements(other) b where a->>'id' = b->>'id') then raise exception 'same card in both decks'; end if;
  execute format('update war_decks set %I = $1, updated_at = now() where user_id = $2', p_kind) using sn, uid;
  return jsonb_build_object('ok', true, 'decks', (select to_jsonb(d) - 'user_id' from war_decks d where user_id = uid));
end $$;
-- 참가 (보스·간부, 신청 기간)
create or replace function public.war_enter() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; s date := _war_tick();
begin
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  if m.role not in ('boss', 'officer') then raise exception 'not allowed'; end if;
  if _war_phase(s) <> 'signup' then raise exception 'signup closed'; end if;
  if (select count(*) from guild_members where guild_id = m.guild_id) < (_war_numbers()->>'min_members')::int then raise exception 'need members'; end if;
  insert into war_entries (season, guild_id) values (s, m.guild_id) on conflict do nothing;
  return war_status();
end $$;
create or replace function public.war_withdraw() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; s date := _war_tick();
begin
  m := _guild_me(uid);
  if m.user_id is null or m.role <> 'boss' then raise exception 'not allowed'; end if;
  if _war_phase(s) <> 'signup' then raise exception 'signup closed'; end if;
  delete from war_entries where season = s and guild_id = m.guild_id;
  return war_status();
end $$;
-- 배치 (보스만, 신청 기간): p_user = null 이면 그 칸 비움. 같은 사람을 다른 칸에 두면 옮겨짐
create or replace function public.war_set_slot(p_slot int, p_user uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; s date := _war_tick();
begin
  m := _guild_me(uid);
  if m.user_id is null or m.role <> 'boss' then raise exception 'not allowed'; end if;
  if _war_phase(s) <> 'signup' then raise exception 'signup closed'; end if;
  if not exists (select 1 from war_entries where season = s and guild_id = m.guild_id) then raise exception 'not entered'; end if;
  if p_slot not between 1 and 21 then raise exception 'bad slot'; end if;
  if p_user is not null and not exists (select 1 from guild_members where user_id = p_user and guild_id = m.guild_id) then raise exception 'not member'; end if;
  if p_user is not null then delete from war_roster where season = s and guild_id = m.guild_id and user_id = p_user; end if;
  insert into war_roster (season, guild_id, slot, user_id) values (s, m.guild_id, p_slot, p_user) on conflict (season, guild_id, slot) do update set user_id = excluded.user_id;
  return war_status();
end $$;
-- 아지트 목록 (한 쪽)
create or replace function public._war_side_json(p_mid bigint, p_side int) returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('slot', a.slot, 'role', a.role, 'npc', a.npc, 'user_id', a.user_id,
      'name', case when a.npc and a.user_id is null then '동네 불량배' else coalesce(p.nickname, '조직원') end, 'deck', a.deck, 'decks', jsonb_array_length(a.snaps) - (case when jsonb_array_length(coalesce(a.snaps->1, '[]'::jsonb)) = 0 then 1 else 0 end),
      'cards', (select coalesce(jsonb_agg(jsonb_build_object('id', c->>'id', 'level', c->'level', 'scale', c->'scale', 'hp', a.state->(c->>'uid'))), '[]'::jsonb) from jsonb_array_elements(a.snaps->(a.deck - 1)) c),
      'destroyed', a.destroyed_at is not null, 'locked', a.locked_until > _war_now()) order by a.slot), '[]'::jsonb)
  from war_ajits a left join profiles p on p.id = a.user_id where a.match_id = p_mid and a.side = p_side $$;
-- 상태
create or replace function public.war_status() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; s date; e war_entries; mt war_matches; my int; d int; res jsonb; me_slot int; used int := 0;
begin
  if uid is null then raise exception 'login required'; end if;
  s := _war_tick(); d := _war_day(s); m := _guild_me(uid);
  res := jsonb_build_object('ok', true, 'season', s, 'season_end', s + 4, 'phase', _war_phase(s), 'day', d,
    'opens_at', _war_at(s, coalesce(d, 1) + case when d is not null and _war_now() >= _war_at(s, d, (_war_numbers()->>'close_hour')::int) then 1 else 0 end, (_war_numbers()->>'open_hour')::int),
    'closes_at', case when d is not null then _war_at(s, d, (_war_numbers()->>'close_hour')::int) end,
    'numbers', _war_numbers() - 'npc_scale' - 'layout',
    'decks', (select to_jsonb(x) - 'user_id' from war_decks x where user_id = uid),
    'standings', (select coalesce(jsonb_agg(jsonb_build_object('rank', rk, 'guild_id', guild_id, 'name', name, 'emblem', emblem, 'points', points, 'wins', wins, 'draws', draws, 'losses', losses, 'boss_kills', boss_kills, 'score', score_total, 'me', guild_id = m.guild_id) order by rk), '[]'::jsonb)
                  from (select e2.*, g.name, g.emblem, row_number() over (order by e2.points desc, e2.boss_kills desc, e2.score_total desc, e2.guild_id) rk from war_entries e2 join guilds g on g.id = e2.guild_id where e2.season = s and e2.status = 'in') t where rk <= 30 or guild_id = m.guild_id),
    'claimable', war_claimable());
  if m.user_id is null then return res || jsonb_build_object('guild', null); end if;
  select * into e from war_entries where season = s and guild_id = m.guild_id;
  res := res || jsonb_build_object('guild', jsonb_build_object('id', m.guild_id, 'role', m.role, 'members', (select count(*) from guild_members where guild_id = m.guild_id)),
    'entry', to_jsonb(e) - 'season',
    'roster', (select coalesce(jsonb_agg(jsonb_build_object('slot', x, 'role', _war_role(x), 'user_id', r.user_id, 'name', p.nickname,
                 'ready', (select dd.def1 is not null from war_decks dd where dd.user_id = r.user_id)) order by x), '[]'::jsonb)
               from generate_series(1, 21) x left join war_roster r on r.season = s and r.guild_id = m.guild_id and r.slot = x left join profiles p on p.id = r.user_id),
    'members', (select coalesce(jsonb_agg(jsonb_build_object('user_id', gm.user_id, 'name', coalesce(p.nickname, '조직원'), 'role', gm.role,
                  'ready', (select dd.def1 is not null from war_decks dd where dd.user_id = gm.user_id))), '[]'::jsonb) from guild_members gm left join profiles p on p.id = gm.user_id where gm.guild_id = m.guild_id));
  if d is null then return res; end if;
  select * into mt from war_matches where season = s and day = d and (guild_a = m.guild_id or guild_b = m.guild_id);
  if mt.id is null then return res; end if;
  my := case when mt.guild_a = m.guild_id then 0 else 1 end;
  select slot into me_slot from war_ajits where match_id = mt.id and side = my and user_id = uid;
  select count(*) into used from war_attacks where match_id = mt.id and user_id = uid;
  return res || jsonb_build_object('match', jsonb_build_object('id', mt.id, 'day', mt.day, 'side', my,
    'opponent', case when (case my when 0 then mt.guild_b else mt.guild_a end) is null then jsonb_build_object('name', '동네 불량배파', 'npc', true, 'emblem', 0)
                else (select jsonb_build_object('id', g.id, 'name', g.name, 'emblem', g.emblem, 'level', g.level, 'npc', false) from guilds g where g.id = case my when 0 then mt.guild_b else mt.guild_a end) end,
    'score_me', case my when 0 then mt.score_a else mt.score_b end, 'score_opp', case my when 0 then mt.score_b else mt.score_a end,
    'ended', mt.ended_at is not null or mt.settled, 'winner_me', mt.winner = m.guild_id, 'draw', mt.draw, 'boss_kill', mt.boss_kill,
    'gate_open', not exists (select 1 from war_ajits where match_id = mt.id and side = 1 - my and role = 'def' and destroyed_at is null),
    'me', jsonb_build_object('slot', me_slot, 'alive', me_slot is not null and exists (select 1 from war_ajits where match_id = mt.id and side = my and slot = me_slot and destroyed_at is null),
      'attacks_left', greatest(0, (_war_numbers()->>'attacks_per_day')::int - used),
      'atk', (select coalesce(jsonb_object_agg(deck, jsonb_build_object('alive', (select count(*) from jsonb_array_elements(snap) c where coalesce((state->>(c->>'uid'))::int, 1) > 0))), '{}'::jsonb) from war_atk_state where match_id = mt.id and user_id = uid)),
    'mine', _war_side_json(mt.id, my), 'enemy', _war_side_json(mt.id, 1 - my)));
end $$;
-- 공격 시작
create or replace function public.war_start(p_slot int, p_deck int) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); s date; d int; N jsonb := _war_numbers(); m guild_members; mt war_matches; my int; me war_ajits; t war_ajits; st war_atk_state; snap jsonb;
        atk jsonb; def jsonb; seed bigint; aid bigint; ab jsonb; db jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  s := _war_tick(); d := _war_day(s);
  if _war_phase(s) <> 'live' then raise exception 'not battle time'; end if;
  m := _guild_me(uid);
  select * into mt from war_matches where season = s and day = d and (guild_a = m.guild_id or guild_b = m.guild_id) for update;
  if mt.id is null then raise exception 'no match'; end if;
  if mt.ended_at is not null then raise exception 'match ended'; end if;
  my := case when mt.guild_a = m.guild_id then 0 else 1 end;
  select * into me from war_ajits where match_id = mt.id and side = my and user_id = uid;
  if me.slot is null then raise exception 'not in roster'; end if;
  if me.destroyed_at is not null then raise exception 'ajit destroyed'; end if;
  perform pg_advisory_xact_lock(hashtext('waratk:' || uid));
  update war_attacks set finished_at = now(), win = false where user_id = uid and finished_at is null;   -- 끝내지 않은 판 = 패배(변화 없음)
  update war_ajits set locked_by = null, locked_until = null where locked_by = uid;
  if (select count(*) from war_attacks where match_id = mt.id and user_id = uid) >= (N->>'attacks_per_day')::int then raise exception 'no attacks'; end if;
  select * into t from war_ajits where match_id = mt.id and side = 1 - my and slot = p_slot for update;
  if t.slot is null then raise exception 'bad target'; end if;
  if t.destroyed_at is not null then raise exception 'already destroyed'; end if;
  if t.locked_until > _war_now() then raise exception 'target busy'; end if;
  if t.role <> 'def' and exists (select 1 from war_ajits where match_id = mt.id and side = 1 - my and role = 'def' and destroyed_at is null) then raise exception 'defense first'; end if;
  if p_deck not in (1, 2) then raise exception 'bad deck'; end if;
  select * into st from war_atk_state where match_id = mt.id and user_id = uid and deck = p_deck;
  if st.match_id is null then
    select case p_deck when 1 then atk1 else atk2 end into snap from war_decks where user_id = uid;
    if snap is null or jsonb_array_length(snap) = 0 then raise exception 'no attack deck'; end if;
    insert into war_atk_state (match_id, user_id, deck, snap) values (mt.id, uid, p_deck, snap) returning * into st;
  end if;
  select coalesce(jsonb_agg(c || jsonb_build_object('hp', st.state->(c->>'uid'))), '[]'::jsonb) into atk from jsonb_array_elements(st.snap) c where coalesce((st.state->>(c->>'uid'))::int, 1) > 0;
  if jsonb_array_length(atk) = 0 then raise exception 'deck dead'; end if;
  select coalesce(jsonb_agg(c || jsonb_build_object('hp', t.state->(c->>'uid'))), '[]'::jsonb) into def from jsonb_array_elements(t.snaps->(t.deck - 1)) c where coalesce((t.state->>(c->>'uid'))::int, 1) > 0;
  ab := jsonb_build_object('atk', (N->'roles'->me.role->>'atk')::numeric, 'def', case when me.role in ('mid', 'boss') then (N->'roles'->me.role->>'def')::numeric else 1 end);   -- 공격 측
  db := jsonb_build_object('atk', case when t.role in ('mid', 'boss') then (N->'roles'->t.role->>'atk')::numeric else 1 end, 'def', (N->'roles'->t.role->>'def')::numeric);   -- 방어 측
  seed := floor(random() * 2147483647)::bigint;
  update war_ajits set locked_by = uid, locked_until = _war_now() + make_interval(mins => (N->>'lock_minutes')::int) where match_id = mt.id and side = t.side and slot = t.slot;
  insert into war_attacks (match_id, user_id, side, target_slot, atk_deck, def_deck, seed, atk_snap, def_snap, atk_buff, def_buff, before)
    values (mt.id, uid, my, p_slot, p_deck, t.deck, seed, atk, def, ab, db, jsonb_build_object('atk_state', st.state, 'def_state', t.state, 'def_deck', t.deck))
    returning id into aid;
  return jsonb_build_object('ok', true, 'id', aid, 'seed', seed, 'atk', atk, 'def', def, 'atk_buff', ab, 'def_buff', db, 'target', jsonb_build_object('slot', t.slot, 'role', t.role, 'deck', t.deck, 'npc', t.npc));
end $$;
-- 공격 끝: p_atk_hp / p_def_hp = { 카드 uid: 남은 HP } (살아남은 카드만). 서버는 이전 HP 를 넘지 않게 자름
create or replace function public.war_finish(p_id bigint, p_win boolean, p_atk_hp jsonb, p_def_hp jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); a war_attacks; N jsonb := _war_numbers(); mt war_matches; t war_ajits; cap int := (_war_numbers()->>'hp_cap')::int;
        ast jsonb := '{}'::jsonb; dst jsonb := '{}'::jsonb; c jsonb; hp int; iswin boolean; pts int := 0; flag boolean := false; next_ok boolean;
begin
  select * into a from war_attacks where id = p_id and user_id = uid for update;
  if a.id is null then raise exception 'no battle'; end if;
  if a.finished_at is not null then raise exception 'already finished'; end if;
  if now() - a.started_at < make_interval(secs => (N->>'min_secs')::int) then raise exception 'too fast'; end if;
  select * into mt from war_matches where id = a.match_id for update;
  select * into t from war_ajits where match_id = a.match_id and side = 1 - a.side and slot = a.target_slot for update;
  if now() - a.started_at > make_interval(mins => (N->>'open_minutes')::int) or t.destroyed_at is not null or t.deck <> a.def_deck or mt.settled then
    update war_attacks set finished_at = now(), win = false where id = a.id;
    update war_ajits set locked_by = null, locked_until = null where match_id = t.match_id and side = t.side and slot = t.slot and locked_by = uid;
    return war_status() || jsonb_build_object('result', jsonb_build_object('win', false, 'expired', true));
  end if;
  -- 남은 HP (이전보다 클 수 없음, 없으면 쓰러짐)
  for c in select * from jsonb_array_elements(a.atk_snap) loop
    hp := greatest(0, least(coalesce((p_atk_hp->>(c->>'uid'))::int, 0), coalesce((c->>'hp')::int, cap)));
    if coalesce((p_atk_hp->>(c->>'uid'))::int, 0) > coalesce((c->>'hp')::int, cap) then flag := true; end if;
    ast := ast || jsonb_build_object(c->>'uid', hp);
  end loop;
  for c in select * from jsonb_array_elements(a.def_snap) loop
    hp := case when p_win then 0 else greatest(0, least(coalesce((p_def_hp->>(c->>'uid'))::int, 0), coalesce((c->>'hp')::int, cap))) end;
    dst := dst || jsonb_build_object(c->>'uid', hp);
  end loop;
  iswin := p_win or not exists (select 1 from jsonb_each_text(dst) x where x.value::int > 0);
  if not exists (select 1 from jsonb_each_text(ast) x where x.value::int > 0) and iswin then flag := true; end if;   -- 둘 다 전멸 = 의심
  update war_atk_state set state = coalesce(state, '{}'::jsonb) || ast where match_id = a.match_id and user_id = uid and deck = a.atk_deck;
  if iswin then
    next_ok := t.deck = 1 and jsonb_array_length(coalesce(t.snaps->1, '[]'::jsonb)) > 0;
    if next_ok then
      update war_ajits set deck = 2, state = null where match_id = t.match_id and side = t.side and slot = t.slot;   -- 2번 덱 등장
    else
      pts := (N->'points'->>t.role)::int;
      update war_ajits set destroyed_at = now(), destroyed_by = uid, state = dst where match_id = t.match_id and side = t.side and slot = t.slot;
      update war_matches set score_a = score_a + case a.side when 0 then pts else 0 end, score_b = score_b + case a.side when 1 then pts else 0 end where id = mt.id;
      if t.role = 'boss' then
        update war_matches set boss_kill = true, winner = coalesce(case a.side when 0 then mt.guild_a else mt.guild_b end, -1), ended_at = now() where id = mt.id;
      end if;
    end if;
  else
    update war_ajits set state = coalesce(state, '{}'::jsonb) || dst where match_id = t.match_id and side = t.side and slot = t.slot;
  end if;
  update war_ajits set locked_by = null, locked_until = null where match_id = t.match_id and side = t.side and slot = t.slot;
  update war_attacks set finished_at = now(), win = iswin, points = pts, flagged = flag, reported = jsonb_build_object('win', p_win, 'atk', p_atk_hp, 'def', p_def_hp) where id = a.id;
  return war_status() || jsonb_build_object('result', jsonb_build_object('win', iswin, 'points', pts, 'next_deck', iswin and next_ok, 'destroyed', iswin and not next_ok, 'boss_kill', t.role = 'boss' and iswin and not next_ok));
end $$;
create or replace function public._war_sum(a jsonb, b jsonb) returns jsonb language sql immutable as $$
  select coalesce(jsonb_object_agg(k, coalesce((a->>k)::int, 0) + coalesce((b->>k)::int, 0)), '{}'::jsonb) from (select jsonb_object_keys(a) k union select jsonb_object_keys(b)) x $$;
-- 받을 보상 (경기 승리 · 시즌 순위) 수
create or replace function public._war_pending(p_uid uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare out jsonb := '[]'::jsonb; r record; N jsonb := _war_numbers(); rk int;
begin
  for r in select mt.*, wr.guild_id gid from war_roster wr join war_matches mt on mt.season = wr.season and (mt.guild_a = wr.guild_id or mt.guild_b = wr.guild_id)
            where wr.user_id = p_uid and mt.settled and wr.season >= _war_season() - 62 loop
    continue when exists (select 1 from guild_claims where user_id = p_uid and ref = 'warm:' || r.id);
    out := out || jsonb_build_object('ref', 'warm:' || r.id, 'gid', r.gid, 'reward', case when r.draw then N->'match_draw' when r.winner is distinct from r.gid then N->'match_loss' else (N->'match_win') ||
      case when r.boss_kill then _war_sum(N->'match_win', N->'match_boss_kill') else '{}'::jsonb end end);
  end loop;
  for r in select wr.season, wr.guild_id from war_roster wr join war_entries e on e.season = wr.season and e.guild_id = wr.guild_id and e.status = 'in'
            where wr.user_id = p_uid and wr.season >= _war_season() - 62 and _war_now() >= _war_at(wr.season, 5, (N->>'close_hour')::int) loop
    continue when exists (select 1 from guild_claims where user_id = p_uid and ref = 'wars:' || r.season);
    select x.rk into rk from (select guild_id, row_number() over (order by points desc, boss_kills desc, score_total desc, guild_id) rk from war_entries where season = r.season and status = 'in') x where x.guild_id = r.guild_id;
    out := out || jsonb_build_object('ref', 'wars:' || r.season, 'gid', r.guild_id, 'rank', rk, 'reward', _war_sum(N->'season_member',
      coalesce((select q->'reward' from jsonb_array_elements(N->'season_rank') q where rk between (q->>'from')::int and (q->>'to')::int), '{}'::jsonb)));
  end loop;
  return out;
end $$;
create or replace function public.war_claimable() returns int language sql stable security definer set search_path = public as $$ select jsonb_array_length(_war_pending(auth.uid())) $$;
create or replace function public.war_claim() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); p jsonb; x jsonb; got jsonb := '{}'::jsonb; k text;
begin
  if uid is null then raise exception 'login required'; end if;
  perform _war_tick();
  p := _war_pending(uid);
  if jsonb_array_length(p) = 0 then raise exception 'nothing to claim'; end if;
  for x in select * from jsonb_array_elements(p) loop
    perform _guild_reward(uid, (x->>'gid')::bigint, x->'reward', 'war_reward', x->>'ref');
    for k in select jsonb_object_keys(x->'reward') loop got := jsonb_set(got, array[k], to_jsonb(coalesce((got->>k)::int, 0) + (x->'reward'->>k)::int)); end loop;
    if x ? 'rank' then got := got || jsonb_build_object('rank', x->'rank'); end if;
  end loop;
  return war_status() || jsonb_build_object('got', got);
end $$;
revoke all on function public._war_side_json(bigint, int), public._war_pending(uuid) from public, anon, authenticated;
revoke all on function public.war_set_deck(text, jsonb), public.war_enter(), public.war_withdraw(), public.war_set_slot(int, uuid), public.war_status(), public.war_start(int, int),
  public.war_finish(bigint, boolean, jsonb, jsonb), public.war_claimable(), public.war_claim() from public, anon;
grant execute on function public.war_set_deck(text, jsonb), public.war_enter(), public.war_withdraw(), public.war_set_slot(int, uuid), public.war_status(), public.war_start(int, int),
  public.war_finish(bigint, boolean, jsonb, jsonb), public.war_claimable(), public.war_claim() to authenticated;

-- 7) 관리자: 시즌 현황 · 의심 기록 · 공격 무효(정산 전만: 그 공격 전 상태로 되돌리고 점수 회수)
create or replace function public.admin_war(p_season date) returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
begin
  perform public._admin_guard();
  return jsonb_build_object('entries', (select coalesce(jsonb_agg(to_jsonb(e) order by e.points desc), '[]'::jsonb) from war_entries e where season = coalesce(p_season, _war_season())),
    'matches', (select coalesce(jsonb_agg(to_jsonb(m) order by m.day, m.id), '[]'::jsonb) from war_matches m where season = coalesce(p_season, _war_season())),
    'flagged', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'match_id', a.match_id, 'user_id', a.user_id, 'target', a.target_slot, 'win', a.win, 'points', a.points, 'at', a.finished_at) order by a.id desc), '[]'::jsonb)
                from war_attacks a join war_matches m on m.id = a.match_id where m.season = coalesce(p_season, _war_season()) and a.flagged and not a.voided));
end $$;
create or replace function public.admin_war_void(p_id bigint, p_reason text) returns jsonb language plpgsql volatile security definer set search_path = public, auth as $$
declare a war_attacks; mt war_matches;
begin
  perform public._admin_guard();
  if coalesce(btrim(p_reason), '') = '' then raise exception 'reason required'; end if;
  select * into a from war_attacks where id = p_id for update;
  if a.id is null or a.voided or a.finished_at is null then raise exception 'no attack'; end if;
  select * into mt from war_matches where id = a.match_id for update;
  if mt.settled then raise exception 'match settled'; end if;
  update war_attacks set voided = true where id = p_id;
  update war_ajits set state = a.before->'def_state', deck = (a.before->>'def_deck')::int, destroyed_at = null, destroyed_by = null where match_id = a.match_id and side = 1 - a.side and slot = a.target_slot;
  update war_atk_state set state = a.before->'atk_state' where match_id = a.match_id and user_id = a.user_id and deck = a.atk_deck;
  if a.points > 0 then
    update war_matches set score_a = score_a - case a.side when 0 then a.points else 0 end, score_b = score_b - case a.side when 1 then a.points else 0 end where id = a.match_id;
  end if;
  if mt.boss_kill and exists (select 1 from war_ajits where match_id = a.match_id and side = 1 - a.side and slot = a.target_slot and role = 'boss') then update war_matches set boss_kill = false, winner = null, ended_at = null where id = a.match_id; end if;
  insert into public.admin_log (admin_id, admin_email, action, target_user, amount, reason) values (auth.uid(), auth.jwt()->>'email', 'war_void', a.user_id, a.points, left(btrim(p_reason), 200));
  return jsonb_build_object('ok', true, 'voided', p_id);
end $$;
revoke all on function public.admin_war(date), public.admin_war_void(bigint, text) from public, anon;
grant execute on function public.admin_war(date), public.admin_war_void(bigint, text) to authenticated;


-- ===== SOURCE: manual_battle.sql =====
-- 수동 전투 (균열 토벌 · PvP): 내 행동 기록 저장 → tools/raid_verify.mjs · tools/pvp_verify.mjs 가 같은 seed 로 다시 돌려 검증
-- guild3.sql · guild.sql(pvp_report) 뒤에 실행. 여러 번 실행해도 안전
alter table public.guild_raid_attempts add column if not exists actions jsonb;   -- null = 자동 전투
alter table public.pvp_attempts add column if not exists actions jsonb;          -- null = 자동 · 판마다 배열 [[..],[..]]

-- 수동은 시간이 더 걸려서 토벌 제한 시간 10분 → 20분 (나머지 숫자는 guild3.sql 그대로)
create or replace function public._raid_numbers() returns jsonb language sql immutable as $$ select '{
  "attempts_per_day": 3, "sweep_pct": 90, "min_secs": 3, "open_minutes": 20,
  "hp_per_member": {"normal": 500000, "hard": 1250000, "abyss": 3000000}, "hp_min_members": 5, "hp_growth": 1.35,
  "diff_level": {"normal": 1, "hard": 3, "abyss": 5}, "diff_mult": {"normal": 1, "hard": 1.6, "abyss": 2.5},
  "hit_cap": 6000, "hit_cap_growth": 1.1, "attempt_hits": 200,
  "attempt": {"loyalty": 5, "gold_base": 200, "gold_per_damage": 200, "gold_max": 2000, "exp": 5},
  "stage": {"loyalty": 20, "gold": 2000, "gem": 30, "gem_every3": 150, "tickets_every5": 1, "exp_per_stage": 30},
  "last_hit": {"loyalty": 10},
  "rank": [{"from": 1, "to": 1, "reward": {"gem": 1000, "loyalty": 100}}, {"from": 2, "to": 3, "reward": {"gem": 500, "loyalty": 70}}, {"from": 4, "to": 10, "reward": {"gem": 200, "loyalty": 40}}],
  "member": {"gem": 100, "loyalty": 20},
  "join_hours": 24
}'::jsonb $$;

-- 행동 기록 검사: 배열 · 크기 제한 (한 판 최대 행동 수 = 턴 × 5장 + 턴 종료)
create or replace function public._battle_acts_ok(p jsonb, p_max int) returns boolean language sql immutable as $$
  select p is not null and jsonb_typeof(p) = 'array' and jsonb_array_length(p) <= p_max and octet_length(p::text) <= 65536 $$;

-- 토벌: raid_finish 전에 호출 (끝나기 전 · 본인 판만 · 한 번만)
create or replace function public.raid_log(p_id bigint, p_actions jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); a guild_raid_attempts;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into a from guild_raid_attempts where id = p_id and user_id = uid for update;
  if a.id is null then raise exception 'no battle'; end if;
  if a.kind <> 'fight' or a.finished_at is not null then raise exception 'already finished'; end if;
  if a.actions is not null then raise exception 'already logged'; end if;
  if not _battle_acts_ok(p_actions, 15 * 6 + 5) then raise exception 'bad actions'; end if;
  update guild_raid_attempts set actions = p_actions where id = a.id;
  return jsonb_build_object('ok', true);
end $$;

-- PvP: pvp_report 전에 호출 (보고 전 · 본인 판만 · 한 번만). 판마다 배열
create or replace function public.pvp_log(p_id bigint, p_actions jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); a pvp_attempts; x jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into a from pvp_attempts where id = p_id and user_id = uid for update;
  if a.id is null then raise exception 'not found'; end if;
  if a.reported_at is not null then raise exception 'already reported'; end if;
  if a.actions is not null then raise exception 'already logged'; end if;
  if p_actions is null or jsonb_typeof(p_actions) <> 'array' or jsonb_array_length(p_actions) > 3 or octet_length(p_actions::text) > 131072 then raise exception 'bad actions'; end if;
  for x in select value from jsonb_array_elements(p_actions) loop
    if not _battle_acts_ok(x, 20 * 6 + 5) then raise exception 'bad actions'; end if;
  end loop;
  update pvp_attempts set actions = p_actions where id = a.id;
  return jsonb_build_object('ok', true);
end $$;

revoke all on function public._battle_acts_ok(jsonb, int) from public, anon, authenticated;
revoke all on function public.raid_log(bigint, jsonb) from public, anon;
grant execute on function public.raid_log(bigint, jsonb) to authenticated;
revoke all on function public.pvp_log(bigint, jsonb) from public, anon;
grant execute on function public.pvp_log(bigint, jsonb) to authenticated;


-- ===== SOURCE: war_manual.sql =====
-- 구역 전쟁 수동 전투: 내 행동 기록 저장 → tools/war_verify.mjs 가 같은 seed 로 다시 돌려 검증
-- guild4.sql · manual_battle.sql 뒤에 실행. 여러 번 실행해도 안전
alter table public.war_attacks add column if not exists actions jsonb;   -- null = 자동 전투

-- 수동은 시간이 더 걸려서 공격 제한 시간 10분 → 20분 (나머지 숫자는 guild4.sql 그대로)
create or replace function public._war_numbers() returns jsonb language sql immutable as $$ select '{
  "min_members": 10, "attacks_per_day": 5, "open_hour": 9, "close_hour": 23, "min_secs": 3, "open_minutes": 20, "lock_minutes": 3, "hp_cap": 60000,
  "layout": {"def": [1,2,3,4,5], "atk": [6,7,8,9,10], "mid": [11,12,13], "boss": [14], "etc": [15,16,17,18,19,20,21]},
  "roles": {"def": {"atk": 1, "def": 1.2}, "atk": {"atk": 1.2, "def": 1}, "mid": {"atk": 1.15, "def": 1.15}, "boss": {"atk": 1.25, "def": 1.25}, "etc": {"atk": 1, "def": 1}},
  "points": {"def": 200, "atk": 150, "etc": 150, "mid": 250, "boss": 400},
  "standings": {"win": 3, "draw": 2, "loss": 0, "boss_bonus": 1},
  "npc_level": 10, "npc_scale": 1, "signup_days_before": 3,
  "match_win": {"loyalty": 60, "gold": 5000}, "match_boss_kill": {"loyalty": 20, "gold": 2000}, "match_draw": {"loyalty": 20, "gold": 1500}, "match_loss": {"loyalty": 10}, "match_exp_win": 300,
  "season_rank": [{"from": 1, "to": 1, "reward": {"gem": 1000, "loyalty": 300}}, {"from": 2, "to": 2, "reward": {"gem": 700, "loyalty": 200}}, {"from": 3, "to": 3, "reward": {"gem": 500, "loyalty": 150}},
                  {"from": 4, "to": 10, "reward": {"gem": 300, "loyalty": 100}}, {"from": 11, "to": 30, "reward": {"gem": 150, "loyalty": 50}}],
  "season_member": {"gem": 100, "loyalty": 30}
}'::jsonb $$;

-- war_finish 전에 호출 (끝나기 전 · 본인 공격만 · 한 번만). 40턴 → 내 턴 20 × (5장 + 턴 종료)
create or replace function public.war_log(p_id bigint, p_actions jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); a war_attacks;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into a from war_attacks where id = p_id and user_id = uid for update;
  if a.id is null then raise exception 'no battle'; end if;
  if a.finished_at is not null then raise exception 'already finished'; end if;
  if a.actions is not null then raise exception 'already logged'; end if;
  if not _battle_acts_ok(p_actions, 20 * 6 + 5) then raise exception 'bad actions'; end if;
  update war_attacks set actions = p_actions where id = a.id;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.war_log(bigint, jsonb) from public, anon;
grant execute on function public.war_log(bigint, jsonb) to authenticated;


-- ===== SOURCE: guild4_ui.sql =====
-- 조직 4단계 보완: 구역 전쟁 「참가 신청(개인)」 · 아지트 칸에 리더 얼굴. 여러 번 실행해도 안전.
-- 선행: guild4.sql
-- · 조직원은 신청 기간(셋째 주 일~화)에 개인 참가 신청 (war_signup). 보스는 신청 안 한 조직원도 배치 가능 (war_set_slot 그대로)
-- · 시즌 잠금 때 빈 칸 자동 배치는 신청한 사람부터 (그다음 나머지 조직원)
-- · war_ui(): 내 조직 신청자 목록 + 내 조직·오늘 상대의 리더 인재 id (화면 표시용)

create table if not exists public.war_signups (
  season date not null, user_id uuid not null references auth.users(id) on delete cascade, guild_id bigint not null,
  created_at timestamptz not null default now(), primary key (season, user_id));
create index if not exists war_signups_g on public.war_signups (season, guild_id);
alter table public.war_signups enable row level security;
revoke all on public.war_signups from public, anon, authenticated;

-- 리더 인재 id (스토리 저장에서)
create or replace function public._war_leader_card(p_uid uuid) returns text language sql stable security definer set search_path = public as $$
  select o->>'id' from story_progress sp, jsonb_array_elements(coalesce(sp.data->'owned', '[]'::jsonb)) o where sp.user_id = p_uid and o->>'uid' = sp.data->>'leader' limit 1 $$;

-- 개인 참가 신청 / 취소
create or replace function public.war_signup(p_on boolean) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; s date := _war_tick();
begin
  if uid is null then raise exception 'login required'; end if;
  m := _guild_me(uid);
  if m.user_id is null then raise exception 'not in guild'; end if;
  if _war_phase(s) <> 'signup' then raise exception 'signup closed'; end if;
  if p_on then insert into war_signups (season, user_id, guild_id) values (s, uid, m.guild_id) on conflict (season, user_id) do update set guild_id = excluded.guild_id;
  else delete from war_signups where season = s and user_id = uid; end if;
  return war_ui();
end $$;

-- 화면 보조: 신청자 · 리더 얼굴
create or replace function public.war_ui() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m guild_members; s date; d int; mid bigint;
begin
  if uid is null then raise exception 'login required'; end if;
  s := _war_season(); d := _war_day(s); m := _guild_me(uid);
  if m.user_id is null then return jsonb_build_object('ok', true, 'signed', '[]'::jsonb, 'me_signed', false, 'cards', '{}'::jsonb); end if;
  select id into mid from war_matches where season = s and day = d and (guild_a = m.guild_id or guild_b = m.guild_id);
  return jsonb_build_object('ok', true,
    'signed', (select coalesce(jsonb_agg(user_id), '[]'::jsonb) from war_signups where season = s and guild_id = m.guild_id),
    'me_signed', exists (select 1 from war_signups where season = s and user_id = uid),
    'cards', (select coalesce(jsonb_object_agg(u, _war_leader_card(u)) filter (where _war_leader_card(u) is not null), '{}'::jsonb) from (
       select gm.user_id u from guild_members gm where gm.guild_id = m.guild_id
       union select a.user_id from war_ajits a where a.match_id = mid and a.user_id is not null) x));
end $$;

-- 시즌 잠금: 빈 칸 자동 배치는 신청자 먼저
create or replace function public._war_lock(p_season date) returns void language plpgsql security definer set search_path = public as $$
declare e record; u record; s int; n int; sc numeric;
begin
  for e in select * from war_entries where season = p_season and not locked loop
    -- 배치 안 된 조직원 → 빈 칸
    for u in select gm.user_id from guild_members gm where gm.guild_id = e.guild_id
               and not exists (select 1 from war_roster r where r.season = p_season and r.user_id = gm.user_id) order by (exists (select 1 from war_signups ws where ws.season = p_season and ws.user_id = gm.user_id)) desc, gm.joined_at loop
      select min(x) into s from generate_series(1, 21) x where not exists (select 1 from war_roster r where r.season = p_season and r.guild_id = e.guild_id and r.slot = x and r.user_id is not null);
      exit when s is null;
      insert into war_roster (season, guild_id, slot, user_id) values (p_season, e.guild_id, s, u.user_id) on conflict (season, guild_id, slot) do update set user_id = excluded.user_id;
    end loop;
    -- 떠난 사람 정리 · 방어 덱 잠금
    update war_roster r set user_id = null where r.season = p_season and r.guild_id = e.guild_id and r.user_id is not null
      and not exists (select 1 from guild_members gm where gm.user_id = r.user_id and gm.guild_id = e.guild_id);
    update war_roster r set def_snap = (select case when d.def1 is null then null else jsonb_build_array(d.def1, coalesce(d.def2, '[]'::jsonb)) end from war_decks d where d.user_id = r.user_id)
      where r.season = p_season and r.guild_id = e.guild_id and r.user_id is not null;
    select count(*) into n from war_roster where season = p_season and guild_id = e.guild_id and user_id is not null;
    sc := _war_scale(p_season, e.guild_id);
    update war_entries set locked = true, scale = sc, status = case when n >= (_war_numbers()->>'min_members')::int then 'in' else 'out' end where season = p_season and guild_id = e.guild_id;
  end loop;
end $$;


revoke all on function public._war_leader_card(uuid), public._war_lock(date) from public, anon, authenticated;
revoke all on function public.war_signup(boolean), public.war_ui() from public, anon;
grant execute on function public.war_signup(boolean), public.war_ui() to authenticated;


-- ===== SOURCE: pvp_info_notices.sql =====
-- PR 3/3: PvP 랭커 정보 팝업 + 공지 게시판. 여러 번 실행해도 안전. RLS 켬.
-- 필요: pvp.sql, phaseE_2.sql(player_state), guild.sql, admin.sql(_admin_guard)

-- 1) PvP 랭커 정보 — 로그인 유저만. 순위로 조회(유저 id 노출 없음). 공개 필드만 반환:
--    닉네임 · 계정 레벨 · 리더 카드 id · 해당 리그/모드 PvP 덱(카드 id·레벨) · 소속 조직(이름·엠블럼)
create or replace function public.pvp_user_info(p_league text, p_mode text, p_rank int) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); s date := _pvp_season(); t uuid; g record; deck jsonb; lead text;
begin
  if uid is null then raise exception 'login required' using errcode = '42501'; end if;
  perform _pvp_ok(p_league, p_mode);
  if p_rank is null or p_rank < 1 or p_rank > 100 then raise exception 'bad rank'; end if;
  select x.user_id into t from (select r.user_id, row_number() over (order by r.rating desc, r.wins desc, r.user_id) rn
      from pvp_ratings r where r.league = p_league and r.mode = p_mode and r.season = s and r.wins + r.losses > 0) x where x.rn = p_rank;
  if t is null then raise exception 'not found'; end if;
  select o->>'id' into lead from story_progress sp, jsonb_array_elements(case when jsonb_typeof(sp.data->'owned') = 'array' then sp.data->'owned' else '[]'::jsonb end) o
    where sp.user_id = t and o->>'uid' = sp.data->>'leader' limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('slot', d.slot, 'cards',
      (select coalesce(jsonb_agg(jsonb_build_object('id', c->>'id', 'level', coalesce((c->>'level')::int, 1))), '[]'::jsonb)
         from jsonb_array_elements(case when jsonb_typeof(d.snap->'cards') = 'array' then d.snap->'cards' when jsonb_typeof(d.snap) = 'array' then d.snap else '[]'::jsonb end) c)) order by d.slot), '[]'::jsonb)
    into deck from pvp_decks d where d.user_id = t and d.league = p_league and d.mode = p_mode;
  select gg.name, gg.emblem into g from guild_members m join guilds gg on gg.id = m.guild_id where m.user_id = t;
  return jsonb_build_object('ok', true, 'rank', p_rank, 'me', t = uid,
    'name', coalesce((select nickname from profiles where id = t), '플레이어'),
    'level', coalesce((select level from player_state where user_id = t), 1),
    'leader', lead, 'decks', deck,
    'guild', case when g.name is null then null else jsonb_build_object('name', g.name, 'emblem', g.emblem) end);
end $$;
revoke all on function public.pvp_user_info(text, text, int) from public, anon;
grant execute on function public.pvp_user_info(text, text, int) to authenticated;

-- 2) 공지 게시판 — 누구나 읽기, 쓰기·수정·삭제는 관리자 RPC 만
create table if not exists public.notices (
  id         bigint generated always as identity primary key,
  body       text not null check (char_length(body) between 1 and 200),
  pinned     boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists notices_order_idx on public.notices (pinned desc, created_at desc);
alter table public.notices enable row level security;
revoke all on public.notices from public, anon, authenticated;
grant select on public.notices to anon, authenticated;
drop policy if exists "notices_read_all" on public.notices;
create policy "notices_read_all" on public.notices for select to anon, authenticated using (true);

-- 저장: p_id null = 새 글, 아니면 수정
create or replace function public.admin_notice_save(p_id bigint, p_body text, p_pinned boolean) returns jsonb
language plpgsql security definer set search_path = public, auth as $$
declare r notices; b text := btrim(coalesce(p_body, ''));
begin
  perform public._admin_guard();
  if char_length(b) not between 1 and 200 then raise exception 'body 1~200'; end if;
  if p_id is null then
    insert into notices (body, pinned) values (b, coalesce(p_pinned, false)) returning * into r;
  else
    update notices set body = b, pinned = coalesce(p_pinned, pinned), updated_at = now() where id = p_id returning * into r;
    if r.id is null then raise exception 'not found'; end if;
  end if;
  return to_jsonb(r);
end $$;
create or replace function public.admin_notice_delete(p_id bigint) returns jsonb
language plpgsql security definer set search_path = public, auth as $$
begin
  perform public._admin_guard();
  delete from notices where id = p_id;
  return jsonb_build_object('ok', found);
end $$;
revoke all on function public.admin_notice_save(bigint, text, boolean), public.admin_notice_delete(bigint) from public, anon;
grant execute on function public.admin_notice_save(bigint, text, boolean), public.admin_notice_delete(bigint) to authenticated;


-- ===== SOURCE: story_ch0.sql =====
-- =====================================================================
-- 챕터 0 (튜토리얼 · 공허한 여신) — Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전
-- 선행: story_*.sql, phaseE_2.sql, story_ch1_reward.sql (reward_card 열 · 고정 보상 지급)
--   페이즈 1~3, 첫 클리어 보상: 1 오유나 · 2 황보예 · 3 송지아 (이미 있으면 한 장 더)
--   새 사용자: 캐릭터(스타터)를 고르기 전에도 챕터 0 을 할 수 있음
--   기존 사용자: 진행 그대로. 챕터 0 은 다른 챕터의 열림 조건에 들어가지 않음 (챕터 1 은 챕터 0 클리어 없이 열림)
--   행동력: 다른 페이즈와 같이 6 (0 이면 소탕으로 공짜 반복 가능) · 챕터 0 전체 클리어 시 소환권 +10 (기존 규칙)
-- =====================================================================
insert into public.story_phase_config (chapter, phase, type, points, reward_grade, enemy_count) values
  (0,1,'normal',3,null,1), (0,2,'normal',3,null,5), (0,3,'normal',3,null,5)
on conflict (chapter, phase) do update set type = excluded.type, points = excluded.points, reward_grade = excluded.reward_grade, enemy_count = excluded.enemy_count;
update public.story_phase_config set reward_card = case phase when 1 then '10256' when 2 then '10462' when 3 then '10207' end where chapter = 0;

-- 원래 전투 시작(_e0, phaseE_2 가 감쌈)을 다시 정의: 챕터 0 은 스타터 불필요 · 챕터 0 은 다른 챕터 선행 조건에서 제외
create or replace function public._story_start_phase_e0(p_chapter int, p_phase int) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); d jsonb;
begin
  if not exists (select 1 from story_phase_config where chapter = p_chapter and phase = p_phase) then raise exception 'invalid phase'; end if;
  d := _story_lock(uid);
  if p_chapter <> 0 and coalesce(d->>'starter', '') = '' then raise exception 'choose starter first'; end if;
  -- 열림 조건: 같은 챕터의 이전 페이즈 모두 클리어 + 이전 챕터 전체 클리어 (챕터 0 은 다른 챕터 조건에서 빠짐)
  if exists (
    select 1 from story_phase_config c
    where (c.chapter < p_chapter or (c.chapter = p_chapter and c.phase < p_phase))
      and (c.chapter <> 0 or p_chapter = 0)
      and not (coalesce(d->'cleared'->(c.chapter::text), '[]'::jsonb) @> to_jsonb(c.phase))
  ) then raise exception 'phase locked'; end if;
  d := jsonb_set(d, '{battle}', jsonb_build_object('chapter', p_chapter, 'phase', p_phase, 'at', (extract(epoch from clock_timestamp()))::bigint));
  return _story_save(uid, d);
end $$;
revoke all on function public._story_start_phase_e0(int, int) from public, anon, authenticated;

select chapter, phase, type, reward_card from public.story_phase_config where chapter = 0 order by phase;


-- ===== SOURCE: story_ch0_pull.sql =====
-- =====================================================================
-- 챕터 0 클리어 후 강제 10회 프리미엄 영입 — 끝 표시(ch0Pull)를 서버 진행에 저장. 여러 번 실행해도 안전
-- 소환권 10장은 기존 규칙(챕터 전체 첫 클리어마다 +10, _story_ticket_sync · 계정당 한 번)이 그대로 지급 → 추가 지급 없음
-- story_mark_seen 허용 키에 'ch0Pull' 추가 (그 외 동작 동일)
-- =====================================================================
create or replace function public.story_mark_seen(p_key text) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); d jsonb;
begin
  if p_key not in ('openingSeen', 'startSeen', 'ch0Pull') then raise exception 'invalid key'; end if;
  d := _story_lock(uid);
  return _story_save(uid, jsonb_set(d, array[p_key], 'true'::jsonb));
end $$;
revoke all on function public.story_mark_seen(text) from public, anon;
grant execute on function public.story_mark_seen(text) to authenticated;


-- ===== SOURCE: gear_v1.sql =====
-- ⚠ 다시 돌리지 마세요, 최신 아님 (일부): 이 파일의 _gear_grant, mail_claim 는 뒤 파일에서 다시 정의됨. 이 파일을 다시 돌리면 예전 것으로 되돌아가요. supabase/README.md 참고
-- ===== 장비 시스템 v1 (PR1: DB 기반만, UI 없음) =====
-- 설계: 장비 시스템 초안 v4 Page. 여러 번 실행해도 안전 (if not exists / on conflict / create or replace)
-- 의존: phaseE_1.sql (player_wallet, wallet_log), gem.sql (_gem_spend), story_progress (owned[].id)
-- 등급 tier: 1 낡은 · 2 일반 · 3 고급 · 4 희귀 · 5 영웅 · 6 전설 · 7 심연 (6·7 = 이벤트 전용, event_only)
-- 쓰기는 전부 security definer RPC. 테이블은 정의=모두 읽기, 보유=본인만 읽기, 직접 쓰기 불가

-- 1) 정의 테이블 -------------------------------------------------------------
create table if not exists public.gear_defs (
  id         text primary key,                       -- 예: weapon_4_2
  slot       text not null check (slot in ('weapon','armor','acc')),
  tier       int  not null check (tier between 1 and 7),
  name       text not null,
  icon       text not null,                          -- img/gear/{slot}_{tier}_{n}.webp
  main_stat  text not null check (main_stat in ('atk','hp','def','crit','evade','mp')),
  main_pct   numeric not null check (main_pct > 0),  -- 무기 ATK +2%..+14% 등
  opt_count  int  not null default 0 check (opt_count between 0 and 3),
  event_only boolean not null default false,
  raid_only  boolean not null default false
);
create table if not exists public.gear_opt_pool (       -- 랜덤 부옵션 범위 (slot별)
  slot text not null, opt text not null, min_v numeric not null, max_v numeric not null, min_tier int not null default 3,
  primary key (slot, opt)
);
create table if not exists public.gear_tier_gate (      -- 챕터·탑 대역 → 드롭 등급
  band       int primary key,                           -- 1..6
  ch_from    int not null, ch_to int not null, floor_from int not null, floor_to int not null,
  main_tier  int not null check (main_tier between 1 and 5),
  bonus_tier int not null check (bonus_tier between 1 and 5),
  bonus_pct  numeric not null check (bonus_pct between 0 and 100)
);
create table if not exists public.gear_drop_mode (      -- 난이도 모드 배율
  mode text primary key check (mode in ('normal','hard','hell','abyss')),
  bonus_mult numeric not null, up_pct numeric not null, sigil_frag_pct numeric not null
);
create table if not exists public.gear_mode_config (    -- 모드별 장비 효과 (사용자 조절값)
  mode text primary key check (mode in ('story','tower','raid','pvp','war','arcade')),
  gear_pct numeric not null check (gear_pct between 0 and 100),
  sigil_max_plus int not null check (sigil_max_plus between 0 and 5)
);
create table if not exists public.gear_slot_price (     -- 가방 확장 (10칸 단위, 보석)
  slots_from int primary key, slots_to int not null, gem int not null check (gem > 0)
);
create table if not exists public.gear_raid_rewards (   -- 토벌 보상표 (PR5에서 사용)
  id serial primary key, kind text not null check (kind in ('drop','clear_box','rank_box')),
  stage_from int not null default 0, stage_to int not null default 0, rank_from int not null default 0, rank_to int not null default 0,
  tier int not null check (tier between 1 and 5), up_tier int check (up_tier between 1 and 5), up_pct numeric not null default 0,
  qty int not null default 1, sigil_frags int not null default 0,
  unique (kind, stage_from, rank_from)
);
create table if not exists public.gear_event_grants (   -- 전설·심연은 여기 적힌 것만 지급 (PR7, 지금은 비어 있음)
  id serial primary key, event_key text not null, def_id text not null references public.gear_defs(id),
  starts_at timestamptz not null, ends_at timestamptz not null, note text,
  unique (event_key, def_id)
);
create table if not exists public.sigil_defs (
  card_id   text primary key,                          -- data/cards.csv id
  name      text not null,
  effects   int  not null check (effects in (1,2)),   -- SR 1, UR 이상 2
  steps     jsonb not null,                            -- [{plus:0, mods:{...}}, ... +5]
  icon      text not null
);
create table if not exists public.sigil_sources (       -- 인재별 조각 획득처 (최소 2곳)
  card_id text not null references public.sigil_defs(card_id), source text not null
    check (source in ('story_boss','raid_select','guild_shop','pvp_shop','event','exchange')),
  ref text, primary key (card_id, source)
);
create table if not exists public.sigil_cost (          -- 단계별 필요 조각: 제작 50, +1 30, +2 50, +3 80, +4 120, +5 200 = 530
  plus int primary key check (plus between 0 and 5), frags int not null check (frags > 0)
);

-- 2) 보유 테이블 -------------------------------------------------------------
create table if not exists public.player_gear (
  id          bigint generated always as identity primary key,
  user_id     uuid not null references auth.users(id) on delete cascade,
  def_id      text not null references public.gear_defs(id),
  plus        int  not null default 0 check (plus between 0 and 5),
  opts        jsonb not null default '[]'::jsonb,
  locked      boolean not null default false,
  equipped_card text,                                  -- story_progress owned[].id
  source      text not null,
  created_at  timestamptz not null default now()
);
create index if not exists player_gear_user on public.player_gear (user_id);
create unique index if not exists player_gear_one_slot on public.player_gear (user_id, equipped_card, (split_part(def_id, '_', 1))) where equipped_card is not null;
create table if not exists public.player_gear_meta (
  user_id uuid primary key references auth.users(id) on delete cascade,
  slots   int not null default 100 check (slots between 100 and 200),
  dust    bigint not null default 0 check (dust >= 0),   -- 장비 가루 (분해 재료)
  updated_at timestamptz not null default now()
);
create table if not exists public.player_sigils (
  user_id uuid not null references auth.users(id) on delete cascade,
  card_id text not null references public.sigil_defs(card_id),
  plus    int check (plus between 0 and 5),              -- null = 아직 제작 전 (조각만 있음)
  frags   int not null default 0 check (frags >= 0),
  primary key (user_id, card_id)
);
create table if not exists public.player_mail (          -- 우편함 (기존 우편함 없음 → 신설). 7일 보관
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null check (kind in ('gear','sigil_frag','gold','gem')),
  payload jsonb not null, reason text not null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '7 days',
  claimed_at timestamptz
);
create index if not exists player_mail_user on public.player_mail (user_id) where claimed_at is null;

-- 3) RLS ---------------------------------------------------------------------
do $$ declare t text; begin
  foreach t in array array['gear_defs','gear_opt_pool','gear_tier_gate','gear_drop_mode','gear_mode_config','gear_slot_price','gear_raid_rewards','sigil_defs','sigil_sources','sigil_cost'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('drop policy if exists %I on public.%I', t || '_read', t);
    execute format('create policy %I on public.%I for select to authenticated using (true)', t || '_read', t);
  end loop;
  foreach t in array array['player_gear','player_gear_meta','player_sigils','player_mail'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('drop policy if exists %I on public.%I', t || '_own', t);
    execute format('create policy %I on public.%I for select to authenticated using (user_id = auth.uid())', t || '_own', t);
  end loop;
end $$;
alter table public.gear_event_grants enable row level security;          -- 이벤트 표는 클라이언트 비공개
revoke all on public.gear_event_grants from public, anon, authenticated;

-- 4) 내부 함수 ---------------------------------------------------------------
create or replace function public._gear_meta(p_uid uuid) returns public.player_gear_meta
language plpgsql security definer set search_path = public as $$
declare m player_gear_meta;
begin
  insert into player_gear_meta (user_id) values (p_uid) on conflict (user_id) do nothing;
  select * into m from player_gear_meta where user_id = p_uid for update;
  return m;
end $$;

-- 랜덤 부옵션
create or replace function public._gear_roll_opts(p_def text) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare d gear_defs; r jsonb := '[]'::jsonb; o record;
begin
  select * into d from gear_defs where id = p_def;
  for o in select * from gear_opt_pool where slot = d.slot and min_tier <= d.tier order by random() limit d.opt_count loop
    r := r || jsonb_build_array(jsonb_build_object('opt', o.opt, 'v', round((o.min_v + random() * (o.max_v - o.min_v))::numeric, 1)));
  end loop;
  return r;
end $$;

-- 장비 지급 (유일한 생성 경로). 영웅(5) 초과는 이벤트 지급표에 있을 때만
-- p_to_mail=true 면 가방이 꽉 차도 우편함으로. false 면 꽉 찼을 때 'bag full' 예외 (소탕·탑은 시작 전에 막음)
create or replace function public._gear_grant(p_uid uuid, p_def text, p_source text, p_to_mail boolean default false, p_event text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare d gear_defs; m player_gear_meta; n int; gid bigint;
begin
  if p_uid is null then raise exception 'login required'; end if;
  select * into d from gear_defs where id = p_def;
  if not found then raise exception 'unknown gear'; end if;
  if d.tier > 5 or d.event_only then
    if p_source <> 'event' or p_event is null or not exists (
      select 1 from gear_event_grants e where e.event_key = p_event and e.def_id = p_def and now() between e.starts_at and e.ends_at)
    then raise exception 'tier above hero is event only'; end if;
  end if;
  m := _gear_meta(p_uid);
  select count(*) into n from player_gear where user_id = p_uid;
  if n >= m.slots then
    if not p_to_mail then raise exception 'bag full'; end if;
    insert into player_mail (user_id, kind, payload, reason) values (p_uid, 'gear', jsonb_build_object('def_id', p_def, 'source', p_source, 'event', p_event), p_source);
    return jsonb_build_object('ok', true, 'mail', true);
  end if;
  insert into player_gear (user_id, def_id, opts, source, locked)
    values (p_uid, p_def, _gear_roll_opts(p_def), p_source, d.tier >= 6) returning id into gid;
  return jsonb_build_object('ok', true, 'gear_id', gid);
end $$;

-- 드롭 등급 결정 (소탕·탑). 결과는 항상 1..5. 모드 보너스도 영웅에서 멈춤
create or replace function public._gear_roll_tier(p_chapter int, p_floor int, p_mode text default 'normal') returns int
language plpgsql volatile security definer set search_path = public as $$
declare g gear_tier_gate; dm gear_drop_mode; t int;
begin
  select * into g from gear_tier_gate
    where (p_chapter is not null and p_chapter between ch_from and ch_to) or (p_floor is not null and p_floor between floor_from and floor_to)
    order by band desc limit 1;
  if not found then select * into g from gear_tier_gate order by band limit 1; end if;
  select * into dm from gear_drop_mode where mode = coalesce(p_mode, 'normal');
  if not found then select * into dm from gear_drop_mode where mode = 'normal'; end if;
  t := g.main_tier;
  if random() * 100 < g.bonus_pct * dm.bonus_mult then t := g.bonus_tier; end if;
  if random() * 100 < dm.up_pct then t := t + 1; end if;
  return least(t, 5);
end $$;

-- 장비 1개 드롭 (슬롯 랜덤). 영웅 초과는 _gear_grant 에서도 다시 거부
create or replace function public._gear_drop(p_uid uuid, p_chapter int, p_floor int, p_mode text, p_source text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare t int; did text;
begin
  t := _gear_roll_tier(p_chapter, p_floor, p_mode);
  select id into did from gear_defs where tier = t and not event_only and not raid_only order by random() limit 1;
  return _gear_grant(p_uid, did, p_source, false, null);
end $$;

revoke all on function public._gear_meta(uuid), public._gear_roll_opts(text), public._gear_grant(uuid, text, text, boolean, text),
  public._gear_roll_tier(int, int, text), public._gear_drop(uuid, int, int, text, text) from public, anon, authenticated;

-- 5) 공개 RPC (authenticated) ------------------------------------------------
-- 내 장비·증표·가방·우편 요약
create or replace function public.gear_status() returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m player_gear_meta; nx gear_slot_price;
begin
  if uid is null then raise exception 'login required'; end if;
  m := _gear_meta(uid);
  select * into nx from gear_slot_price where slots_from = m.slots + 1;
  return jsonb_build_object(
    'slots', m.slots, 'dust', m.dust,
    'count', (select count(*) from player_gear where user_id = uid),
    'next_expand', case when nx.slots_from is null then null else jsonb_build_object('to', nx.slots_to, 'gem', nx.gem) end,
    'gear', coalesce((select jsonb_agg(jsonb_build_object('id', g.id, 'def', g.def_id, 'plus', g.plus, 'opts', g.opts, 'locked', g.locked, 'card', g.equipped_card) order by g.id)
                      from player_gear g where g.user_id = uid), '[]'::jsonb),
    'sigils', coalesce((select jsonb_agg(jsonb_build_object('card', s.card_id, 'plus', s.plus, 'frags', s.frags)) from player_sigils s where s.user_id = uid), '[]'::jsonb),
    'mail', (select count(*) from player_mail where user_id = uid and claimed_at is null and expires_at > now()));
end $$;

-- 가방 확장 10칸 (보석)
create or replace function public.gear_expand() returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m player_gear_meta; p gear_slot_price; g jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  m := _gear_meta(uid);
  select * into p from gear_slot_price where slots_from = m.slots + 1;
  if not found then return jsonb_build_object('ok', false, 'reason', 'max'); end if;
  g := _gem_spend(uid, p.gem, 'gear_expand', jsonb_build_object('to', p.slots_to));
  update player_gear_meta set slots = p.slots_to, updated_at = now() where user_id = uid;
  return jsonb_build_object('ok', true, 'slots', p.slots_to, 'gem', p.gem, 'wallet', g);
exception when others then
  if sqlerrm = 'not enough gem' then return jsonb_build_object('ok', false, 'reason', 'gem', 'need', p.gem); end if;
  raise;
end $$;

-- 잠금
create or replace function public.gear_lock(p_gear bigint, p_locked boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  update player_gear set locked = coalesce(p_locked, false) where id = p_gear and user_id = uid;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not found'); end if;
  return jsonb_build_object('ok', true);
end $$;

-- 장착 (같은 인재 같은 슬롯에 있던 장비는 자동 해제). 인재는 story_progress.owned 에 있어야 함
create or replace function public.gear_equip(p_gear bigint, p_card text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); g player_gear; sl text;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into g from player_gear where id = p_gear and user_id = uid for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not found'); end if;
  if not exists (select 1 from story_progress sp, jsonb_array_elements(case when jsonb_typeof(sp.data->'owned') = 'array' then sp.data->'owned' else '[]'::jsonb end) o
                 where sp.user_id = uid and o->>'id' = p_card) then
    return jsonb_build_object('ok', false, 'reason', 'card not owned'); end if;
  sl := split_part(g.def_id, '_', 1);
  update player_gear set equipped_card = null where user_id = uid and equipped_card = p_card and split_part(def_id, '_', 1) = sl and id <> p_gear;
  update player_gear set equipped_card = p_card where id = p_gear;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.gear_unequip(p_gear bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  update player_gear set equipped_card = null where id = p_gear and user_id = uid;
  return jsonb_build_object('ok', found);
end $$;

-- 우편 목록
create or replace function public.mail_list() returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', id, 'kind', kind, 'payload', payload, 'reason', reason, 'expires_at', expires_at) order by id)
    from player_mail where user_id = uid and claimed_at is null and expires_at > now()), '[]'::jsonb);
end $$;

-- 우편 받기 (지금은 장비만. 가방이 차 있으면 거부)
create or replace function public.mail_claim(p_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); ml player_mail; d gear_defs; m player_gear_meta; n int; gid bigint;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into ml from player_mail where id = p_id and user_id = uid and claimed_at is null and expires_at > now() for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not found'); end if;
  if ml.kind <> 'gear' then return jsonb_build_object('ok', false, 'reason', 'unsupported'); end if;
  m := _gear_meta(uid);
  select count(*) into n from player_gear where user_id = uid;
  if n >= m.slots then return jsonb_build_object('ok', false, 'reason', 'bag full'); end if;
  select * into d from gear_defs where id = ml.payload->>'def_id';
  -- 우편은 지급 시점에 이미 검사됨. 그래도 영웅 초과는 이벤트 우편만 허용
  if d.tier > 5 and coalesce(ml.payload->>'source', '') <> 'event' then return jsonb_build_object('ok', false, 'reason', 'event only'); end if;
  insert into player_gear (user_id, def_id, opts, source, locked) values (uid, d.id, _gear_roll_opts(d.id), 'mail:' || ml.reason, d.tier >= 6) returning id into gid;
  update player_mail set claimed_at = now() where id = p_id;
  return jsonb_build_object('ok', true, 'gear_id', gid);
end $$;

revoke all on function public.gear_status(), public.gear_expand(), public.gear_lock(bigint, boolean), public.gear_equip(bigint, text),
  public.gear_unequip(bigint), public.mail_list(), public.mail_claim(bigint) from public, anon;
grant execute on function public.gear_status(), public.gear_expand(), public.gear_lock(bigint, boolean), public.gear_equip(bigint, text),
  public.gear_unequip(bigint), public.mail_list(), public.mail_claim(bigint) to authenticated;

