-- ===== SOURCE: guild_lend.sql =====
-- =====================================================================
-- 조직 인재 대여 — Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전 (새 테이블·함수만, 기존 데이터 삭제 없음)
-- 선행: guild.sql (guild_members · _loyalty_add · _guild_day), story_server.sql (story_progress 서버 저장)
--   · 내 인재 최대 3명을 조직에 대여 등록 (내가 계속 써도 됨)
--   · 조직원은 하루(KST) 1명 대여 · 12시간 뒤 자동 반납 (expires_at 지나면 끝)
--   · 대여 인재 = 빌릴 때 원주인의 레벨·스탯 그대로(스냅샷) · 스토리·시련의 탑에서만
--   · 내 인재는 못 빌림 · 이미 같은 인재(같은 카드)를 가지고 있으면 못 빌림
--   · 빌려줄 때마다 원주인에게 충성 +20 (_lend_reward 로 조정)
-- =====================================================================
create table if not exists public.guild_lend_slots (
  user_id uuid not null references auth.users(id) on delete cascade,
  uid text not null check (char_length(uid) <= 80),
  card_id text not null,
  created_at timestamptz not null default now(),
  primary key (user_id, uid));
create table if not exists public.guild_loans (
  id bigint generated always as identity primary key,
  borrower uuid not null references auth.users(id) on delete cascade,
  lender uuid not null references auth.users(id) on delete cascade,
  guild_id bigint not null,
  card_id text not null, src_uid text not null, snap jsonb not null,
  day date not null, borrowed_at timestamptz not null default now(), expires_at timestamptz not null,
  unique (borrower, day));
create index if not exists guild_loans_borrower on public.guild_loans (borrower, expires_at desc);
alter table public.guild_lend_slots enable row level security;
alter table public.guild_loans enable row level security;
revoke all on public.guild_lend_slots, public.guild_loans from anon, authenticated;   -- 읽기·쓰기 모두 아래 함수로만

create or replace function public._lend_reward() returns int language sql immutable as $$ select 20 $$;
create or replace function public._lend_hours() returns int language sql immutable as $$ select 12 $$;
create or replace function public._lend_max() returns int language sql immutable as $$ select 3 $$;

-- 내 보유 인재 (story_progress.data.owned) 에서 uid 로 한 장
create or replace function public._lend_owned(p_uid uuid, p_card_uid text) returns jsonb language sql stable security definer set search_path = public as $$
  select o from story_progress s, jsonb_array_elements(case when jsonb_typeof(s.data->'owned') = 'array' then s.data->'owned' else '[]'::jsonb end) o
  where s.user_id = p_uid and o->>'uid' = p_card_uid limit 1 $$;

-- 등록 바꾸기: p_uids = 내 인재 uid 최대 3개 (빈 배열 = 전부 해제)
create or replace function public.guild_lend_set(p_uids jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); u text; o jsonb; n int := 0;
begin
  if me is null then raise exception 'login required'; end if;
  if not exists (select 1 from guild_members where user_id = me) then raise exception 'not in guild'; end if;
  if jsonb_typeof(p_uids) <> 'array' or jsonb_array_length(p_uids) > _lend_max() then raise exception 'too many'; end if;
  delete from guild_lend_slots where user_id = me;
  for u in select distinct value from jsonb_array_elements_text(p_uids) loop
    o := _lend_owned(me, u);
    if o is null then raise exception 'not owned'; end if;
    if exists (select 1 from guild_lend_slots where user_id = me and card_id = o->>'id') then continue; end if;   -- 같은 카드 두 장 X
    insert into guild_lend_slots (user_id, uid, card_id) values (me, u, o->>'id'); n := n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'n', n);
end $$;

-- 대여 화면: 내 등록 · 조직원 등록 인재(원주인 레벨) · 내 대여 중 · 오늘 빌렸는지
create or replace function public.guild_lend_status() returns jsonb language plpgsql stable security definer set search_path = public as $$
declare me uuid := auth.uid(); gid bigint; mine jsonb; others jsonb; cur jsonb; today boolean;
begin
  if me is null then raise exception 'login required'; end if;
  select guild_id into gid from guild_members where user_id = me;
  if gid is null then return jsonb_build_object('in_guild', false); end if;
  select coalesce(jsonb_agg(jsonb_build_object('uid', s.uid, 'id', s.card_id, 'level', (_lend_owned(me, s.uid)->>'level')::int) order by s.created_at), '[]'::jsonb) into mine
    from guild_lend_slots s where s.user_id = me and _lend_owned(me, s.uid) is not null;
  select coalesce(jsonb_agg(jsonb_build_object('owner', s.user_id, 'owner_name', coalesce(p.nickname, '조직원'), 'uid', s.uid, 'id', s.card_id, 'level', (o.o->>'level')::int) order by p.nickname, s.created_at), '[]'::jsonb) into others
    from guild_lend_slots s join guild_members m on m.user_id = s.user_id and m.guild_id = gid left join profiles p on p.id = s.user_id
    cross join lateral (select _lend_owned(s.user_id, s.uid) o) o
    where s.user_id <> me and o.o is not null;
  select jsonb_build_object('id', l.id, 'card_id', l.card_id, 'snap', l.snap, 'lender', l.lender, 'lender_name', coalesce(p.nickname, '조직원'), 'expires_at', l.expires_at) into cur
    from guild_loans l left join profiles p on p.id = l.lender where l.borrower = me and l.expires_at > now() order by l.expires_at desc limit 1;
  today := exists (select 1 from guild_loans where borrower = me and day = _guild_day());
  return jsonb_build_object('in_guild', true, 'max', _lend_max(), 'hours', _lend_hours(), 'reward', _lend_reward(), 'mine', mine, 'others', others, 'loan', cur, 'borrowed_today', today, 'now', now());
end $$;

-- 빌리기: 하루 1명 · 12시간 · 같은 조직 · 내 것 X · 같은 카드 보유 X · 원주인 레벨 스냅샷 · 원주인 충성 +보상
create or replace function public.guild_lend_borrow(p_owner uuid, p_uid text) returns jsonb language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); gid bigint; s guild_lend_slots; o jsonb; snap jsonb; lid bigint; ex timestamptz;
begin
  if me is null then raise exception 'login required'; end if;
  if p_owner = me then raise exception 'own card'; end if;
  select guild_id into gid from guild_members where user_id = me;
  if gid is null then raise exception 'not in guild'; end if;
  if not exists (select 1 from guild_members where user_id = p_owner and guild_id = gid) then raise exception 'not guildmate'; end if;
  perform pg_advisory_xact_lock(hashtext('guild_lend:' || me::text));
  if exists (select 1 from guild_loans where borrower = me and day = _guild_day()) then raise exception 'already borrowed today'; end if;
  select * into s from guild_lend_slots where user_id = p_owner and uid = p_uid;
  if s.user_id is null then raise exception 'not lendable'; end if;
  o := _lend_owned(p_owner, p_uid);
  if o is null then raise exception 'not lendable'; end if;
  if exists (select 1 from story_progress sp, jsonb_array_elements(case when jsonb_typeof(sp.data->'owned') = 'array' then sp.data->'owned' else '[]'::jsonb end) x
             where sp.user_id = me and x->>'id' = s.card_id) then raise exception 'already own card'; end if;
  snap := jsonb_strip_nulls(jsonb_build_object('id', o->'id', 'level', o->'level', 'boost', o->'boost', 'ex', o->'ex', 'exb', o->'exb', 'skillLv', o->'skillLv'));
  ex := now() + make_interval(hours => _lend_hours());
  insert into guild_loans (borrower, lender, guild_id, card_id, src_uid, snap, day, expires_at) values (me, p_owner, gid, s.card_id, p_uid, snap, _guild_day(), ex) returning id into lid;
  perform _loyalty_add(p_owner, _lend_reward(), 'lend', 'lend:' || lid, jsonb_build_object('borrower', me, 'card', s.card_id));
  perform _guild_log(gid, me, 'lend', p_owner, jsonb_build_object('card', s.card_id));
  return jsonb_build_object('ok', true, 'id', lid, 'card_id', s.card_id, 'snap', snap, 'expires_at', ex);
end $$;

-- 일찍 반납 (선택)
create or replace function public.guild_lend_return() returns jsonb language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); n int;
begin
  if me is null then raise exception 'login required'; end if;
  update guild_loans set expires_at = now() where borrower = me and expires_at > now(); get diagnostics n = row_count;
  return jsonb_build_object('ok', true, 'n', n);
end $$;

revoke all on function public._lend_owned(uuid, text), public._lend_reward(), public._lend_hours(), public._lend_max() from public, anon, authenticated;
revoke all on function public.guild_lend_set(jsonb), public.guild_lend_status(), public.guild_lend_borrow(uuid, text), public.guild_lend_return() from public, anon;
grant execute on function public.guild_lend_set(jsonb), public.guild_lend_status(), public.guild_lend_borrow(uuid, text), public.guild_lend_return() to authenticated;
select 'guild_lend ok' as result;


-- ===== SOURCE: story_decks10.sql =====
-- 마이 덱: 덱당 최대 5장 → 10장 (스토리 마나 전투 손패 10장). story_set_decks 만 다시 정의 · 여러 번 실행해도 안전 · 데이터 삭제 없음
-- 탑·PvP·전쟁·토벌은 클라이언트에서 앞 5장만 씀
create or replace function public.story_set_decks(p_decks jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); d jsonb; owned jsonb; clean jsonb := '[]'::jsonb; x jsonb; ids jsonb; u text; nm text;
        alluids text[] := '{}'; mine text[]; i int; e jsonb;
begin
  d := _story_lock(uid);
  owned := _story_owned(d);
  if p_decks is null or jsonb_typeof(p_decks) <> 'array' then raise exception 'bad decks'; end if;
  if jsonb_array_length(p_decks) > 10 then raise exception 'too many decks'; end if;
  select coalesce(array_agg(o->>'uid'), '{}') into mine from jsonb_array_elements(owned) o where coalesce(o->>'uid', '') <> '' and o->>'uid' not like 'guest:%';
  for x in select * from jsonb_array_elements(p_decks) loop
    if jsonb_typeof(x) <> 'object' then raise exception 'bad deck'; end if;
    nm := left(btrim(coalesce(x->>'name', '')), 16);
    ids := '[]'::jsonb;
    if jsonb_typeof(x->'uids') = 'array' then
      if jsonb_array_length(x->'uids') > 10 then raise exception 'deck too large'; end if;
      for u in select jsonb_array_elements_text(x->'uids') loop
        if not (u = any(mine)) then raise exception 'card not owned'; end if;
        if not (ids @> to_jsonb(u)) then ids := ids || to_jsonb(u); alluids := alluids || u; end if;
      end loop;
    end if;
    clean := clean || jsonb_build_object('name', nm, 'uids', ids);
  end loop;
  for i in 0 .. coalesce(jsonb_array_length(owned), 0) - 1 loop
    e := owned->i;
    if (e->>'uid') = any(alluids) then
      if not coalesce((e->>'locked')::boolean, false) then e := e || jsonb_build_object('locked', true, 'dlk', true); end if;
    elsif coalesce((e->>'dlk')::boolean, false) then
      e := e - 'locked' - 'dlk';
    end if;
    owned := jsonb_set(owned, array[i::text], e);
  end loop;
  d := jsonb_set(jsonb_set(d, '{owned}', owned), '{decks}', clean);
  d := _story_save(uid, d);
  return jsonb_build_object('data', d, 'decks', clean);
end $$;
revoke all on function public.story_set_decks(jsonb) from public, anon;
grant execute on function public.story_set_decks(jsonb) to authenticated;
select 'story_decks10 ok' as result;


-- ===== SOURCE: guild_lend_notice.sql =====
-- 조직 인재 대여 알림 — 선행: guild_lend.sql. 여러 번 실행해도 안전 (열 추가·함수만, 삭제 없음)
-- 내 인재를 누가 빌리면, 다음에 게임/조직 홈을 열 때 'OO님이 OO를 빌렸어요 · 충성 +20' 을 한 번 보여 주고 읽음 표시
alter table public.guild_loans add column if not exists lender_seen boolean not null default false;
create index if not exists guild_loans_lender_unseen on public.guild_loans (lender) where not lender_seen;

-- 안 본 알림 (최근 30개, 7일 안) 을 돌려주고 읽음으로 표시
create or replace function public.guild_lend_notices() returns jsonb language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); r jsonb;
begin
  if me is null then raise exception 'login required'; end if;
  with x as (
    select l.id from guild_loans l where l.lender = me and not l.lender_seen and l.borrowed_at > now() - interval '7 days' order by l.borrowed_at desc limit 30),
  u as (update guild_loans l set lender_seen = true from x where l.id = x.id returning l.*)
  select coalesce(jsonb_agg(jsonb_build_object('borrower_name', coalesce(p.nickname, '조직원'), 'card_id', u.card_id, 'reward', _lend_reward(), 'at', u.borrowed_at) order by u.borrowed_at desc), '[]'::jsonb) into r
    from u left join profiles p on p.id = u.borrower;
  update guild_loans set lender_seen = true where lender = me and not lender_seen;   -- 7일 지난 것도 정리
  return r;
end $$;
revoke all on function public.guild_lend_notices() from public, anon;
grant execute on function public.guild_lend_notices() to authenticated;
select 'guild_lend_notice ok' as result;


-- ===== SOURCE: story_stars.sql =====
-- 스토리 별점(★1~3, 마나 전투) — 페이즈별 최고 별 저장. 여러 번 실행해도 안전 (함수만, 데이터 삭제 없음)
-- 저장 위치: story_progress.data.stars = { "<챕터>": { "<페이즈>": 1~3 } } · 이미 클리어한 페이즈만, 더 높을 때만 갱신
-- 별 계산은 클라이언트(보상 없음): ★1 클리어 · +★ 내 턴 10턴 이내 · +★ 남은 마나 30% 이상
create or replace function public.story_set_stars(p_chapter int, p_phase int, p_stars int) returns jsonb language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); d jsonb; cur int; s int := greatest(1, least(3, coalesce(p_stars, 1)));
begin
  if me is null then raise exception 'login required'; end if;
  if not exists (select 1 from story_phase_config where chapter = p_chapter and phase = p_phase) then raise exception 'invalid phase'; end if;
  d := _story_lock(me);
  if not (coalesce(d->'cleared'->(p_chapter::text), '[]'::jsonb) @> to_jsonb(p_phase)) then raise exception 'not cleared'; end if;
  cur := coalesce((d->'stars'->(p_chapter::text)->>(p_phase::text))::int, 0);
  if s > cur then
    if jsonb_typeof(d->'stars') is distinct from 'object' then d := jsonb_set(d, '{stars}', '{}'::jsonb); end if;
    if jsonb_typeof(d->'stars'->(p_chapter::text)) is distinct from 'object' then d := jsonb_set(d, array['stars', p_chapter::text], '{}'::jsonb); end if;
    d := jsonb_set(d, array['stars', p_chapter::text, p_phase::text], to_jsonb(s));
    d := _story_save(me, d); cur := s;
  end if;
  return jsonb_build_object('ok', true, 'stars', cur, 'all', coalesce(d->'stars', '{}'::jsonb));
end $$;
revoke all on function public.story_set_stars(int, int, int) from public, anon;
grant execute on function public.story_set_stars(int, int, int) to authenticated;
select 'story_stars ok' as result;


-- ===== SOURCE: blood_rebalance.sql =====
-- =====================================================================
-- 피 리밸런스 (1/2): 카드 레벨업 비용 50% 감소 + LEGENDARY RARE 계수 추가
-- Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전 (함수 재정의만)
-- 선행: phaseE_4.sql (phaseE_3.sql / phaseE_4.sql 은 다시 돌리지 마세요 - 예전 비용으로 돌아감)
--
-- 레벨업 L → L+1:  순수한 피 = ceil(b × L × 0.5),  골드 = ceil(g × L × 10 × 0.5)   (올림이라 최소 1)
--   N b2 g1 · R b3 g1.5 · HR b5 g2 · SR b8 g3 · UR b12 g4 · MR b18 g6 · LR b27 g9 (LR 은 새로 추가, 클라와 맞춤)
--   배율은 _lv_cost_mult() 한 곳. 클라 js/story.js 의 LV_MULT 도 같이 바꿔야 해요
-- 분해 환급(쓴 피 50%)은 카드의 bloodSpent 기준이라 자동으로 새 비용 기준이 됨
-- 기존 유저 차액 환급은 blood_rebalance_refund.sql (따로, 1회)
-- 확인용: select public.card_cost_table();   → version 5, grades.SUPER RARE.lv1 = {"blood":4,"gold":15}
-- =====================================================================

create or replace function public._lv_cost_mult() returns numeric language sql immutable as $$ select 0.5::numeric $$;
create or replace function public._lv_cost_b(p_grade text) returns numeric language sql immutable as $$
  select case p_grade when 'NORMAL' then 2 when 'RARE' then 3 when 'HIGH RARE' then 5 when 'SUPER RARE' then 8 when 'ULTRA RARE' then 12 when 'MYTHIC RARE' then 18 when 'LEGENDARY RARE' then 27 else 2 end::numeric $$;
create or replace function public._lv_cost_g(p_grade text) returns numeric language sql immutable as $$
  select case p_grade when 'NORMAL' then 1 when 'RARE' then 1.5 when 'HIGH RARE' then 2 when 'SUPER RARE' then 3 when 'ULTRA RARE' then 4 when 'MYTHIC RARE' then 6 when 'LEGENDARY RARE' then 9 else 1 end::numeric $$;
create or replace function public._lv_cost(p_grade text, p_level int) returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'blood', greatest(1, ceil(_lv_cost_b(p_grade) * p_level * _lv_cost_mult()))::int,
    'gold',  greatest(1, ceil(_lv_cost_g(p_grade) * p_level * 10 * _lv_cost_mult()))::int) $$;
revoke all on function public._lv_cost_mult() from public, anon, authenticated;

create or replace function public.card_cost_table() returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('ok', true, 'version', 5, 'mult', _lv_cost_mult(),
    'grades', jsonb_object_agg(g, jsonb_build_object('b', _lv_cost_b(g), 'g', _lv_cost_g(g), 'shard', _merge_shard_base(g), 'lv1', _lv_cost(g, 1))))
  from unnest(array['NORMAL','RARE','HIGH RARE','SUPER RARE','ULTRA RARE','MYTHIC RARE','LEGENDARY RARE']) g
$$;
revoke all on function public.card_cost_table() from public, anon;
grant execute on function public.card_cost_table() to authenticated;


-- ===== SOURCE: story_level_gate.sql =====
-- 스토리 챕터 입장 레벨 제한 (계정 레벨 player_state.level) — 선행: phaseE_2.sql (+ 이후 파일들)
-- ⚠ 이 파일 실행 뒤에는 phaseE_2.sql 을 다시 돌리지 마세요 (_player_unlock_level · _player_json · story_start_phase 가 옛 버전으로 돌아가 제한이 사라짐)
-- 여러 번 실행해도 안전 (함수만, 데이터 변경 없음)
-- 설정은 _player_unlock_level('chapter_N') 한 곳. 클라이언트는 _player_json 의 unlocks.chapters 로 받음
-- 규칙: 그 챕터를 아직 한 페이즈도 클리어하지 않은 경우에만 막음 → 이미 시작한 챕터는 레벨과 상관없이 계속·다시 하기 가능
--       소탕은 클리어한 페이즈만 가능하므로 자연히 영향 없음 (변경 없음)

-- 1) 해금 레벨 (기존 키 그대로 + chapter_2 ~ chapter_11)
create or replace function public._player_unlock_level(p_key text) returns int language sql immutable as $$
  select case p_key when 'sweep' then 5 when 'skill' then 10 when 'equip' then 15 when 'equip_merge' then 20
    when 'chapter_2' then 7 when 'chapter_3' then 9 when 'chapter_4' then 11 when 'chapter_5' then 12 when 'chapter_6' then 14
    when 'chapter_7' then 15 when 'chapter_8' then 16 when 'chapter_9' then 18 when 'chapter_10' then 20 when 'chapter_11' then 21 when 'chapter_12' then 22 when 'chapter_13' then 23 when 'chapter_14' then 24 when 'chapter_15' then 25
    else null end $$;

-- 2) 플레이어 정보: unlocks.chapters = { "2": 7, "3": 9, ... } 추가 (나머지는 phaseE_2 와 동일)
create or replace function public._player_json(p_uid uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare ps player_state; mx int; secs int := _stamina_regen_secs(); chs jsonb;
begin
  ps := _player_sync(p_uid); mx := _stamina_max(ps.level);
  select coalesce(jsonb_object_agg(c::text, _player_unlock_level('chapter_' || c)), '{}'::jsonb) into chs
    from generate_series(0, 30) c where _player_unlock_level('chapter_' || c) is not null;
  return jsonb_build_object('ok', true, 'level', ps.level, 'max_level', _player_max_level(), 'xp', ps.xp,
    'xp_next', case when ps.level >= _player_max_level() then 0 else _player_xp_need(ps.level) end,
    'stamina', ps.stamina, 'stamina_max', mx, 'regen_secs', secs,
    'next_regen_secs', case when ps.stamina >= mx then 0 else greatest(0, secs - floor(extract(epoch from (now() - ps.stamina_at)))::int) end,
    'cost', jsonb_build_object('story', _stamina_cost(0, 0), 'quest', 0, 'arcade', 0),
    'unlocks', jsonb_build_object('sweep', _player_unlock_level('sweep'), 'skill', _player_unlock_level('skill'), 'equip', _player_unlock_level('equip'), 'equip_merge', _player_unlock_level('equip_merge'), 'chapters', chs));
end $$;

-- 3) 전투 시작: 레벨 제한 검사 추가 (나머지는 phaseE_2 wrapper 와 동일 — 'phaseE_2 wrapper' 표시 유지해서 phaseE_2 의 보관 로직이 원본으로 착각하지 않게)
create or replace function public.story_start_phase(p_chapter int, p_phase int) returns jsonb language plpgsql security definer set search_path = public as $$
-- phaseE_2 wrapper (+ story_level_gate)
declare uid uuid := auth.uid(); b jsonb; d jsonb; cost int := _stamina_cost(p_chapter, p_phase); need int := _player_unlock_level('chapter_' || p_chapter); lv int; started boolean;
begin
  if uid is null then raise exception 'login required'; end if;
  perform _player_sync(uid);
  select data->'battle' into b from story_progress where user_id = uid for update;
  if need is not null then
    select coalesce(jsonb_array_length(data->'cleared'->(p_chapter::text)), 0) > 0 into started from story_progress where user_id = uid;
    if not coalesce(started, false) then
      select level into lv from player_state where user_id = uid;
      if coalesce(lv, 1) < need then raise exception 'level required: chapter % needs level %', p_chapter, need; end if;
    end if;
  end if;
  if b is not null and (b->>'stamina') is not null then perform _player_stamina_add(uid, (b->>'stamina')::int); end if;
  perform _player_stamina_add(uid, -cost);   -- 부족하면 'not enough stamina' (전체 롤백)
  d := _story_start_phase_e0(p_chapter, p_phase);
  d := jsonb_set(d, '{battle,stamina}', to_jsonb(cost));
  update story_progress set data = d where user_id = uid;
  return d;
end $$;

revoke all on function public._player_json(uuid) from public, anon, authenticated;
revoke all on function public.story_start_phase(int, int) from public, anon;
grant execute on function public.story_start_phase(int, int) to authenticated;


-- ===== SOURCE: lr_grade_align.sql =====
-- =====================================================================
-- LEGENDARY RARE(LR) 서버 등급표를 클라(js/story.js)와 맞춤
-- Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전 (함수 재정의만, LR 줄만 추가 / 다른 등급 숫자는 그대로)
-- 선행: story_merge.sql, story_levels.sql, phaseE_3.sql, phaseE_4.sql, phaseE_6.sql, blood_rebalance.sql
-- ⚠ 이 파일 이후 위 예전 파일들을 다시 돌리면 LR 이 빠져요 (README 표 참고)
--
--   _story_cap        최대 레벨  LR 100 (+5/EX)   ← 기존엔 else 20
--   _story_max_ex     최대 EX    LR 7
--   _story_feed_exp   먹이 EXP   LR 12000
--   _dismantle_yield  분해       LR 골드 5000 · 피 3000 · 혼 200
--   _merge_shard_base EX 조각    LR 60
--   _skill_soul_base  스킬 혼    LR 18
--   (레벨업 피·골드 LR 27·9 는 blood_rebalance.sql 에 이미 있음)
-- 확인용: select public._story_cap('LEGENDARY RARE', 0);  → 100   (SQL Editor 에서)
-- =====================================================================

create or replace function public._story_cap(g text, ex int default 0) returns int language sql immutable as $$
  select (case g when 'NORMAL' then 20 when 'RARE' then 30 when 'HIGH RARE' then 40 when 'SUPER RARE' then 50 when 'ULTRA RARE' then 60 when 'MYTHIC RARE' then 70 when 'LEGENDARY RARE' then 100 else 20 end) + 5 * greatest(0, coalesce(ex, 0))
$$;
create or replace function public._story_max_ex(g text) returns int language sql immutable as $$
  select case g when 'NORMAL' then 1 when 'RARE' then 2 when 'HIGH RARE' then 3 when 'SUPER RARE' then 4 when 'ULTRA RARE' then 5 when 'MYTHIC RARE' then 6 when 'LEGENDARY RARE' then 7 else 1 end
$$;
create or replace function public._story_feed_exp(g text) returns int language sql immutable as $$
  select case g when 'NORMAL' then 50 when 'RARE' then 150 when 'HIGH RARE' then 400 when 'SUPER RARE' then 1000 when 'ULTRA RARE' then 3000 when 'MYTHIC RARE' then 6000 when 'LEGENDARY RARE' then 12000 else 50 end
$$;
create or replace function public._dismantle_yield(p_grade text) returns jsonb language sql immutable as $$
  select case p_grade
    when 'NORMAL'         then '{"gold":20,"blood":10,"soul":0}'
    when 'RARE'           then '{"gold":50,"blood":30,"soul":1}'
    when 'HIGH RARE'      then '{"gold":120,"blood":80,"soul":3}'
    when 'SUPER RARE'     then '{"gold":300,"blood":200,"soul":10}'
    when 'ULTRA RARE'     then '{"gold":800,"blood":500,"soul":30}'
    when 'MYTHIC RARE'    then '{"gold":2000,"blood":1200,"soul":80}'
    when 'LEGENDARY RARE' then '{"gold":5000,"blood":3000,"soul":200}'
    else '{"gold":20,"blood":10,"soul":0}' end::jsonb
$$;
create or replace function public._merge_shard_base(p_grade text) returns int language sql immutable as $$
  select case p_grade when 'NORMAL' then 1 when 'RARE' then 2 when 'HIGH RARE' then 4 when 'SUPER RARE' then 8 when 'ULTRA RARE' then 15 when 'MYTHIC RARE' then 30 when 'LEGENDARY RARE' then 60 else 1 end $$;
create or replace function public._skill_soul_base(p_grade text) returns int language sql immutable as $$
  select case p_grade when 'NORMAL' then 1 when 'RARE' then 2 when 'HIGH RARE' then 3 when 'SUPER RARE' then 5 when 'ULTRA RARE' then 8 when 'MYTHIC RARE' then 12 when 'LEGENDARY RARE' then 18 else 1 end $$;

revoke all on function public._story_cap(text, int), public._story_max_ex(text), public._story_feed_exp(text), public._dismantle_yield(text),
  public._merge_shard_base(text), public._skill_soul_base(text) from public, anon, authenticated;


-- ===== SOURCE: story_ch0_jieun.sql =====
-- =====================================================================
-- 챕터 0 클리어 강제 10회 영입(임유리 튜토리얼)에서 하지은(10439) 확정 — 계정당 한 번
-- 조건: 10회 뽑기 · 강제 영입이 아직 안 끝남(save.ch0Pull 없음) · 확정 받은 적 없음(save.ch0Jieun 없음)
-- 10장 중 무작위 한 자리를 하지은으로, 나머지 9장은 기존과 같이 무작위. 그 외 동작은 story_gacha.sql 과 동일
-- 여러 번 실행해도 안전 (story_ticket_draw 만 교체)
-- =====================================================================
create or replace function public.story_ticket_draw(p_count int) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); s jsonb; t int; r double precision; g text; cid text; d jsonb; owned jsonb; e jsonb; out jsonb := '[]'::jsonb; i int; hr boolean := false;
  jslot int := 0;
begin
  if uid is null then raise exception 'login required'; end if;
  if p_count is null or p_count not in (1, 10) then raise exception 'invalid count'; end if;
  s := _story_ticket_sync(uid);   -- story_gacha 행 잠금 포함
  t := (s->>'tickets')::int;
  if t < p_count then return jsonb_build_object('ok', false, 'reason', 'tickets', 'tickets', t, 'added', (s->>'added')::int); end if;
  d := _story_lock(uid);
  owned := _story_owned(d);
  if p_count = 10 and coalesce((d->>'ch0Pull')::boolean, false) = false and coalesce((d->>'ch0Jieun')::boolean, false) = false then
    jslot := 1 + floor(random() * 10)::int;   -- 강제 영입: 하지은 자리
    d := jsonb_set(d, '{ch0Jieun}', 'true'::jsonb);
  end if;
  for i in 1..p_count loop
    if i = jslot then
      cid := '10439'; g := 'SUPER RARE';
    else
      r := random();
      if p_count = 10 and i = 10 and not hr then   -- 10회 보장: 앞 9장이 모두 R 이하면 마지막 장은 HR 이상 (HR:SR:UR = 16:3.2:0.8)
        r := 0.80 + random() * 0.20;
      end if;
      g := case when r < 0.50 then 'NORMAL' when r < 0.80 then 'RARE' when r < 0.96 then 'HIGH RARE' when r < 0.992 then 'SUPER RARE' else 'ULTRA RARE' end;
      cid := null;
      select id into cid from story_card_pool where grade = g and coalesce(gacha, true) order by random() limit 1;
      if cid is null then raise exception 'empty pool for %', g; end if;
    end if;
    if g in ('HIGH RARE', 'SUPER RARE', 'ULTRA RARE') then hr := true; end if;
    e := _story_new_card(cid);
    owned := owned || jsonb_build_array(e);
    out := out || jsonb_build_array(jsonb_build_object('card_id', cid, 'uid', e->>'uid', 'grade', g));
    insert into story_gacha_log (user_id, card_id, grade, kind) values (uid, cid, g, 'ticket');
  end loop;
  d := _story_save(uid, jsonb_set(d, '{owned}', owned));
  update story_gacha set tickets = tickets - p_count, updated_at = now() where user_id = uid;
  return jsonb_build_object('ok', true, 'cards', out, 'tickets', t - p_count, 'added', (s->>'added')::int);
end $$;
revoke all on function public.story_ticket_draw(int) from public, anon;
grant execute on function public.story_ticket_draw(int) to authenticated;


-- ===== SOURCE: pvp_boss_league.sql =====
-- =====================================================================
-- PvP 보스리그 (mode = 'boss'). pvp.sql · pvp_tier.sql · gem.sql 다음에 실행. 여러 번 실행해도 안전.
--   기존 PvP 구조 그대로 (pvp_set_deck / pvp_status / pvp_start / pvp_report / pvp_rankings / pvp_claim_reward / 티어·연승)
--   p_mode = 'boss' 로 부르면 레이팅·랭킹·하루 10회·시즌 보상이 1v1·3v3 과 따로.
--   덱 1~5장, 첫 장 = 수비대장 (HR 이하, 서버 트리거로 검사). 승패 = 상대 진영 HP 0 (클라이언트 pvp-core.js boss 모드)
--   기존 pvp 데이터(덱·레이팅·기록·보상)는 건드리지 않음. 바뀌는 것: pvp_decks 의 mode 체크 · _pvp_ok · 트리거 · 보상표 행 추가
-- =====================================================================

-- 1) pvp_decks.mode 에 'boss' 허용 (mode 체크 제약만 다시 만듦)
do $$ declare c text; begin
  for c in select conname from pg_constraint where conrelid = 'public.pvp_decks'::regclass and contype = 'c' and pg_get_constraintdef(oid) ilike '%mode%' loop
    execute format('alter table public.pvp_decks drop constraint %I', c);
  end loop;
end $$;
alter table public.pvp_decks add constraint pvp_decks_mode_check check (mode in ('1v1','3v3','boss'));

-- 2) 모드 확인: boss = 덱 1개 (1판)
create or replace function public._pvp_ok(p_league text, p_mode text) returns int language plpgsql immutable as $$
begin
  if p_league not in ('open','hr') then raise exception 'bad league'; end if;
  if p_mode = '1v1' then return 1; elsif p_mode = '3v3' then return 3; elsif p_mode = 'boss' then return 1; end if;
  raise exception 'bad mode';
end $$;

-- 3) 보스리그 덱: 첫 장(수비대장)은 HR 이하
create or replace function public._pvp_boss_deck_chk() returns trigger language plpgsql security definer set search_path = public as $$
declare g text;
begin
  if new.mode <> 'boss' then return new; end if;
  select grade into g from pvp_card_meta where id = new.snap->0->>'id';
  if g is null or g not in ('NORMAL','RARE','HIGH RARE') then raise exception 'guard grade'; end if;
  return new;
end $$;
revoke all on function public._pvp_boss_deck_chk() from public, anon, authenticated;
drop trigger if exists pvp_boss_deck_chk on public.pvp_decks;
create trigger pvp_boss_deck_chk before insert or update on public.pvp_decks for each row execute function public._pvp_boss_deck_chk();

-- 4) 시즌 순위 보상 (1v1 과 같은 값)
insert into public.pvp_reward_table (league, mode, rank_from, rank_to, reward)
select l, 'boss', f, t, r::jsonb from (values ('open'), ('hr')) a(l),
  (values (1, 1, '{"gold":3000,"soul":50,"tickets":50}'), (2, 3, '{"gold":2000,"soul":30,"tickets":30}'), (4, 10, '{"gold":1200,"soul":15,"tickets":20}'),
          (11, 50, '{"gold":600,"shard":20,"tickets":10}'), (51, 100, '{"gold":300,"shard":10,"tickets":10}'), (101, 1000000, '{"gold":100,"tickets":5}')) c(f, t, r)
on conflict (league, mode, rank_from) do update set rank_to = excluded.rank_to, reward = excluded.reward;

-- 확인: select public.pvp_rankings('open','boss');   → {"season":..., "top":[], "me":null}


-- ===== SOURCE: story_ch0_p5.sql =====
-- 챕터 0 Phase 5 (보스전 튜토리얼 「수비대장이라고?」) — Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전 (추가·갱신만, 삭제 없음)
-- 보스 안지수(10229) + 부하 4명 (주예나·동지선·남태은·류하예) · 첫 클리어 보상 주예린(10392)
-- 서버 순서 규칙(_story_start_phase_e0): P5 는 P1~P4 를 모두 깬 뒤에만 시작 가능 → P4 를 안 깬 사용자는 P4 부터
