-- ===== SOURCE: nickname.sql =====
-- 닉네임: 직접 정하기 · 2~12자 · 중복 금지(대소문자 무시). 여러 번 실행해도 안전.
-- 화면(랭킹·PvP·친구·조직 등)은 원래 profiles.nickname 을 쓰므로 이름 표시는 그대로 이 값을 따라감.
-- nick_set = 본인이 직접 정했는지. false 면 로그인 때 닉네임 짓기 창이 뜸 (기존 구글 이름은 그때까지 임시 표시).

alter table public.profiles add column if not exists nick_set boolean not null default false;

-- 직접 정한 닉네임끼리 중복 금지 (대소문자·앞뒤 공백 무시). 구글 이름(임시)은 기존 중복이 있어서 제외
create unique index if not exists profiles_nick_unique on public.profiles (lower(btrim(nickname))) where nick_set;

-- 클라이언트는 아바타만 직접 고칠 수 있음. 닉네임은 set_nickname() 으로만
revoke update on public.profiles from authenticated, anon;
grant update (avatar_url, updated_at) on public.profiles to authenticated;
revoke insert on public.profiles from authenticated, anon;
grant insert (id, nickname, avatar_url) on public.profiles to authenticated;

-- set_nickname 밖에서 닉네임이 바뀌면(관리자 초기화 등) '직접 정함' 표시를 풀어서 다시 짓게 함
create or replace function public._profiles_nick_guard() returns trigger language plpgsql as $$
begin
  if coalesce(current_setting('app.nick_rpc', true), '') <> '1' then
    if tg_op = 'INSERT' then new.nick_set := false;
    elsif new.nickname is distinct from old.nickname or new.nick_set is distinct from old.nick_set then new.nick_set := false; end if;
  end if;
  return new;
end $$;
drop trigger if exists profiles_nick_guard on public.profiles;
create trigger profiles_nick_guard before insert or update on public.profiles for each row execute function public._profiles_nick_guard();

-- 검사 (쓸 수 있는지만): ok / short / long / bad / taken
create or replace function public._nick_check(p text, uid uuid) returns text language sql stable security definer set search_path = public as $$
  select case
    when p is null or char_length(btrim(p)) < 2 then 'short'
    when char_length(btrim(p)) > 12 then 'long'
    when btrim(p) !~ '^[0-9A-Za-z가-힣ㄱ-ㅎㅏ-ㅣ _.\-]+$' or btrim(p) ~ '\s\s' then 'bad'
    when exists (select 1 from profiles x where lower(btrim(x.nickname)) = lower(btrim(p)) and x.id <> coalesce(uid, '00000000-0000-0000-0000-000000000000'::uuid)) then 'taken'
    else 'ok' end
$$;

create or replace function public.nickname_check(p_nick text) returns text
language sql stable security definer set search_path = public as $$ select public._nick_check(p_nick, auth.uid()) $$;

create or replace function public.set_nickname(p_nick text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); n text := btrim(p_nick); r text;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('nick:' || lower(n)));
  r := _nick_check(n, uid);
  if r <> 'ok' then raise exception 'nick %', r; end if;
  perform set_config('app.nick_rpc', '1', true);
  insert into profiles (id, nickname, nick_set) values (uid, n, true)
    on conflict (id) do update set nickname = n, nick_set = true, updated_at = now();
  perform set_config('app.nick_rpc', '', true);
  return jsonb_build_object('ok', true, 'nickname', n);
exception when unique_violation then raise exception 'nick taken';
end $$;

revoke all on function public._nick_check(text, uuid) from public, anon, authenticated;
revoke all on function public.nickname_check(text), public.set_nickname(text) from public;
grant execute on function public.nickname_check(text) to authenticated;
grant execute on function public.set_nickname(text) to authenticated;


-- ===== SOURCE: nickname_v2.sql =====
-- 닉네임 v2: 금지어 · 두 번째 변경부터 심연석 200개. nickname.sql · gem.sql 다음에 실행. 여러 번 실행해도 안전.

-- 1) 금지어 (공백·기호 빼고 소문자로 비교, 단어가 포함되면 막음). 형님이 표에 줄을 더하거나 지워서 관리 가능
create table if not exists public.nick_banned (word text primary key check (word = lower(word) and char_length(word) between 1 and 20));
alter table public.nick_banned enable row level security;
revoke all on public.nick_banned from anon, authenticated;
insert into public.nick_banned (word) values
  ('시발'),('씨발'),('씨바'),('씨팔'),('시팔'),('쓰발'),('ㅅㅂ'),('ㅆㅂ'),('ㅅㅍ'),('병신'),('븅신'),('빙신'),('ㅂㅅ'),('좆'),('존나'),('졸라'),('ㅈㄴ'),
  ('개새'),('새끼'),('색기'),('ㅅㄲ'),('지랄'),('ㅈㄹ'),('미친놈'),('미친년'),('미친새'),('엠창'),('느금'),('니미'),('니애미'),('애미'),('애비'),('에미'),
  ('섹스'),('보지'),('자지'),('창녀'),('걸레'),('꼴린'),('따먹'),('강간'),('한남'),('김치녀'),('틀딱'),('운영자'),('관리자'),('운영진'),
  ('fuck'),('fuk'),('shit'),('bitch'),('asshole'),('dick'),('pussy'),('cunt'),('nigger'),('nigga'),('faggot'),('slut'),('whore'),
  ('porn'),('rape'),('admin'),('operator'),('gamemaster')
on conflict do nothing;

create or replace function public._nick_norm(p text) returns text language sql immutable as $$
  select regexp_replace(lower(coalesce(p, '')), '[\s_.\-0-9]', '', 'g') $$;

-- 2) 검사: ok / short / long / bad / banned / taken
create or replace function public._nick_check(p text, uid uuid) returns text language sql stable security definer set search_path = public as $$
  select case
    when p is null or char_length(btrim(p)) < 2 then 'short'
    when char_length(btrim(p)) > 12 then 'long'
    when btrim(p) !~ '^[0-9A-Za-z가-힣ㄱ-ㅎㅏ-ㅣ _.\-]+$' or btrim(p) ~ '\s\s' then 'bad'
    when exists (select 1 from nick_banned b where position(b.word in _nick_norm(p)) > 0) then 'banned'
    when exists (select 1 from profiles x where lower(btrim(x.nickname)) = lower(btrim(p)) and x.id <> coalesce(uid, '00000000-0000-0000-0000-000000000000'::uuid)) then 'taken'
    else 'ok' end
$$;
revoke all on function public._nick_check(text, uuid), public._nick_norm(text) from public, anon, authenticated;

-- 3) 변경: 처음(아직 직접 안 정함)은 무료, 이미 정한 뒤 바꾸면 심연석 200 (무료분 먼저, 같은 트랜잭션에서 차감)
create or replace function public._nick_price() returns int language sql immutable as $$ select 200 $$;
create or replace function public.set_nickname(p_nick text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); n text := btrim(p_nick); r text; was boolean; old text; cost int := 0; g jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('nick:' || lower(n)));
  select nick_set, nickname into was, old from profiles where id = uid for update;
  if coalesce(was, false) and old = n then raise exception 'nick same'; end if;
  r := _nick_check(n, uid);
  if r <> 'ok' then raise exception 'nick %', r; end if;
  if coalesce(was, false) then
    cost := _nick_price();
    begin g := _gem_spend(uid, cost, 'nickname', jsonb_build_object('from', old, 'to', n));
    exception when others then if sqlerrm ~ 'not enough' then raise exception 'nick gem'; else raise; end if; end;
  end if;
  perform set_config('app.nick_rpc', '1', true);
  insert into profiles (id, nickname, nick_set) values (uid, n, true)
    on conflict (id) do update set nickname = n, nick_set = true, updated_at = now();
  perform set_config('app.nick_rpc', '', true);
  return jsonb_build_object('ok', true, 'nickname', n, 'cost', cost);
exception when unique_violation then raise exception 'nick taken';
end $$;
revoke all on function public.set_nickname(text) from public, anon;
grant execute on function public.set_nickname(text) to authenticated;

-- 4) 로그인 안 한 사람(anon)은 닉네임 함수 못 씀 (Supabase 기본 권한이 anon 에게도 줘서 명시적으로 회수)
revoke execute on function public.nickname_check(text), public.set_nickname(text) from anon;
revoke execute on function public._nick_check(text, uuid), public._nick_norm(text), public._nick_price() from public, anon, authenticated;
grant execute on function public.nickname_check(text) to authenticated;


-- ===== SOURCE: rankings_v2.sql =====
-- 랭킹 v2: 시련의 탑 · 스토리 랭킹 (읽기 전용 함수 2개). 여러 번 실행해도 안전.
-- 닉네임·기록만 돌려주고 user_id 는 내보내지 않아요. 아케이드(rankings_weekly/all), PvP(pvp_rankings)는 기존 그대로 사용.

-- 1) 탑 랭킹: 탑별 최고 층 (같으면 먼저 도달한 사람이 위)
create or replace function public.tower_rankings(p_tower text default 'normal') returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); top jsonb; mine jsonb;
begin
  if p_tower not in ('normal', 'wind', 'ice', 'fire', 'light', 'dark') then raise exception 'bad tower'; end if;
  with t as (select g.user_id, g.best_floor, g.clears, rank() over (order by g.best_floor desc) rk, row_number() over (order by g.best_floor desc, g.updated_at) rn
             from tower_progress g where g.tower = p_tower and g.best_floor > 0)
  select coalesce(jsonb_agg(jsonb_build_object('rank', rk, 'name', coalesce(p.nickname, '플레이어'), 'floor', best_floor, 'me', t.user_id = uid) order by rn), '[]'::jsonb)
    into top from (select * from t order by rn limit 50) t left join profiles p on p.id = t.user_id;
  with t as (select g.user_id, g.best_floor, rank() over (order by g.best_floor desc) rk
             from tower_progress g where g.tower = p_tower and g.best_floor > 0)
  select jsonb_build_object('rank', rk, 'floor', best_floor) into mine from t where t.user_id = uid;
  return jsonb_build_object('top', top, 'me', mine);
end $$;

-- 2) 스토리 랭킹: 깬 페이즈 중 가장 먼 곳 (챕터 → 페이즈 순). 화면엔 '9-15' 처럼 표시
create or replace function public.story_rankings() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); top jsonb; mine jsonb;
begin
  with c as (
    select s.user_id, s.updated_at, (k.key)::int ch, max((v.value)::int) ph, count(*) n
      from story_progress s, jsonb_each(case when jsonb_typeof(s.data->'cleared') = 'object' then s.data->'cleared' else '{}'::jsonb end) k,
           jsonb_array_elements_text(case when jsonb_typeof(k.value) = 'array' then k.value else '[]'::jsonb end) v
     where k.key ~ '^[0-9]{1,3}$' and v.value ~ '^[0-9]{1,3}$'
     group by s.user_id, s.updated_at, k.key),
  b as (select distinct on (user_id) user_id, updated_at, ch, ph from c order by user_id, ch desc),
  tot as (select user_id, sum(n)::int total from c group by user_id),
  t as (select b.*, tot.total, rank() over (order by ch desc, ph desc) rk, row_number() over (order by ch desc, ph desc, tot.total desc, b.updated_at) rn
          from b join tot using (user_id))
  select coalesce((select jsonb_agg(jsonb_build_object('rank', rk, 'name', coalesce(p.nickname, '플레이어'), 'ch', ch, 'ph', ph, 'total', total, 'me', t.user_id = uid) order by rn)
                     from (select * from t order by rn limit 50) t left join profiles p on p.id = t.user_id), '[]'::jsonb),
         (select jsonb_build_object('rank', rk, 'ch', ch, 'ph', ph, 'total', total) from t where t.user_id = uid)
    into top, mine;
  return jsonb_build_object('top', top, 'me', mine);
end $$;

revoke all on function public.tower_rankings(text) from public;
revoke all on function public.story_rankings() from public;
grant execute on function public.tower_rankings(text) to anon, authenticated;
grant execute on function public.story_rankings() to anon, authenticated;


-- ===== SOURCE: rankings_v2_story_tie.sql =====
-- 스토리 랭킹 동점 처리 보강 (rankings_v2.sql 다음에 실행). 여러 번 실행해도 안전.
-- 순위: 가장 먼 챕터-페이즈 → 깬 페이즈 수 → 그 기록에 먼저 도달한 사람.
-- story_progress 에는 '언제 깼는지'가 없어서, 기록(챕터·페이즈·깬 수)이 올라간 시각을 따로 적어 둡니다.

create table if not exists public.story_rank_reach (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  ch int not null, ph int not null, total int not null,
  reached_at timestamptz not null default now());
alter table public.story_rank_reach enable row level security;   -- 정책 없음 = 직접 조회 불가 (아래 함수로만)
revoke all on public.story_rank_reach from anon, authenticated;

create or replace function public._story_best(d jsonb, out ch int, out ph int, out total int)
language sql immutable set search_path = public as $$
  with c as (select (k.key)::int ch, max((v.value)::int) ph, count(*)::int n
               from jsonb_each(case when jsonb_typeof(d->'cleared') = 'object' then d->'cleared' else '{}'::jsonb end) k,
                    jsonb_array_elements_text(case when jsonb_typeof(k.value) = 'array' then k.value else '[]'::jsonb end) v
              where k.key ~ '^[0-9]{1,3}$' and v.value ~ '^[0-9]{1,3}$' group by k.key)
  select (select c.ch from c order by c.ch desc limit 1), (select c.ph from c order by c.ch desc limit 1), (select coalesce(sum(n), 0)::int from c)
$$;

create or replace function public._story_reach_trg() returns trigger
language plpgsql security definer set search_path = public as $$
declare b record;
begin
  select * into b from _story_best(new.data);
  if b.ch is null then return new; end if;
  insert into story_rank_reach (user_id, ch, ph, total, reached_at) values (new.user_id, b.ch, b.ph, b.total, now())
  on conflict (user_id) do update set ch = excluded.ch, ph = excluded.ph, total = excluded.total, reached_at = now()
    where (story_rank_reach.ch, story_rank_reach.ph, story_rank_reach.total) is distinct from (excluded.ch, excluded.ph, excluded.total);
  return new;
end $$;
drop trigger if exists story_reach on public.story_progress;
create trigger story_reach after insert or update of data on public.story_progress for each row execute function public._story_reach_trg();

-- 기존 기록 채우기: 정확한 시각을 모르니 마지막 저장 시각으로 (이미 있으면 그대로)
insert into public.story_rank_reach (user_id, ch, ph, total, reached_at)
select s.user_id, b.ch, b.ph, b.total, s.updated_at from public.story_progress s, lateral public._story_best(s.data) b where b.ch is not null
on conflict (user_id) do nothing;

create or replace function public.story_rankings() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); top jsonb; mine jsonb;
begin
  with t as (select r.*, rank() over (order by ch desc, ph desc, total desc, reached_at) rk from story_rank_reach r)
  select coalesce((select jsonb_agg(jsonb_build_object('rank', rk, 'name', coalesce(p.nickname, '플레이어'), 'ch', ch, 'ph', ph, 'total', total, 'me', t.user_id = uid) order by rk)
                     from (select * from t order by rk limit 50) t left join profiles p on p.id = t.user_id), '[]'::jsonb),
         (select jsonb_build_object('rank', rk, 'ch', ch, 'ph', ph, 'total', total) from t where t.user_id = uid)
    into top, mine;
  return jsonb_build_object('top', top, 'me', mine);
end $$;
revoke all on function public.story_rankings() from public;
grant execute on function public.story_rankings() to anon, authenticated;
revoke all on function public._story_best(jsonb), public._story_reach_trg() from public, anon, authenticated;


-- ===== SOURCE: friends.sql =====
-- =====================================================================
-- 👥 친구 (1단계: 검색·신청·수락·거절·취소·삭제·목록·접속 상태) — 여러 번 실행해도 안전, 삭제 없음
-- 선행: schema.sql(profiles) · phaseE_2.sql(player_state, 레벨 표시용)
-- 친구 코드 = user id 앞 8자리 (대문자). 닉네임 부분 검색 또는 코드로 검색
-- 이후 친구 대전/리플레이 공유는 friendships(정렬된 쌍 a<b) 를 기준으로 붙이면 됨
-- 공개 RPC: friends_ping() · friends_list() · friends_search(q) · friend_request(user) · friend_respond(req_id, accept)
--           friend_cancel(req_id) · friend_remove(user) · friends_pending_count()
-- =====================================================================

create table if not exists public.friend_requests (
  id         bigint generated always as identity primary key,
  from_user  uuid not null references auth.users(id) on delete cascade,
  to_user    uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  check (from_user <> to_user),
  unique (from_user, to_user)
);
create index if not exists friend_requests_to_idx on public.friend_requests (to_user);
alter table public.friend_requests enable row level security;
revoke all on public.friend_requests from public, anon, authenticated;

-- 친구 관계: 한 쌍당 한 줄 (user_a < user_b). 친구 대전·리플레이 공유 시 참조
create table if not exists public.friendships (
  user_a     uuid not null references auth.users(id) on delete cascade,
  user_b     uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_a, user_b),
  check (user_a < user_b)
);
create index if not exists friendships_b_idx on public.friendships (user_b);
alter table public.friendships enable row level security;
revoke all on public.friendships from public, anon, authenticated;

-- 접속 기록 (클라이언트가 몇 분마다 friends_ping)
create table if not exists public.player_presence (
  user_id uuid primary key references auth.users(id) on delete cascade,
  seen_at timestamptz not null default now()
);
alter table public.player_presence enable row level security;
revoke all on public.player_presence from public, anon, authenticated;

create or replace function public._friend_cap() returns int language sql immutable as $$ select 50 $$;
create or replace function public._friend_code(p uuid) returns text language sql immutable as $$ select upper(left(replace(p::text, '-', ''), 8)) $$;
create or replace function public._is_friend(p1 uuid, p2 uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from friendships where user_a = least(p1, p2) and user_b = greatest(p1, p2)) $$;
create or replace function public._friend_count(p uuid) returns int language sql stable security definer set search_path = public as $$
  select count(*)::int from friendships where user_a = p or user_b = p $$;
create or replace function public._friend_card(p uuid) returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('user_id', p, 'code', _friend_code(p),
    'name', coalesce((select nickname from profiles where id = p), '플레이어'),
    'avatar', (select avatar_url from profiles where id = p),
    'level', coalesce((select level from player_state where user_id = p), 1),
    'seen_at', (select seen_at from player_presence where user_id = p),
    'online', coalesce((select seen_at > now() - interval '5 minutes' from player_presence where user_id = p), false)) $$;
revoke all on function public._is_friend(uuid, uuid), public._friend_count(uuid), public._friend_card(uuid) from public, anon, authenticated;

create or replace function public.friends_ping() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  insert into player_presence (user_id, seen_at) values (uid, now()) on conflict (user_id) do update set seen_at = now();
  return jsonb_build_object('ok', true, 'pending', (select count(*) from friend_requests where to_user = uid));
end $$;

create or replace function public.friends_pending_count() returns int language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  return (select count(*)::int from friend_requests where to_user = uid);
end $$;

create or replace function public.friends_list() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  insert into player_presence (user_id, seen_at) values (uid, now()) on conflict (user_id) do update set seen_at = now();
  return jsonb_build_object('ok', true, 'me', _friend_card(uid), 'cap', _friend_cap(),
    'friends', (select coalesce(jsonb_agg(_friend_card(o) || jsonb_build_object('since', f.created_at)
                 order by (select seen_at from player_presence where user_id = o) desc nulls last), '[]'::jsonb)
               from (select case when user_a = uid then user_b else user_a end o, created_at from friendships where user_a = uid or user_b = uid) f),
    'incoming', (select coalesce(jsonb_agg(_friend_card(r.from_user) || jsonb_build_object('req_id', r.id, 'at', r.created_at) order by r.id desc), '[]'::jsonb)
               from friend_requests r where r.to_user = uid),
    'outgoing', (select coalesce(jsonb_agg(_friend_card(r.to_user) || jsonb_build_object('req_id', r.id, 'at', r.created_at) order by r.id desc), '[]'::jsonb)
               from friend_requests r where r.from_user = uid));
end $$;

create or replace function public.friends_search(p_q text) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); q text := btrim(coalesce(p_q, ''));
begin
  if uid is null then raise exception 'login required'; end if;
  if char_length(q) < 2 then raise exception 'query too short'; end if;
  q := replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_');
  return (select coalesce(jsonb_agg(_friend_card(x.id) || jsonb_build_object(
      'state', case when _is_friend(uid, x.id) then 'friend'
                    when exists (select 1 from friend_requests where from_user = uid and to_user = x.id) then 'sent'
                    when exists (select 1 from friend_requests where from_user = x.id and to_user = uid) then 'received'
                    else 'none' end)), '[]'::jsonb)
    from (select p.id from profiles p
          where p.id <> uid and (p.nickname ilike '%' || q || '%' or (char_length(q) = 8 and _friend_code(p.id) = upper(q)))
          order by (_friend_code(p.id) = upper(q)) desc, (p.nickname = btrim(p_q)) desc, char_length(p.nickname) limit 20) x);
end $$;

create or replace function public.friend_request(p_user uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); rid bigint;
begin
  if uid is null then raise exception 'login required'; end if;
  if p_user is null or p_user = uid then raise exception 'invalid user'; end if;
  if not exists (select 1 from profiles where id = p_user) then raise exception 'invalid user'; end if;
  perform pg_advisory_xact_lock(hashtext('friend:' || least(uid, p_user)::text || greatest(uid, p_user)::text));
  if _is_friend(uid, p_user) then raise exception 'already friends'; end if;
  -- 상대가 이미 나에게 신청했다면 바로 수락
  select id into rid from friend_requests where from_user = p_user and to_user = uid;
  if rid is not null then return friend_respond(rid, true); end if;
  if _friend_count(uid) >= _friend_cap() then raise exception 'friend cap'; end if;
  if (select count(*) from friend_requests where from_user = uid) >= 50 then raise exception 'too many requests'; end if;
  insert into friend_requests (from_user, to_user) values (uid, p_user) on conflict do nothing;
  return jsonb_build_object('ok', true, 'state', 'sent');
end $$;

create or replace function public.friend_respond(p_req bigint, p_accept boolean) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); r friend_requests;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into r from friend_requests where id = p_req and to_user = uid;
  if r.id is null then raise exception 'request not found'; end if;
  perform pg_advisory_xact_lock(hashtext('friend:' || least(r.from_user, uid)::text || greatest(r.from_user, uid)::text));
  delete from friend_requests where id = r.id;
  if not coalesce(p_accept, false) then return jsonb_build_object('ok', true, 'state', 'declined'); end if;
  if _friend_count(uid) >= _friend_cap() then raise exception 'friend cap'; end if;
  if _friend_count(r.from_user) >= _friend_cap() then raise exception 'their friend cap'; end if;
  insert into friendships (user_a, user_b) values (least(uid, r.from_user), greatest(uid, r.from_user)) on conflict do nothing;
  delete from friend_requests where from_user = uid and to_user = r.from_user;
  return jsonb_build_object('ok', true, 'state', 'friend');
end $$;

create or replace function public.friend_cancel(p_req bigint) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  delete from friend_requests where id = p_req and from_user = uid;
  if not found then raise exception 'request not found'; end if;
  return jsonb_build_object('ok', true, 'state', 'none');
end $$;

create or replace function public.friend_remove(p_user uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  delete from friendships where user_a = least(uid, p_user) and user_b = greatest(uid, p_user);
  if not found then raise exception 'not friends'; end if;
  return jsonb_build_object('ok', true, 'state', 'none');
end $$;

revoke all on function public.friends_ping(), public.friends_pending_count(), public.friends_list(), public.friends_search(text),
  public.friend_request(uuid), public.friend_respond(bigint, boolean), public.friend_cancel(bigint), public.friend_remove(uuid) from public, anon;
grant execute on function public.friends_ping(), public.friends_pending_count(), public.friends_list(), public.friends_search(text),
  public.friend_request(uuid), public.friend_respond(bigint, boolean), public.friend_cancel(bigint), public.friend_remove(uuid) to authenticated;


-- ===== SOURCE: friend_battle.sql =====
-- =====================================================================
-- ⚔️ 친구 대전 (2단계) — 여러 번 실행해도 안전, 삭제 없음
-- 선행: friends.sql(friendships, _is_friend) · pvp.sql(pvp_decks, _pvp_snap, _pvp_day) · manual_battle.sql(_battle_acts_ok)
-- 방식: 기존 PvP 와 같은 비동기. 상대 = 친구의 PvP 방어 덱(무제한 리그) 스냅샷, 서버 seed 발급
-- 레이팅·랭킹·보상 없음. 하루 20회(KST). 결과 + seed + 양쪽 스냅샷 + 수동 행동 기록 저장 → 3단계 리플레이 공유가 이 행(id)을 참조
-- 공개 RPC: friend_battle_start(p_friend uuid, p_mode text) · friend_battle_report(p_id bigint, p_wins int, p_losses int, p_actions jsonb)
--           friend_battle_history(p_friend uuid default null)
-- =====================================================================

create table if not exists public.friend_battles (
  id          bigint generated always as identity primary key,
  user_id     uuid not null references auth.users(id) on delete cascade,   -- 도전한 사람
  opp_user    uuid not null references auth.users(id) on delete cascade,   -- 친구 (방어 덱)
  mode        text not null check (mode in ('1v1','3v3')),
  day         date not null,
  seed        bigint not null,
  my_snap     jsonb not null,
  opp_snap    jsonb not null,
  manual      boolean not null default false,
  actions     jsonb,                                                       -- 수동 전투 행동 기록 (리플레이용)
  created_at  timestamptz not null default now(),
  reported_at timestamptz, wins smallint, losses smallint, win boolean
);
create index if not exists friend_battles_user_idx on public.friend_battles (user_id, created_at desc);
create index if not exists friend_battles_opp_idx on public.friend_battles (opp_user, created_at desc);
alter table public.friend_battles enable row level security;
revoke all on public.friend_battles from public, anon, authenticated;

create or replace function public._fb_daily_max() returns int language sql immutable as $$ select 20 $$;

create or replace function public.friend_battle_start(p_friend uuid, p_mode text default '1v1') returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); n int; used int; mine jsonb := '[]'::jsonb; osnap jsonb; d record; seed bigint; aid bigint; oname text;
begin
  if uid is null then raise exception 'login required'; end if;
  if p_mode not in ('1v1','3v3') then raise exception 'bad mode'; end if;
  n := _pvp_ok('open', p_mode);
  if p_friend is null or not _is_friend(uid, p_friend) then raise exception 'not friends'; end if;
  perform pg_advisory_xact_lock(hashtext('fb:' || uid::text));
  select count(*) into used from friend_battles where user_id = uid and day = _pvp_day();
  if used >= _fb_daily_max() then raise exception 'no attempts left'; end if;
  if (select count(*) from pvp_decks where user_id = uid and league = 'open' and mode = p_mode) < n then raise exception 'deck required'; end if;
  if (select count(*) from pvp_decks where user_id = p_friend and league = 'open' and mode = p_mode and slot < n) < n then raise exception 'friend deck missing'; end if;
  for d in select * from pvp_decks where user_id = uid and league = 'open' and mode = p_mode and slot < n order by slot loop
    mine := mine || jsonb_build_array(_pvp_snap(uid, d.uids, 'open')->'cards');
  end loop;
  select coalesce(jsonb_agg(snap order by slot), '[]'::jsonb) into osnap from pvp_decks where user_id = p_friend and league = 'open' and mode = p_mode and slot < n;
  oname := coalesce((select nickname from profiles where id = p_friend), '플레이어');
  seed := floor(random() * 2147483647)::bigint;
  insert into friend_battles (user_id, opp_user, mode, day, seed, my_snap, opp_snap)
  values (uid, p_friend, p_mode, _pvp_day(), seed, mine, osnap) returning id into aid;
  return jsonb_build_object('id', aid, 'seed', seed, 'mode', p_mode, 'me', mine, 'opp', osnap, 'opp_name', oname, 'opp_user', p_friend,
    'left', _fb_daily_max() - used - 1);
end $$;

create or replace function public.friend_battle_report(p_id bigint, p_wins int, p_losses int, p_actions jsonb default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); a friend_battles; need int; v_win boolean; x jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  select * into a from friend_battles where id = p_id and user_id = uid for update;
  if a.id is null then raise exception 'not found'; end if;
  if a.reported_at is not null then raise exception 'already reported'; end if;
  if now() - a.created_at > interval '1 hour' then raise exception 'expired'; end if;
  need := case when a.mode = '3v3' then 2 else 1 end;
  if p_wins is null or p_losses is null or p_wins < 0 or p_losses < 0 or p_wins > need or p_losses > need
     or not (p_wins = need or p_losses = need) or (p_wins = need and p_losses = need) then raise exception 'bad result'; end if;
  if p_actions is not null and jsonb_typeof(p_actions) <> 'null' then
    if jsonb_typeof(p_actions) <> 'array' or jsonb_array_length(p_actions) > 3 or octet_length(p_actions::text) > 131072 then raise exception 'bad actions'; end if;
    for x in select value from jsonb_array_elements(p_actions) loop
      if not _battle_acts_ok(x, 20 * 6 + 5) then raise exception 'bad actions'; end if;
    end loop;
  else p_actions := null; end if;
  v_win := p_wins = need;
  update friend_battles set reported_at = now(), wins = p_wins, losses = p_losses, win = v_win, actions = p_actions, manual = p_actions is not null where id = a.id;
  return jsonb_build_object('ok', true, 'id', a.id, 'win', v_win, 'record', (
    select jsonb_build_object('w', count(*) filter (where (user_id = uid and win) or (opp_user = uid and not win)),
                              'l', count(*) filter (where (user_id = uid and not win) or (opp_user = uid and win)))
    from friend_battles where reported_at is not null and ((user_id = uid and opp_user = a.opp_user) or (user_id = a.opp_user and opp_user = uid))));
end $$;

-- 전적: p_friend 를 주면 그 친구와의 기록 (공격·방어 모두), 없으면 친구별 승패 요약
create or replace function public.friend_battle_history(p_friend uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  if p_friend is null then
    return jsonb_build_object('ok', true, 'left', greatest(0, _fb_daily_max() - (select count(*) from friend_battles where user_id = uid and day = _pvp_day())::int),
      'records', (select coalesce(jsonb_object_agg(o, jsonb_build_object('w', w, 'l', l)), '{}'::jsonb) from (
        select case when user_id = uid then opp_user else user_id end o,
               count(*) filter (where (user_id = uid and win) or (opp_user = uid and not win)) w,
               count(*) filter (where (user_id = uid and not win) or (opp_user = uid and win)) l
        from friend_battles where reported_at is not null and (user_id = uid or opp_user = uid) group by 1) t));
  end if;
  if not _is_friend(uid, p_friend) then raise exception 'not friends'; end if;
  return jsonb_build_object('ok', true, 'battles', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'attack', user_id = uid, 'mode', mode,
      'win', case when user_id = uid then win else not win end, 'wins', wins, 'losses', losses, 'manual', manual, 'at', created_at) order by id desc), '[]'::jsonb)
    from (select * from friend_battles where reported_at is not null and ((user_id = uid and opp_user = p_friend) or (user_id = p_friend and opp_user = uid))
          order by id desc limit 30) b));
end $$;

revoke all on function public.friend_battle_start(uuid, text), public.friend_battle_report(bigint, int, int, jsonb), public.friend_battle_history(uuid) from public, anon;
grant execute on function public.friend_battle_start(uuid, text), public.friend_battle_report(bigint, int, int, jsonb), public.friend_battle_history(uuid) to authenticated;


-- ===== SOURCE: daily.sql =====
-- =====================================================================
-- 📅 일일 미션 + 출석 보상 — Supabase SQL Editor 에서 실행. 여러 번 실행해도 안전
-- 선행: phaseE_1.sql(_wallet_add) · gem.sql(_gem_add, _gem_day) · story_gacha.sql(소환권)
-- 초기화: 한국 시간 00:00 (_gem_day). 보상 지급은 전부 서버 (클라이언트는 미션 키만 보냄)
-- 진행 기록은 클라이언트가 전투 끝에 daily_track 으로 알림 → 서버가 목표치에서 잘라 저장 (1회 호출당 상한)
-- 공개 RPC: daily_status() · daily_track(kind, n) · daily_claim(key) · attend_claim()
-- 확인용: select public.daily_status();
-- =====================================================================

create table if not exists public.daily_progress (
  user_id uuid not null references auth.users(id) on delete cascade,
  day     date not null,
  prog    jsonb not null default '{}'::jsonb,   -- { win: 2, skill: 7, ... }
  claimed jsonb not null default '[]'::jsonb,   -- ["win","all",...]
  primary key (user_id, day)
);
alter table public.daily_progress enable row level security;
revoke all on public.daily_progress from public, anon, authenticated;

create table if not exists public.daily_attend (
  user_id  uuid primary key references auth.users(id) on delete cascade,
  last_day date,
  step     int not null default 0,   -- 이번 주기에서 받은 날 수 (0~7)
  total    int not null default 0
);
alter table public.daily_attend enable row level security;
revoke all on public.daily_attend from public, anon, authenticated;

-- 미션 정의 (한 곳에서 조정). per = daily_track 1회 호출로 올릴 수 있는 최대
create or replace function public._daily_defs() returns jsonb language sql immutable as $$ select '[
  {"key":"arcade","name":"아케이드 1판 플레이","goal":1,"per":1,"reward":{"gold":1000}},
  {"key":"win","name":"전투 3회 승리","goal":3,"per":1,"reward":{"gold":2000}},
  {"key":"story","name":"스토리 스테이지 2회 클리어","goal":2,"per":1,"reward":{"gold":2000,"gem":10}},
  {"key":"tower","name":"시련의 탑 1회 도전","goal":1,"per":1,"reward":{"gold":1500,"gem":10}},
  {"key":"skill","name":"고유기술 10회 사용","goal":10,"per":20,"reward":{"gold":1500}}
]'::jsonb $$;
create or replace function public._daily_all_reward() returns jsonb language sql immutable as $$ select '{"gem":30}'::jsonb $$;
-- 출석 7일 주기 (빠진 날이 있어도 끊기지 않고 다음 칸으로. 7일째 받으면 1일째부터 다시)
create or replace function public._attend_defs() returns jsonb language sql immutable as $$ select '[
  {"gold":3000},{"gem":20},{"gold":5000},{"gem":30},{"tickets":1},{"gold":10000},{"gem":100,"tickets":2}
]'::jsonb $$;

create or replace function public._daily_grant(p_uid uuid, p_rw jsonb, p_reason text, p_ref text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare res jsonb := '{}'::jsonb; t int;
begin
  if coalesce((p_rw->>'gold')::int, 0) > 0 then res := res || jsonb_build_object('wallet', _wallet_add(p_uid, jsonb_build_object('gold', (p_rw->>'gold')::int), p_reason)); end if;
  if coalesce((p_rw->>'gem')::int, 0) > 0 then perform _gem_add(p_uid, (p_rw->>'gem')::int, 0, p_reason, p_ref, jsonb_build_object('ref', p_ref)); end if;
  if coalesce((p_rw->>'tickets')::int, 0) > 0 then
    insert into story_gacha (user_id, last_draw) values (p_uid, _gem_day() - 1) on conflict (user_id) do nothing;
    update story_gacha set tickets = tickets + (p_rw->>'tickets')::int, updated_at = now() where user_id = p_uid returning tickets into t;
    res := res || jsonb_build_object('tickets', t);
  end if;
  return res;
end $$;

create or replace function public._daily_json(p_uid uuid) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare dp daily_progress; a daily_attend; today date := _gem_day(); done int;
begin
  select * into dp from daily_progress where user_id = p_uid and day = today;
  select * into a from daily_attend where user_id = p_uid;
  select count(*) into done from jsonb_array_elements(_daily_defs()) m where coalesce((dp.prog->>(m->>'key'))::int, 0) >= (m->>'goal')::int;
  return jsonb_build_object('ok', true, 'day', today,
    'next_reset', ((today + 1)::timestamp at time zone 'Asia/Seoul'),
    'missions', (select jsonb_agg(m || jsonb_build_object('prog', least((m->>'goal')::int, coalesce((dp.prog->>(m->>'key'))::int, 0)),
                   'claimed', coalesce(dp.claimed, '[]'::jsonb) ? (m->>'key'))) from jsonb_array_elements(_daily_defs()) m),
    'all', jsonb_build_object('reward', _daily_all_reward(), 'done', done, 'goal', jsonb_array_length(_daily_defs()), 'claimed', coalesce(dp.claimed, '[]'::jsonb) ? 'all'),
    'attend', jsonb_build_object('rewards', _attend_defs(), 'step', case when coalesce(a.step, 0) >= 7 and a.last_day < today then 0 else coalesce(a.step, 0) end,
                   'today', a.last_day = today, 'total', coalesce(a.total, 0)));
end $$;
revoke all on function public._daily_grant(uuid, jsonb, text, text), public._daily_json(uuid) from public, anon, authenticated;

create or replace function public.daily_status() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'login required'; end if;
  return _daily_json(uid);
end $$;

create or replace function public.daily_track(p_kind text, p_n int default 1) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m jsonb; today date := _gem_day(); cur int; nv int;
begin
  if uid is null then raise exception 'login required'; end if;
  select x into m from jsonb_array_elements(_daily_defs()) x where x->>'key' = p_kind;
  if m is null then raise exception 'invalid kind'; end if;
  perform pg_advisory_xact_lock(hashtext('daily:' || uid::text));
  insert into daily_progress (user_id, day) values (uid, today) on conflict do nothing;
  select coalesce((prog->>p_kind)::int, 0) into cur from daily_progress where user_id = uid and day = today;
  nv := least((m->>'goal')::int, cur + greatest(0, least(coalesce(p_n, 1), (m->>'per')::int)));
  if nv <> cur then update daily_progress set prog = prog || jsonb_build_object(p_kind, nv) where user_id = uid and day = today; end if;
  return jsonb_build_object('ok', true, 'kind', p_kind, 'prog', nv, 'goal', (m->>'goal')::int);
end $$;

create or replace function public.daily_claim(p_key text) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); m jsonb; today date := _gem_day(); dp daily_progress; rw jsonb; res jsonb; done int;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('daily:' || uid::text));
  perform pg_advisory_xact_lock(hashtext('gem:' || uid::text));
  insert into daily_progress (user_id, day) values (uid, today) on conflict do nothing;
  select * into dp from daily_progress where user_id = uid and day = today for update;
  if dp.claimed ? p_key then raise exception 'already claimed'; end if;
  if p_key = 'all' then
    select count(*) into done from jsonb_array_elements(_daily_defs()) x where coalesce((dp.prog->>(x->>'key'))::int, 0) >= (x->>'goal')::int;
    if done < jsonb_array_length(_daily_defs()) then raise exception 'not done'; end if;
    rw := _daily_all_reward();
  else
    select x into m from jsonb_array_elements(_daily_defs()) x where x->>'key' = p_key;
    if m is null then raise exception 'invalid key'; end if;
    if coalesce((dp.prog->>p_key)::int, 0) < (m->>'goal')::int then raise exception 'not done'; end if;
    rw := m->'reward';
  end if;
  update daily_progress set claimed = claimed || to_jsonb(p_key) where user_id = uid and day = today;
  res := _daily_grant(uid, rw, 'daily', 'daily:' || today || ':' || p_key);
  return _daily_json(uid) || res || jsonb_build_object('got', rw);
end $$;

create or replace function public.attend_claim() returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); today date := _gem_day(); a daily_attend; st int; rw jsonb; res jsonb;
begin
  if uid is null then raise exception 'login required'; end if;
  perform pg_advisory_xact_lock(hashtext('daily:' || uid::text));
  perform pg_advisory_xact_lock(hashtext('gem:' || uid::text));
  insert into daily_attend (user_id) values (uid) on conflict do nothing;
  select * into a from daily_attend where user_id = uid for update;
  if a.last_day = today then raise exception 'already claimed'; end if;
  st := case when a.step >= 7 then 1 else a.step + 1 end;
  rw := _attend_defs()->(st - 1);
  update daily_attend set last_day = today, step = st, total = total + 1 where user_id = uid;
  res := _daily_grant(uid, rw, 'attend', 'attend:' || today);
  return _daily_json(uid) || res || jsonb_build_object('got', rw, 'got_day', st);
end $$;

revoke all on function public.daily_status(), public.daily_track(text, int), public.daily_claim(text), public.attend_claim() from public, anon;
grant execute on function public.daily_status(), public.daily_track(text, int), public.daily_claim(text), public.attend_claim() to authenticated;


-- ===== SOURCE: dispatch.sql =====
-- 파견 (배척지 001~009 · 안전지대 B~SS). 선행: phaseE_1/2(지갑·플레이어 레벨) · gem.sql · gacha.sql(story_gacha.tickets) · trade_drink.sql(_item_add). 여러 번 실행해도 안전.
-- 규칙 요약
--  * 매일 0시(KST) 의뢰 6개(배척지 4 · 안전지대 2) 무작위. 새로고침: 하루 3번 무료 → 심연석 20/30/40/50(이후 50)
--  * 필수 = 등급만(보낸 카드 중 1장 이상이 그 등급 이상). 속성·클래스 맞는 카드 1장당 +15%(속성·클래스 따로, 최대 +60%), 필수보다 높은 등급 카드 있으면 +10%
--  * 보너스 최대(+60%)면 10% 확률 대성공(보상 2배). 보상·확률·종료 시각은 출발할 때 서버가 정해 둠
--  * 시간 1/4/8/12시간 = 1시간 보상 × 1 / 3.5 / 6 / 8.5
--  * 동시 진행 슬롯: 플레이어 Lv1~29 = 3, 30~59 = 4, 60~ = 5. 하루 출발 최대 12번
--  * 한 카드(uid)는 진행 중인 파견 하나에만. 덱·스토리·PvP 사용은 막지 않음. MR·LR 카드는 아직 파견 불가

-- 1) 카드 정보 (등급 0=N 1=R 2=HR 3=SR 4=UR 5=MR 6=LR · 속성 · 클래스). data/cards.csv · npc_cards.csv 에서 생성
