  ('x005', 'exile', '배척지 005', 5, 2, 3, '{"shard":14,"blood":10,"soul":0.8}'),
  ('x006', 'exile', '배척지 006', 6, 2, 3, '{"shard":16,"blood":12,"soul":1}'),
  ('x007', 'exile', '배척지 007', 7, 3, 3, '{"shard":18,"blood":14,"soul":1.5,"gem":0.2}'),
